(window.GIM_TS=window.GIM_TS||{})["Keritot.0"]={"from":0,"a":[["\u0003שלשים ושש כריתות\u0004 עבירות שעונשן כרת יש \u0003בתורה: הבא על האם\u0004 (על אמו), \u0003ועל אשת אב\u0004 אף על פי שאינה אמו, \u0003ועל הכלה,\u0004 אשת בנו, \u0003הבא על הזכור\u0004 במשכב זכר, \u0003ו\u0004כן הבא \u0003על הבהמה, ו\u0004כן \u0003אשה המביאה הבהמה עליה, הבא על אשה ובתה, ו\u0004הבא על \u0003אשת איש, הבא על אחותו, ועל אחות אביו, ועל אחות אמו, ועל אחות אשתו\u0004 בחיי אשתו, \u0003ועל אשת אחיו, ועל אשת אחי אביו, ועל אשת אחי אמו, ו\u0004הבא \u0003על הנדה.\u0004","\u0003והמגדף\u0004 שם שמים, \u0003ועובד עבודה זרה, והנותן מזרעו\u0004 (מבניו או מבנותיו) \u0003ל\u0004עבודת ה\u0003מולך\u0004 (ראה ויקרא ב, א—ה), \u0003ובעל אוב\u0004 שמעלה את רוח המת (שם ו), \u0003ומחלל שבת. וטמא שאכל קדש, ו\u0004כן \u0003הבא אל המקדש טמא. והאוכל חלב\u0004 (שומן האסור באכילה), \u0003ו\u0004האוכל \u0003דם, ו\u0004האוכל \u0003נותר\u0004 מן הקרבנות לאחר שעבר זמן אכילתם, \u0003ו\u0004האוכל \u0003פיגול\u0004 מבשר קרבן שהכהן עשה את עבודתו על דעת שיקרב או ייאכל לאחר זמנו. \u0003והשוחט\u0004 זבחים מחוץ לבית המקדש, \u0003ו\u0004כן ה\u0003מעלה\u0004 אותם על מזבח \u0003בחוץ.\u0004","\u0003והאוכל חמץ בפסח, והאוכל\u0004 (או שותה) ביום הכיפורים, \u0003והעושה מלאכה ביום הכפורים, והמפטם\u0004 (הרוקח) \u0003את השמן\u0004 בבשמים כעין שמן המשחה שעשה משה במדבר למשיחת כלי המשכן (ראה שמות ל, כב—לג), \u0003והמפטם את הקטרת\u0004 כעשייתה במקדש, שלא לצורך המקדש, \u0003והסך את השמן המשחה\u0004 על גבי גופו שלא כדין. \u0003ו\u0004כן חייבים כרת מי שלא עשה את \u0003הפסח, ו\u0004מי שביטל את מצות \u0003המילה,\u0004 ושתי אלה הן \u0003מצו‍ת עשה,\u0004 בעוד שכל שאר העבירות שמנינו הן מצוות לא תעשה.","\u0003על אלו\u0004 מצוות לא תעשה שמנינו, \u0003חייבין על זדונו\u0004 אם עשה אותם במזיד — \u0003כרת, ועל שגגתו\u0004 אם עשה אותם בשגגה — חייב \u0003חטאת, ועל לא הודע שלהם\u0004 כאשר הוא מסופק אם עבר עבירה זו או לא — מביא \u0003אשם תלוי\u0004 (ראה ויקרא ה, יז—יט) התולה ומכפר לו עד שייוודע לו אם אכן חטא, \u0003חוץ מן המטמא מקדש וקדשיו,\u0004 שאינו מביא אשם תלוי, \u0003מפני שהוא\u0004 אינו מביא חטאת קבועה על שגגתו, כלומר, כבשה או עז, אלא דינו \u0003בעולה ויורד,\u0004 שסוג הקרבן שהוא מביא על חטאו תלוי ביכולתו הכספית (ראה שם א—יג), ואין אשם תלוי בא אלא על דבר שקרבנו חטאת קבועה (להלן כה,ב), אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: אף המגדף\u0004 אינו מביא חטאת ולא אשם תלוי, מפני \u0003שנאמר\u0004 בענין החטאת: \u0003\"תורה אחת יהיה לכם לעשה בשגגה\"\u0004 (במדבר טו, כט), \u0003יצא מגדף שאינו עושה מעשה,\u0004 אלא חוטא בדיבור בלבד."],["שנינו במשנה: שלושים ושש כריתות בתורה. ושואלים: \u0003מניינא\u0004 \u0005[המנין]\u0006\u0003 למה לי?\u0004 הרי כולן מפורשות במשנה! \u0003אמר ר' יוחנן:\u0004 בא הדבר ללמד \u0003ש\u0004גם \u0003אם עשאן כולן בהעלם אחת\u0004 בשגגה אחת, ששכח, או שלא ידע שמעשים אלו אסורים, ולא נודע לו בין מעשה למעשה, ש\u0003חייב\u0004 חטאת \u0003על כל אחת ואחת,\u0004 שלושים ושש חטאות.","ואגב זה שואלים: \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הא דתנן\u0004 \u0005[זו ששנינו]\u0006 במסכת שבת: \u0003אבות מלאכות\u0004 האסורות בשבת \u0003ארבעים חסר אחת,\u0004 גם שם \u0003מניינא\u0004 \u0005[המנין]\u0006 \u0003למה לי?\u0004 ומשיבים: לומר \u0003שאם עשאן כולן בהעלם אחת,\u0004 שנעלם ממנו שכולן אסורות, מכיון שהן מלאכות חלוקות — \u0003חייב\u0004 להביא קרבן חטאת \u0003על כל אחת ואחת.\u0004","ושואלים: \u0003תו, הא דתנן\u0004 \u0005[ועוד, זו ששנינו\u0006 במשנה]: \u0003ארבעה מחוסרי כפרה\u0004 הם שצריכים להביא קרבן לאחר שנטהרו מטומאתם, כדי להיטהר לגמרי ולהיות ראויים לאכול בשר קדשים: הזב והזבה והיולדת והמצורע, \u0003מניינא\u0004 \u0005[המנין]\u0006 \u0003למה לי\u0004 שם?","ומשיבים: מנין זה הוא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' אליעזר בן יעקב,\u0004 ש\u0003אמר: חמשה הוי\u0004 \u0005[הם],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כך \u0005שנויה\u0006 משנה\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר:\u0004 גם \u0003גר\u0004 הוא \u0003מחוסר כפרה עד שיזרק דם\u0004 קרבנו \u0003עליו\u0004 (עבורו), שנוסף למילה וטבילה צריך הוא להביא קרבן, וכל עוד לא הביא קרבן אינו נחשב כישראל גמור המותר לאכול בשר קדשים, \u0003אהכי תנא\u0004 \u0005[משום כך שנה]\u0006 \u0003ארבעה,\u0004 לומר שגר אינו בכלל זה.","ושואלים \u0003תו, הא דתנן\u0004 \u0005[ועוד, זו ששנינו\u0006 במשנה]: \u0003ארבעה מביאין\u0004 קרבן \u0003על הזדון כ\u0004פי שמביאים על ה\u0003שגגה:\u0004 הבא על השפחה, ונזיר שנטמא, ועל שבועת העדות, ועל שבועת הפקדון, \u0003מניינא\u0004 \u0005[המנין]\u0006 \u0003למה לי\u0004 שם?","ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006\u0003 מ\u0004דברי ר' \u0003שמעון, דתניא\u0004 \u0005[ששנויה ברייתא],\u0006 \u0003ר' שמעון אומר: שבועת הפקדון,\u0004 שנשבע לשקר שלא הופקד פקדון בידו — \u0003לא ניתן זדונה לכפרה,\u0004 שאין מביאים קרבן על זדונה, \u0003אהכי תנא\u0004 \u0005[משום כך שנה]\u0006 \u0003ארבעה,\u0004 להדגיש שאף שבועת הפקדון בכלל.","ושואלים: \u0003תו, הא דתנן\u0004 \u0005[ועוד, זו ששנינו\u0006 במשנה]: \u0003חמשה מביאין קרבן אחד על עבירות הרבה, מניינא\u0004 \u0005[המנין]\u0006 \u0003למה לי?\u0004","ומשיבים: \u0003משום דקא בעי למיתנא סיפא\u0004 \u0005[שהוא רוצה לשנות בסוף]:\u0006 \u0003נזיר אם נטמא טומאות הרבה\u0004 (פעמים רבות) במהלך נזירות אחת, \u0003ומשכחת לה\u0004 \u0005[ואתה מוצא אותה]\u0006 שנטמא טומאות הרבה — \u0003כגון\u0004 נזיר שנטמא ונטהר, \u0003דאיטמי\u0004 \u0005[ש\u0006חזר ו\u0005נטמא] ב\u0006יום ה\u0003שביעי\u0004 של ימי הטהרה מטומאתו, \u0003וחזר ונטמא\u0004 שוב ביום ה\u0003שביעי\u0004 לימי הטהרה הנוספים. \u0003ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' יוסי בר' יהודה היא,\u0004 ש\u0003אמר: נזירות טהרה\u0004 שצריך לחזור ולנהוג לאחר שנטהר, \u0003מן\u0004 יום ה\u0003שביעי\u0004 לטהרתו \u0003הוא דחייל עליה\u0004 \u0005[שחלה עליו],\u0006 שזה הוא יומה הראשון.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003תאמר\u0004 שיטת \u0003רבי היא, כיון\u0004 שלשיטתו \u0003נזירות\u0004 של \u0003טהרה עד\u0004 היום ה\u0003שמיני לא חיילא עליה\u0004 \u0005[לא חלה עליו],\u0006 \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]\u0006 שייחשב כנטמא טומאות הרבה בנזירות אחת?","\u0003אי\u0004 \u0005[אם]\u0006 ש\u0003נטמא ב\u0004יום ה\u0003שביעי\u0004 ונטהר \u0003וחזר ונטמא בשביעי\u0004 — \u0003כולה חדא טומאה אריכתא\u0004 \u0005[טומאה אחת ארוכה]\u0006 \u0003היא,\u0004 שהרי עדיין לא נטהר לגמרי,","\u0003ואי\u0004 \u0005[ואם]\u0006 מדובר במקרה ש\u0003נטמא ב\u0004יום ה\u0003שמיני וחזר ונטמא בשמיני,\u0004 והרי \u0003כיון\u0004 ש\u0003יצא\u0004 והגיע \u0003בשעה הראויה להביא בה קרבן\u0004 על טומאתו, הרי יצא לגמרי מכלל חובת קרבן הטומאה הקודם, ו\u0003חייב על כל אחת ואחת\u0004 מן הנזירויות קרבן טומאה, ואין זו אותה נזירות שנטמא בה! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שדברי \u0003רבי יוסי בר' יהודה היא.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006\u0003 שאמר רבי, ומאי\u0004 \u0005[ומהו]\u0006 שאמר \u0003ר' יוסי בר' יהודה? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בנזיר שנטמא ונטהר \u0003\"וקדש את ראשו ביום ההוא\"\u0004 (במדבר ו, יא), שמתחיל נזירות מחדש, כוונתו — \u0003ביום הבאת קרבנותיו,\u0004 שהוא היום השמיני לטהרתו, אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר:\u0004 הכוונה היא \u0003ביום תגלחתו,\u0004 שהוא היום השביעי לטהרתו.","ושואלים: \u0003תו, הא דתנן\u0004 \u0005[ועוד, זו ששנינו\u0006 במשנה]: \u0003חמשה\u0004 כלומר, על חמש עבירות \u0003מביאין קרבן עולה ויורד\u0004 לפי רמתו הכלכלית של המביא, \u0003מניינא\u0004 \u0005[המנין]\u0006 \u0003למה לי?\u0004","ומשיבים: \u0003משום דקתני סיפא\u0004 \u0005[ששנה בסוף,\u0006 במשנה אחרת\u0005]:\u0006 בית דין, שהתירו בשוגג אחת מן העבירות הללו אינם מביאים קרבן עולה ויורד, ו\u0003נשיא כיוצא בהן,\u0004 שגם הוא אינו מביא כלל קרבן עולה ויורד. ומשום כך הוא שונה \u0003חמשה, לאפוקי\u0004 \u0005[להוציא] מ\u0006\u0003דברי ר' אליעזר,\u0004 שאמר: על טומאת מקדש וקדשיו, שהיא אחת מעבירות אלו, \u0003נשיא מביא שעיר,\u0004 חטאת קבועה, כפי שמביא על שאר חטאותיו, ואינו מביא קרבן עולה ויורד.","\u0003תו, הא דתנן\u0004 \u0005[ועוד, זו ששנינו\u0006 במשנה]: \u0003ארבעה אבות נזיקין, מנינא\u0004 \u0005[מנין]\u0006 \u0003למה לי?\u0004","ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא] מ\u0006\u0003דברי ר' אושעיא,\u0004 שאמר: \u0003שלשה עשר אבות נזיקין הן.\u0004 ושואלים: ולדברי ר' \u0003אושעיא מניינא\u0004 \u0005[מנין]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006\u0003 מ\u0004דברי ר' \u0003חייא,\u0004 שאמר: \u0003עשרים וארבעה אבות נזיקין.\u0004 ושואלים: ולדעת ר' \u0003חייא מנינא\u0004 \u0005[מנין]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מסור\u0004 (מלשין ומוסר ממון חבירו לגוי או לאנס) \u0003ומפגל\u0004 בקדשים, שאף לשיטתו אין מונים אותם בין אבות נזיקין.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 ר' יוחנן לעיל: \u0003שאם עשאן כולן\u0004 את כל העבירות המנויות במשנתנו \u0003בהעלם\u0004 (בשגגה) \u0003אחת\u0004 — \u0003חייב\u0004 חטאת \u0003על כל אחת ואחת.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שיהיה \u0003פטור לגמרי\u0004 — \u0003לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 בסוף פרשת העריות: \u0003\"כי כל אשר יעשה מכל התועבת האלה ונכרתו\u0004 הנפשות העושות מקרב עמם\" (ויקרא יח, כט), והואיל ויש בכולן כרת — חייב על שגגתן חטאת. \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: אם \u0003עבר\u0004 עבירה \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003נתחייב חדא\u0004 \u0005[אחת],\u0006 \u0003עבר כולהו\u0004 \u0005[את כולם]\u0006 \u0003בהעלם אחת\u0004 — \u0003אינו חייב אלא אחת!\u0004","\u0003אמר ר' יוחנן: ל\u0004שם \u0003כך יצאה כרת\u0004 שנאמרה בנפרד \u0003ב\u0004בא על \u0003אחותו\u0004 (שם כ, יז) — \u0003לחלק,\u0004 ללמד שכל עבירה מחייבת כרת (וחטאת) בפני עצמה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ביבי בר אביי, אימא\u0004 \u0005[אמור]\u0006 כך: \u0003אחותו דפרט קרא\u0004 \u0005[שפירט\u0006 אותה \u0005הכתוב]\u0006 — \u0003ניחייב חדא עלה\u0004 \u0005[שיתחייב עליה אחת\u0006 בפני עצמה\u0005], וכולן\u0006 וכל השאר, \u0003כיון\u0004 שבהעלם \u0003אחת\u0004 נעשו — \u0003לא ניחייב\u0004 \u0005[יתחייב]\u0006 \u0003אלא אחת!\u0004","ושואלים: \u0003ולרב ביבי בר אביי, מי לית ליה הדא דתניא\u0004 \u0005[האם אין לו, אינו מקבל את זו ששנויה בברייתא]\u0006 לגבי המידות שהתורה נדרשת בהן: \u0003כל דבר שהיה בכלל ויצא מן הכלל\u0004 שנכתב בתורה לעצמו \u0003ללמד\u0004 הלכה כל שהיא, \u0003לא ללמד על עצמו\u0004 בלבד \u0003יצא אלא ללמד על הכלל כולו יצא,\u0004 ומסבירה הברייתא:","\u0003כיצד?\u0004 נאמר: \u0003\"והנפש אשר תאכל בשר\u0004 מזבח השלמים אשר לה' וטומאתו עליו, ונכרתה הנפש ההיא מעמיה\" (ויקרא ז, כ), \u0003והלא שלמים בכלל הקדשים היו,\u0004 שנאמר בהם כבר \"כל איש אשר יקרב מזרעכם של הקדשים... וטומאתו עליו ונכרתה הנפש ההיא...\" (שם כב, ג), אם כן, \u0003למה יצאו\u0004 ללמד בהם דין זה?","\u0003להקיש\u0004 (להשוות) \u0003אליהן\u0004 ולומר: \u0003מה שלמים שהן קדשי מזבח וחייבין עליהן\u0004 על אכילתם בטומאה — \u0003אף כל שהן קדשי מזבח חייבין עליהן, יצאו קדשי בדק הבית\u0004 שאין בהם חיוב זה. ואם כן הוא הדין באחותו, שיצאה ללמד על שאר כל העריות, לחייב על כל אחת ואחת בפני עצמה!","ומשיבים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ביבי: בר מינה\u0004 \u0005[חוץ מזו],\u0006 זו אינה קושיה לדברי, ולהיפך, מברייתא זו עצמה יש להקשות על ר' יוחנן: \u0003לאו מי אמרת התם\u0004 \u0005[האם לא אמרת שם]\u0006 שיצאו \u0003קדשי בדק הבית,\u0004 כלומר, שהפרט מלמד רק על דברים הדומים לו?","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נאמר כך: \u0003מה אחותו מיוחדת\u0004 משאר איסורי עריות \u0003שהיא ערוה ואין לה היתר בחיי אוסרה,\u0004 שהוא איסור שאין דרך להתירו כל זמן שהוא בחיים, \u0003אף כל\u0004 ערווה \u0003שאין לה היתר בחיי אוסרה\u0004 מתחייב עליה בפני עצמה, \u0003יצאה\u0004 מכלל זה \u0003אשת איש, שיש לה היתר בחיי בעלה\u0004 אם יגרש אותה, ושמא לא יתחייב עליה קרבן לעצמו. ולא כדברי ר' יוחנן, שלמדנו מאחותו לחלק חטאת על כל אחת מן העריות!","בתשובה לכך \u0003אמר ר' יונה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת העריות: \u0003\"כי כל אשר יעשה מכל התועבת\u0004 האלה\" (שם יח, כט), הואיל וכך, שאף אחותו בכלל כתוב זה — \u0003הקיש הוא\u0004 שהוקשו \u0003כל העריות כולן לאחותו: מה אחותו חייבין עליה בפני עצמה, אף כל\u0004 אחת מן העבירות המנויות שם \u0003חייבין עליה בפני עצמה.\u0004 ובדרך הלימוד של היקש למדים גם לדברים שאינם דומים לגמרי.","ושואלים, \u0003ול\u0004דעת \u0003ר' יצחק\u0004 ש\u0003אמר:\u0004 כל \u0003חייבי כריתות בכלל\u0004 אחד \u0003היו,\u0004 שנאמר: \"כי כל אשר עשה מכל התועבות האלה ונכרתו\" (שם), \u0003ולמה יצאה\u0004 ונתפרש עונש \u0003כרת באחותו\u0004 בנפרד? \u0003לדונה בכרת\u0004 דווקא \u0003ולא במלקות,\u0004 וממנה אתה למד לשאר חייבי הכריתות, אם כן,","\u0003לחלק\u0004 ולחייב חטאת בנפרד על כל כרת כשעשאן בהעלם אחד, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו] מ\u0006מה שנאמר \"\u0003ואל אשה בנדת טומאתה לא תקרב\u0004 לגלות ערוה\" (שם, יט), ויכול היה לכתוב \"ואל נדה לא תקרב\", אלא מכאן למדנו \u0003לחלק על כל אשה ואשה,\u0004 שעל כל אחת חייב למרות שהיה זה בהעלם אחד.","ושואלים: \u0003ורבנן נמי תיפוק להו\u0004 \u0005[וחכמים,\u0006 החולקים על ר' יצחק, \u0005גם כן תצא להם]\u0006 הלכה זו \u0003מ\u0004מה שנאמר \u0003\"ואל אשה בנדת טומאתה\"!\u0004 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן כך הוא גם כן],\u0006 ואף לדעתם זה המקור להלכה זו. ושואלים: אם כן, \u0003אלא כרת דאחותו למאי אתא\u0004 \u0005[למה בא],\u0006 מדוע הוצרך לפרט אותו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו\u0006 הדבר\u0005]\u0006 \u0003לחלק\u0004 חטאות במי שבא \u0003על אחותו ועל אחות אביו ועל אחות אמו\u0004 בהעלם אחד.","ושואלים: \u0003הני למה להו\u0004 \u0005[אלה למה להם]\u0006 פסוק מיוחד \u0003לחלק\u0004 ביניהם? \u0003הרי שמות\u0004 איסורים \u0003מוחלקין\u0004 הם, עבירות שונות, \u0003והרי גופים מוחלקים\u0004 נשים שונות הן, ואין סברה לפטור בחטאת אחת את העובר על כולן! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003לחלק\u0004 במי שבא \u0003על אחותו שהיא\u0004 גם \u0003אחות אביו ושהיא\u0004 גם \u0003אחות אמו,\u0004 שחייב עליה שלוש חטאות למרות שמדובר בגוף אחד.","ושואלים: \u0003ור' יצחק, הא מילתא מנא ליה\u0004 \u0005[דבר זה מנין לו]?\u0006 שהרי הוא לומד מפסוק זה של כרת באחותו ענין אחר! ומשיבים: \u0003נפקא ליה מן סיפא דקרא\u0004 \u0005[יוצא לו\u0006 הדבר \u0005מסופו של המקרא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ערות אחתו גלה\"\u0004 (שם כ, יז) לומר שבכל פרט של איסור זה יש חיוב לחוד.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלמדו הלכה זו מעצם הכרת באחותו, \u0003\"אחתו\" דסיפא דקרא\u0004 \u0005[שבסופו של אותו\u0006 \u0005כתוב]\u0006 \u0003מאי עבדי ליה\u0004 \u0005[מה עושים הם בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006"],["\u0003לאחותו שהיא\u0004 גם \u0003בת אביו ו\u0004גם \u0003בת אמו, לומר שאין עונשין מן הדין,\u0004 בדרך קל וחומר. שאף שנתפרש בתורה עונש גם לבא על אחותו בת אביו וגם לבא על אחותו בת אמו, אין למדים בקל וחומר כרת לבא על זו שהיא גם בת אביו וגם בת אמו, שאין עונשים אלא מגזירת הכתוב.","ומעירים: \u0003ור' יצחק,\u0004 שאינו למד מכאן דין זה, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003עונשין מן הדין. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 טעם אחר שאינו נצרך לכתוב מיוחד לדין זה, משום שהוא \u0003יליף\u0004 \u0005[לומד]\u0006 \u0003עונש\u0004 כרת באשה זו \u0003מאזהרה,\u0004 ממצות \"לא תעשה\" שנאמרה בה, שכשם שהזהיר עליה כשאר עריות — כך ענש עליה כמותן.","עוד בענין כרת שכתבה התורה באחותו בנפרד, מביאים \u0003אמר ר' אלעזר אמר ר' הושעיא: כל מקום שאתה מוצא שני לאוין\u0004 שונים \u0003ו\u0004עונש \u0003כרת אחד\u0004 בלבד ביחס לשניהם — \u0003חלק חטאת ביניהן,\u0004 שאם עשה שניהם בשגגה אחת — יש בכל אחד מהם חיוב חטאת לעצמו. \u0003ומאי היא\u0004 \u0005[ומהו]\u0006 המקרה הזה? מי ש\u0003מפטם\u0004 (רוקח) לצורך עצמו את שמן המשחה שנצטווה משה \u0003ו\u0004גם \u0003סך\u0004 ממנו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"על בשר אדם לא ייסך ובמתכנתו\u0004 לא תעשו כמוהו\" (שמות ל, לב) — הרי כאן שני לאוים, אחד על סיכה, ואחד על פיטום, ו\u0003כרת אחד\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אשר ירקח כמהו ואשר יתן ממנו על זר ונכרת מעמיו\"\u0004 (שם לג).","ושואלים: לפי דרך זו, \u0003וכי מאחר\u0004 שיש \u0003לאוין מוחלקים\u0004 (נפרדים) בכל העריות, בפרשת \"אחרי מות\" (ויקרא י״ח:כ״ט), ובסופה נאמר: \"כי כל אשר יעשה מכל התועבות האלה ונכרתו\" (שם כט), הרי די בכך לחייב חטאת על כל אחת, ואם כן, \u0003כרת\u0004 ב\u0003אחותו דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 בנפרד בפרשת \"קדושים\": \"ונכרתו לעיני בני עמם ערות אחותו גילה\" (שם כ, יז) \u0003למה לי?\u0004","ומשיבים: כפי שנאמר לעיל, לשיטת חכמים — כפי שהם סבורים, \u0003ל\u0004שיטת \u0003ר' יצחק כדאית ליה\u0004 \u0005[כמו שיש לו],\u0006 כפי שהוא סבור. ומפרטים: \u0003לרבנן מיבעיא להו\u0004 \u0005[לחכמים נצרכה להם]\u0006 \u0003לומר שאין עונשין מן הדין, לר' יצחק,\u0004 הוא \u0003מפיק ליה\u0004 \u0005[מוציא אותו,\u0006 למד ממנו\u0005]\u0006 \u0003לחייב\u0004 שלוש חטאות נפרדות \u0003על אחותו שהיא אחות אביו ושהיא אחות אמו.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 כיצד למדים הם הלכה זו? ומסבירים: \u0003דנפקא להון\u0004 \u0005[ש\u0006היא \u0005יוצאת להם]\u0006 \u0003מן \"אחתו\" דרישא\u0004 \u0005[שבתחילת\u0006 הפסוק], שנאמר שם: \"ואיש אשר יקח את אחותו\". \u0003ו\u0004לעומתם \u0003ר' יצחק סבר\u0004 \u0005[סבור]\u0006 ש\u0003אחותו דרישא\u0004 \u0005[שבתחילת\u0006 הפסוק\u0005]\u0006 \u0003אורחיה דקרא\u0004 \u0005[דרכו של הכתוב]\u0006 \u0003היא,\u0004 שמתאר את המקרה עליו מדובר, ואין ללמוד מכאן, \u0003ו\u0004לכן \u0003מפיק\u0004 \u0005[מוציא]\u0006 את ההלכה הזו \u0003לחלק מ\"אחתו\"\u0004 שכתוב \u0003דסיפיה דקרא\u0004 \u0005[בסופו של המקרא],\u0006 \u0003לחלק על אחותו שהיא אחות אביו ושהיא אחות אמו.\u0004 ושבים לעיקר דברי ר' אלעזר שהמפטם וסך בהעלם אחד חייב שתי חטאות.","\u0003אמר רב נחמן בר יצחק, אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 ברשימת הכריתות שבמשנתנו כדבריו: \u0003המפטם את השמן, המפטם את הקטרת, והסך בשמן המשחה.\u0004","ויש לשאול: \u0003למה לי דתניא\u0004 \u0005[מפני מה שנויה]\u0006 \u0003המפטם את הקטרת במיצעא\u0004 \u0005[באמצע],\u0006 בין שתי כריתות הנוגעות לשמן המשחה? \u0003לאו הא קא משמע לן\u0004 \u0005[האם לא\u0006 דבר \u0005זה הוא משמיע לנו]:\u0006 \u0003מה קטרת\u0004 יש בה \u0003לאו בפני עצמו וחייבים עליה כרת,\u0004 וחטאת בשוגג, \u0003בפני עצמו\u0004 — \u0003אף מפטם שמן\u0004 המשחה \u0003וסך\u0004 מן השמן \u0003נמי\u0004 \u0005[גם כן],\u0006 \u0003כיון\u0004 שכל אחד מהם \u0003לאו בפני עצמו\u0004 — \u0003חייבים עליו\u0004 כרת, וחטאת בשוגג, \u0003בפני עצמה?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 הסבר אחר לדבר, \u0003דקא בעי למיתנא פיטומין בהדי הדדי [\u0004משום \u0005שהוא רוצה לשנות\u0006 את \u0005שני הפיטומים זה עם זה]\u0006 — \u0003ניתנהו איפוך\u0004 \u0005[שישנה אותם להיפך]:\u0006 \u0003המפטם את הקטרת, והמפטם את השמן, והסך שמן המשחה,\u0004 ויסמוך פיטום לפיטום, ושמן לשמן, \u0003אמאי פלגיה\u0004 \u0005[מדוע חילק]\u0006 את ה\u0003שמן,\u0004 ושנה את הקטורת באמצע? \u0003לאו הא קמשמע לן\u0004 \u0005[האם לא\u0006 דבר \u0005זה הוא משמיע לנו]\u0006 ש\u0003יש חילוק חטאות ביניהן?\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה ברשימת הכריתות: \u0003הבא על הזכור\u0004 ועל הבהמה ואשה המביאה הבהמה עליה. ושואלים: ה\u0003תנא\u0004 של משנתנו, \u0003במאי קא חשיב\u0004 \u0005[במה\u0006 במי \u0005הוא מונה]\u0006 את הכריתות שבמשנה?","\u0003אי בגברי\u0004 \u0005[אם באנשים]\u0006 — \u0003דל\u0004 \u0005[הורד]\u0006 את \u0003האשה הנרבעת\u0004 לבהמה, \u0003ובצרא לה חדא\u0004 \u0005[וחסרה לה\u0006 כרת \u0005אחת]\u0006 מן המנין! \u0003אי בנשי קחשיב\u0004 \u0005[אם בנשים הוא מונה]\u0006 — \u0003דל מינהון\u0004 \u0005[הורד מהן]\u0006 את \u0003הבא על הזכור ועל הבהמה, ובצרי להו תרתי\u0004 \u0005[וחסרות להן שתים]!\u0006","\u0003אמר ר' יוחנן: לעולם תנא גברי קחשיב\u0004 \u0005[אנשים הוא מונה],\u0006 ויש להוריד מן הרשימה את האשה הנרבעת לבהמה, \u0003ותני הכי\u0004 \u0005[ושנה כך]\u0006\u0003 בלשון זו: הבא על הזכור והביא זכור עליו. ו\u0004שיטת ר' \u0003ישמעאל היא,\u0004 שאמר: מי שעושה שתי עבירות אלה בהעלם (שגגה) אחד — \u0003חייב שתים,\u0004 שתי חטאות.","ושואלים: \u0003והא מדקתני\u0004 \u0005[והרי ממה שהוא שונה]\u0006 \u0003מגדף בסיפיה\u0004 \u0005[בסופו,\u0006 בסוף המשנה\u0005],\u0006 \u0003ומוקמינן לה\u0004 \u0005[ומעמידים אנו אותה]\u0006 \u0003כ\u0004דעת \u0003ר' עקיבא\u0004 — \u0003רישא נמי\u0004 \u0005[תחילתה\u0006 של המשנה \u0005גם כן]\u0006 שיטת ר' \u0003עקיבא\u0004 היא!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 אכן, משנתנו שיטת ר' \u0003עקיבא היא, וברישא\u0004 \u0005[ובהתחלה],\u0006 בענין זכור, \u0003סבר לה\u0004 \u0005[\u0006הוא \u0005סבור]\u0006\u0003 כ\u0004דעת ר' \u0003ישמעאל\u0004 — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבהו: הבא על הזכור והביא זכור עליו, ל\u0004דעת ר' \u0003ישמעאל דמפיק ליה מתרתי קראי\u0004 \u0005[שמוציא לו\u0006 את האיסורים הללו \u0005משני מקראות]\u0006 נבדלים, את הבא על הזכור \u0003מ\"ואת זכר לא תשכב\u0004 משכבי אשה\" (ויקרא יח, כב), ואת המביא זכור עליו \u0003מ\"ולא יהיה קדש\u0004 (זונה ממין זכר) \u0003מבני ישראל\"\u0004 (דברים כג, יח), לכן הוא חייב שתים, ואילו","\u0003לר' עקיבא אינו חייב אלא\u0004 חטאת \u0003אחת, דמחד קרא נפיק ליה\u0004 \u0005[שמאותו כתוב יוצא לו]\u0006 גבי המביא זכר עליו: \u0003\"את זכר לא תשכב\", קרי ביה\u0004 \u0005[קרא בו]\u0006 גם: \u0003לא תשכיב!\u0004","\u0003אלא\u0004 כך צריך לומר: \u0003רישא\u0004 \u0005[תחילתה\u0006 של המשנה\u0005]\u0006 היא שיטת \u0003ר' ישמעאל,\u0004 הסבור שיש שתי חטאות בבא על הזכור ובמביא את הזכר עליו, אבל בענין \u0003מגדף סבר לה\u0004 \u0005[סבור הוא]\u0006\u0003 כ\u0004שיטת \u0003ר' עקיבא.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמשנה זו לשיטת ר' ישמעאל, הלמד אזהרה לנשכב מ\"לא יהיה קדש\" (דברים כג, יח), \u0003ניתני נמי\u0004 \u0005[שישנה גם כן]\u0006 שתי כריתות נפרדות לגבי בהמה: \u0003הבא על הבהמה\u0004 (מ\"ובכל בהמה לא תתן שכבתך\", ויקרא יח, כג), \u0003והביא בהמה עליו\u0004 (מ\"לא יהיה קדש\")!","ודוחים: \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר אביי: הבא על הבהמה והביא בהמה עליו, אף לר' ישמעאל,\u0004 שמחייב שתים בזכר, בענין זה \u0003אינו חייב אלא אחת, דכי כתיב קרא\u0004 \u0005[שכאשר נאמר הכתוב]\u0006 \"לא יהיה קדש\" — \u0003בגברי כתיב\u0004 \u0005[באנשים נאמר],\u0006 שמושג הזנות (\"קדש\") לא שייך בבהמה. זה היה הסברו של ר' יוחנן, שמדובר במשנתנו באנשים, ולכן יש למחוק מן הרשימה במשנתנו את האשה המביאה בהמה עליה, ולהוסיף את המביא זכור עליו, וכשיטת ר' ישמעאל.","\u0003ר' אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר:\u0004 משנתנו אמנם עוסקת באנשים ולא בנשים, ומכל מקום אין למחוק אשה הנרבעת לבהמה מן המשנה, שכן ה\u0003תנא תני\u0004 \u0005[שונה]\u0006 במשנתנו רק \u0003שלשים ושלש חטאות,\u0004 עבירות כרת שמביא עליהן חטאת, \u0003ותני\u0004 \u0005[ו\u0006הוא \u0005שונה]\u0006 עוד \u0003שלש כריתות\u0004 שאינן בכלל רשימה זו, ובכללן אשה הנרבעת לבהמה, כדי \u0003לסיומינהו\u0004 \u0005[לסיים,\u0006 להכליל \u0005אותן]\u0006 \u0003ב\u0004רשימת \u0003כריתות\u0004 שבתורה. ומנין?","\u0003דקתני סיפא\u0004 \u0005[ש\u0006הרי \u0005הוא שונה בסוף\u0006 המשנה\u0005]:\u0006 \u0003פסח ומילה במצו‍ת עשה,\u0004 ויש לשאול: \u0003פסח ומילה אמאי קתני להו\u0004 \u0005[מדוע שונה אותם]?\u0006","\u0003ואיתימא לאיתויי קרבן עליהון\u0004 \u0005[ואם תאמר\u0006 כדי \u0005להביא קרבן עליהם],\u0006 אם ביטל אותן בשגגה, \u0003מי מייתי\u0004 \u0005[האם\u0006 הוא \u0005מביא]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הוקשה\u0004 (הושוותה) \u0003כל התורה כולה לעבודה זרה\u0004 לענין קרבן חטאת לעובר בשגגה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בקרבן חטאת: \u0003\"תורה אחת יהיה לכם לעושה בשגגה. והנפש אשר תעשה ביד רמה\u0004 וכו' את ה' הוא מגדף\" (במדבר טו, כט — ל), והיא עבודה זרה:","\u0003מה עבודה זרה\u0004 היא ציווי של \u0003שב ואל תעשה,\u0004 ומתחייב חטאת אם עשאה בשגגה — \u0003אף כל\u0004 עבירות שחייבים עליהן חטאת בשגגה, הן דברים שהתורה מצווה ב\u0003שב ואל תעשה,\u0004 ולא במצוות עשה!","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נלמד מכאן]\u0006 כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003שלשים ושלש חטאות מאן דעבדי\u0004 \u0005[\u0006ל\u0005מי שעושים]\u0006 אותן \u0003בשוגג, והדר תנא\u0004 \u0005[וחזר\u0006 ו\u0005שנה]\u0006 עוד \u0003שלש כריתות\u0004 כדי \u0003לסיומינהו\u0004 \u0005[לסיים,\u0006 להכליל \u0005אותן]\u0006 בתוך רשימת ה\u0003כריתות\u0004 שבתורה, והן: אשה הנרבעת, פסח ומילה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","שנינו במשנה ברשימת הכריתות שמביאים על כל אחת מהן חטאת: \u0003המחלל את השבת. אמרי\u0004 \u0005[אומרים]\u0006 על כך בתמיהה: הרי מלאכות \u0003שבת ארבעים חסר אחת הוויין\u0004 \u0005[הן],\u0006 ומתחייב חטאת על כל אחת ואחת מהן! \u0003אמר ר' יוחנן: תנא\u0004 \u0005[שנה]\u0006 במשנתנו מקרה שהיתה \u0003שגגת שבת,\u0004 ששכח ששבת היא, \u0003וזדון מלאכות,\u0004 שיודע שמלאכות אלה אסורות בשבת, שבמקרה זה \u0003לא מחייב אלא חדא\u0004 \u0005[אינו מתחייב אלא\u0006 חטאת \u0005אחת],\u0006 משום שהיתה רק שגגה יסודית אחת, ולא כמה שגגות נבדלות.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר לגבי קרבן חטאת \"נפש כי תחטא בשגגה מכל מצוות ה' אשר לא תיעשנה ועשה מאחת מהנה\" (ויקרא ד, ב), ודרשו חכמים את \"מאחת מהנה\" בכמה אופנים, וביניהן כאילו נאמר \"ועשה אחת הנה\", שיש \u0003\"הנה\"\u0004 (שגגות רבות) \u0003שהיא \"אחת\"\u0004 (שגגה אחת) שמתחייב עליה רק חטאת אחת, כיצד? כאשר עשה מלאכות רבות ב\u0003שגגת שבת וזדון מלאכות,\u0004 שידע שהן אסורות בשבת.","ושואלים: \u0003וניתני\u0004 \u0005[ושישנה]\u0006 כאן התנא \u0003זדון שבת ושגגת מלאכות,\u0004 שהוא יודע ששבת היום, אבל שגג בכל אחת מהמלאכות, שלא ידע שהן אסורות, \u0003דמחייב\u0004 \u0005[שמתחייב]\u0006 אז \u0003ארבעים חסר אחת\u0004 חטאות!","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"ועשה מאחת מהנה\"\u0004 — \u0003פעמים שחייב\u0004 חטאת \u0003אחת על כולן, ופעמים שחייב\u0004 חטאת \u0003על כל אחת ואחת.\u0004 וכן מצאנו \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"אחת\" שהיא \"הנה\",\u0004 שיש שאדם שוגג שגגה אחת ומביא עליה חטאות רבות, ב\u0003זדון שבת ושגגת מלאכות!\u0004","ומשיבים: ה\u0003תנא שגגת שבת וזדון מלאכות עדיפא ליה\u0004 \u0005[עדיף לו]\u0006 לשנות, כדי להדגיש \u0003דמחטאת מיהא לא מיפטר\u0004 \u0005[ש\u0006בכל מקרה ששגג בשבת \u0005מחטאת\u0006 אחת \u0005על כל פנים לא נפטר].\u0006","ומעירים: \u0003וכן אתה מוצא\u0004 שהתנא הולך במשנתנו בדרך זו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עבודה זרה, דקתני\u0004 \u0005[שהוא שונה]\u0006 בה כרת אחת, למרות שחייב על כל אחת מדרכי עבודתה: שחיטה, הקטרה, ניסוך והשתחווייה, וכיצד — כאשר היתה \u0003שגגת עבודה זרה,\u0004 שלא ידע שהוא עובד עבודה זרה, \u0003וזדון עבודות,\u0004 שיודע שעבודות אלה אסורות לעבודה זרה.","ושואלים: \u0003שגגת עבודה זרה היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003עמד בבית עבודה זרה וסבר בית הכנסת היא, והשתחוה\u0004 שם לה' — \u0003הרי לבו לשמים,\u0004 שהשתחווה לה', ולא לעבודה זרה, ואין מקום לחייבו כלל!","\u0003ואלא\u0004 תאמר \u0003דחזא אנדרטא וסגיד לה\u0004 \u0005[שראה פסל אדם,\u0006 שלא נעשה לשם עבודה זרה, \u0005והשתחווה לו],\u0006 גם על כך יש לתמוה: במה מדובר? \u0003אי דקבליה עליה\u0004 \u0005[אם קיבל אותו עליו]\u0006 \u0003באלוה,\u0004 שהוא משתחווה לו לשם פולחן — \u0003בר\u0004 \u0005[בן]\u0006 \u0003סקילה הוא,\u0004 כלומר, מזיד הוא ולא שוגג! \u0003ואי דלא קבליה\u0004 \u0005[ואם שלא קיבל אותו]\u0006 \u0003באלוה,\u0004 אלא רק משתחווה מחמת הנימוס — \u0003לאו מידי הוא\u0004 \u0005[אין זה כלום],\u0006 אין זו עבודה זרה כלל!","\u0003אלא\u0004 הכוונה היא שהשתחווה לעבודה זרה, וידע שהיא עבודה זרה, ואולם עשה זאת לא מתוך שקיבלה כאלוה, אלא \u0003מאהבה ומיראה,\u0004 משום שהוא אוהב או מתיירא מאדם, ועושה זאת למענו, ובזה היתה שגגתו.","ושואלים: הניחא \u0005[זה נוח,\u0006 מובן\u0005]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 שאמר שבמקרה כזה \u0003חייב\u0004 חטאת, \u0003אלא ל\u0004שיטת \u0003רבא\u0004 שאמר שבכגון זה \u0003פטור,\u0004 מפני שאינו מקבלה עליו כאלוה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006"],["\u0003אלא\u0004 מוצא אתה שגגת עבודה זרה \u0003באומר מותר\u0004 לעבוד עבודה זרה, שאינו יודע שיש איסור בדבר, שעד \u0003כאן לא קבעי מיניה\u0004 \u0005[לא שאל ממנו]\u0006 \u0003רבא מרב נחמן\u0004 בהלכות שבת, מה דינו של מי שנעלם ממנו ששבת היום, וגם שמלאכות אלו שהוא עושה אסורות, \u0003אלא אי חדא מחייב אי תרתי מחייב\u0004 \u0005[אם אחת הוא חייב או שתיים הוא חייב],\u0006 \u0003אבל מיפטר לגמרי לא בעא מיניה\u0004 \u0005[להיפטר לגמרי לא שאל אותו].\u0006","\u0003רב פפא אמר: משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 שגגת עבודה זרה \u0003בתינוק שנשבה לבין הגוים, דידע דאסירא\u0004 \u0005[שיודע שאסורה]\u0006 עבודה זרה, והני \u0005[ואותן]\u0006 \u0003עבודה זרה\u0004 שהוא עובד \u0003לא ידע דאסירן\u0004 \u0005[אינו יודע ש\u0006הן \u0005אסורות].\u0006 \u0003ואי\u0004","\u0003בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר \u0003בגדול\u0004 — \u0003כגון דקא טעי בהדין קרא\u0004 \u0005[שהוא טועה בפסוק זה]\u0006 שנאמר: \u0003\"לא תעשון אתי אלהי כסף ואלהי זהב\"\u0004 (שמות כ, כ), \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כי אסירא\u0004 \u0005[כאשר אסורה]\u0006 \u0003השתחואה\u0004 הרי זה \u0003לעבודה זרה\u0004 של \u0003כסף וזהב, אבל דמיני אחריני שריא\u0004 \u0005[של מינים אחרים,\u0006 כגון של עץ ואבן, \u0005מותרת],\u0006 \u0003דהיינו\u0004 \u0005[שהרי זו]\u0006 \u0003שגגת עבודה זרה וזדון עבודות.\u0004 ושבים לשאלה ששאלנו מתחילה: מדוע לא שנה התנא את כל מלאכות השבת ברשימת הכריתות שבמשנה (שמביאין על כל אחת חטאת בפני עצמה)?","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב ביבי אמר:\u0004 ה\u0003תנא, שם\u0004 (ענין) \u0003שבת, ו\u0004כיוצא בזה \u0003שם עבודה זרה קתני\u0004 \u0005[הוא שונה],\u0006 ולא נכנס לפרטי החטאות שיש בכל אחת. \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה למד זאת? \u0003מדקתני\u0004 \u0005[ממה שהוא שונה\u0006 במשנתנו\u0005]:\u0006 \u0003הבא על אשה ובתה ועל אשת איש, והא\u0004 \u0005[והרי]\u0006 \u0003יש בתו מאנוסתו דלא קתני לה\u0004 \u0005[שאינו שונה אותה],\u0006 למרות שגם היא בכלל חייבי הכריתות, אלא לא שנאה משום שגם היא בכלל \"אשה ובתה\".","בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים],\u0006 אין מכאן ראיה, שכך יש לומר: \u0003דכתיבן קתני, דלא כתיבן לא קתני\u0004 \u0005[\u0006אלה \u0005שכתובות\u0006 במקרא במפורש \u0005הוא שונה, שאינן כתובות אינו שונה],\u0006 ובתו מאנוסתו אנו למדים ממדרש הכתובים, ואינה כתובה במפורש.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003בת אשתו\u0004 (מאיש אחר) \u0003ובת בתה ובת בנה, דכתיבא\u0004 \u0005[שכתובה]\u0006 בתורה, \u0003ולא קתני\u0004 \u0005[ואינו שונה]\u0006 אותן במשנה! \u0003אלא\u0004 צריך אתה לומר כי \u0003שם אשה ובתה קתני\u0004 \u0005[הוא שונה],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יש לומר: \u0003שם שבת ושם עבודה זרה קתני\u0004 \u0005[הוא שונה].\u0006","ומעירים: \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא רמי דיליה אדיליה\u0004 \u0005[השליך\u0006 שמועה \u0005שלו,\u0006 של רב ביבי \u0005על\u0006 שמועה אחרת \u0005שלו],\u0006 וכך אמר: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר רב ביבי בר אביי הכי\u0004 \u0005[כך],\u0006 ש\u0003שם שבת קתני\u0004 \u0005[הוא שונה]\u0006 \u0003ושם עבודה זרה קתני\u0004 \u0005[הוא שונה]?\u0006 \u0003והאיתמר\u0004 \u0005[והרי נאמר]:\u0006 \u0003המעלה אברי פנים בחוץ,\u0004 ששחט קרבן במקדש כדינו, והעלה את איבריו על מזבח מחוץ למקדש — \u0003חייב\u0004 חטאת אם עשה זאת בשוגג. וכן אם מעלה \u0003אברי\u0004 קרבן שנשחט מ\u0003חוץ\u0004 למקדש, \u0003בחוץ\u0004 לצורך קרבן — גם הוא \u0003חייב.\u0004","\u0003וקשיא ליה\u0004 \u0005[ו\u0006היה \u0005קשה לו]\u0006 \u0003לרב ביבי בר אביי: אי הכי\u0004 \u0005[אם כך],\u0006 \u0003הא דתנן\u0004 \u0005[זו ששנינו]\u0006 במשנתנו: \u0003שלשים ושש כריתות בתורה\u0004 — הלא \u0003תלתין ושבע נינהו\u0004 \u0005[שלושים ושבע הם],\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003המעלה\u0004 איברי פנים בחוץ, \u0003והמעלה\u0004 איברי חוץ בחוץ! ואם הוא סבור כי התנא אינו שונה את כל פרטי הכריתות, אלא \u0003שם שבת, מאי קשיא ליה\u0004 \u0005[מה קשה לו]?\u0006 \u0003נישני\u0004 \u0005[שיתרץ]\u0006 גם במקרה זה: \u0003שם העלאה קתני\u0004 \u0005[הוא שונה]!\u0006","ודוחים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדברים \u0005דומים]?\u0006 \u0003שבת ועבודה זרה תנא יתהון אבינכיהון\u0004 \u0005[שנה אותם\u0006 את פרטי החיוב שבהם \u0005במקומם]\u0006 של שבת — במסכת שבת (עג,א), ושל עבודה זרה — במסכת סנהדרין (ס,ב), ולכן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003כריתות, דאיריא\u0004 \u0005[שהוצרך\u0006 להזכירם\u0005]\u0006 כחלק מרשימת הכריתות, הוא \u0003משני\u0004 \u0005[מתרץ]:\u0006 \u0003שם שבת קתני\u0004 \u0005[שנה]\u0006 \u0003שם עבודה זרה קתני\u0004 \u0005[שונה],\u0006 אבל \u0003גבי\u0004 \u0005[אצל]\u0006 חיובי \u0003העלאה, מי תנא יתהון בינכיהון\u0004 \u0005[האם שנה אותם במקומם]\u0006 \u0003דשני הכי\u0004 \u0005[ש\u0006הוא \u0005יכול לתרץ כך]?\u0006","בעקבות מה שאמר ר' אלעזר בעמוד הקודם, שאם יש שני איסורי לאו, וכרת אחד לשניהם, ועשה שניהם כאחד — חייב על כל אחד מהם חטאת בפני עצמו, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006\u0003 ר' ירמיה מר' זירא:\u0004 אם יש \u0003שתי כריתות ולאו אחד\u0004 כתוב בהן, \u0003מהו?\u0004 האם יתחייב חטאת על כל עבירה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם לגבי \u0003שוחט\u0004 קדשים בחוץ \u0003והעלה\u0004 איברי קרבן בחוץ \u0003קאמרת\u0004 \u0005[אומר אתה]?\u0006 והלא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003שני לאוין נינהו\u0004 \u0005[הם],\u0006","\u0003אי למאן דגמר\u0004 \u0005[אם ל\u0006דעת \u0005מי שלומד]\u0006 דבר זה \u0003מגזרה שוה,\u0004 ממה ש\u0003נאמר כאן הבאה:\u0004 \"אשר ישחט חוץ למחנה ואל פתח אהל מועד לא יביאנו\" (ויקרא יז, ד), \u0003ונאמר להלן הבאה:\u0004 \"אשר יעלה עולה או זבח ואל פתח אהל מועד לא יביאנו\" (שם ט),","\u0003מה להלן\u0004 בהעלאה \u0003לא ענש\u0004 כרת \u0003אלא אם כן הזהיר,\u0004 שנאמר: \"השמר לך פן תעלה עולותיך\" (דברים יב, יג) — \u0003אף כאן\u0004 בשחיטה \u0003לא ענש\u0004 כרת (ויקרא יז, ד) \u0003אלא אם כן הזהיר.\u0004","אם \u0003למאן דמייתי לה\u0004 \u0005[למי שמביא,\u0006 לומד \u0005אותה]\u0006 \u0003בהיקש\u0004 — שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006\u0003: \"שם תעלה... ושם תעשה\"\u0004 (דברים יב, יד), \u0003מקיש\u0004 (משווה) \u0003שחיטה\u0004 (\"תעשה\") \u0003להעלאה, מה העלאה לא ענש אלא אם כן הזהיר, אף שחיטה לא ענש אלא אם כן הזהיר.\u0004 ולדברי שניהם הרי זה כאילו נאמר לאו מפורש בתורה גם ביחס לשחיטה.","\u0003דלמא\u0004 \u0005[שמא]\u0006 לגבי \u0003שתי מיתות ולאו אחד קאמרת\u0004 \u0005[אומר,\u0006 שואל \u0005אתה],\u0006 כלומר, שתי עבירות שחייב מיתה על כל אחת מהן כשעשאן בעדים ובהתראה, האם גם מביא שתי חטאות נפרדות כשעשאן יחדיו בשוגג, למרות שיש בהן רק לאו אחד? ו\u0003מה היא,\u0004 במה מדובר — ב\u0003אוב וידעוני.\u0004","\u0003הוסיף ואמר ליה\u0004 \u0005[לו]\u0006 \u0003דהא פלוגתא\u0004 \u0005[שזו מחלוקת]\u0006 \u0005ר' י\u0006 \u0003וחנן וריש לקיש\u0004 בהסבר טעמה של משנתנו. \u0003דתנו\u0004 \u0005[ששנו]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 רשימת הנסקלין שבמסכת \u0003סנהדרין\u0004 (נג,א) \u0003בעל אוב,\u0004 המעלה את רוח המת, \u0003וידעוני,\u0004 המכניס עצם מיוחדת לפיו והיא \"מדברת\", \u0003וקשיא לן\u0004 \u0005[ו\u0006היה \u0005קשה לנו],\u0006 \u0003ומאי שנא גבי\u0004 \u0005[ובמה שונה אצל]\u0006 \u0003סקילות\u0004 שהוא \u0003תני\u0004 \u0005[שונה]\u0006 \u0003ידעוני\u0004 כעבירה לחוד, \u0003וגבי\u0004 \u0005[ואצל]\u0006 רשימת ה\u0003כריתות\u0004 (במשנה שלנו) \u0003לא תני\u0004 \u0005[אינו שונה]\u0006 \u0003ידעוני,\u0004 ומשמע שמביא חטאת אחת על שניהם?","\u0003אמר ר' יוחנן: הואיל ושניהם בלאו אחד נאמרו\u0004 — \"אל תפנו אל האובות ואל הידעונים\" (ויקרא יט, לא). ושואלים: \u0003ונימא\u0004 \u0005[ושיאמר]\u0006 במשנתנו \u0003ידעוני, ולא נימא\u0004 \u0005[ולא יאמר]\u0006 \u0003בעל אוב!\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 הזכיר התנא בעל אוב \u0003הואיל ופתח הכתוב בבעל אוב.\u0004","\u0003וריש לקיש אמר:\u0004 לא הזכיר ידעוני בכריתות \u0003הואיל ואין בו מעשה,\u0004 ואין מביאים חטאת אלא על לאו שיש בו מעשה. ושואלים: \u0003וריש לקיש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוחנן,\u0004 שלא נזכר ידעוני במשנתנו הואיל ושניהם בלאו אחד נאמרו?","\u0003אמר רב פפא: דהא\u0004 \u0005[שהרי]\u0006 \u0003חלוקין הן במיתות,\u0004 שבכל אחד מהם כשלעצמו יש חיוב מיתה, שהרי נאמר: \"אוב או ידעוני מות יומתו\" (שם כ, כז). ומעירים: ור' \u0003יוחנן אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך: חלוקה\u0004 של \u0003לאו\u0004 לכל עבירה בנפרד \u0003הוי\u0004 \u0005[הריהי]\u0006 \u0003חלוקה\u0004 לענין חטאת, \u0003חלוקה\u0004 של \u0003מיתה לא הויא\u0004 \u0005[אינה]\u0006 \u0003חלוקה.\u0004","ושואלים: ור' \u0003יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כריש לקיש?\u0004 ומשיבים, \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מאן תנא\u0004 \u0005[מיהו ששנה]\u0006 את רשימת ה\u0003כריתות\u0004 — שיטת \u0003ר' עקיבא היא,\u0004 שאמר: \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003מעשה\u0004 לענין חיוב חטאת.","\u0003וריש לקיש,\u0004 מה הוא אומר? \u0003נהי\u0004 \u0005[אף]\u0006 ש\u0003ר' עקיבא לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003מעשה רבה\u0004 \u0005[גדול]\u0006 לחייב חטאת, מכל מקום \u0003מעשה זוטא\u0004 \u0005[קטן]\u0006 \u0003בעי\u0004 \u0005[צריך],\u0006 כלומר, שיהיה בו משהו של מעשה, וידעוני אינו עושה דבר, אלא הקול יוצא מאליו מפיו.","ושואלים: \u0003בעל אוב מאי מעשה אית ביה\u0004 \u0005[מה מעשה יש בו]?\u0006 ומשיבים: \u0003הקשת זרועותיו,\u0004 שמקיש בהן כדי להעלות את רוח המת, \u0003הוי\u0004 \u0005[הריהי]\u0006 נחשבת למעשה. ושואלים: ולשיטתו, \u0003מגדף,\u0004 ששנינו במשנתנו, \u0003מאי מעשה אית ביה\u0004 \u0005[מה מעשה יש בו]?\u0006 ומשיבים: \u0003עקימת שפתיו\u0004 בתוך דיבורו \u0003הוי\u0004 \u0005[הריהי]\u0006 נחשבת למעשה.","ומעירים: \u0003קא סלקא דעתין\u0004 \u0005[עלה\u0006 מלכתחילה \u0005בדעתנו]\u0006 כי לשיטת ריש לקיש \u0003הקשת זרועותיו הוי\u0004 \u0005[הריהו]\u0006 \u0003מעשה זוטא\u0004 \u0005[קטן]\u0006 \u0003אפילו לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים].\u0006 ומשום כך \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003בעבודה זרה אינו חייב אלא על דבר שיש בו מעשה, כגון שזיבח\u0004 (שחט), \u0003וקיטר\u0004 (העלה באש), \u0003וניסך, והשתחוה. וקשיא לן\u0004 \u0005[ו\u0006היה קשה לנו], \u0003השתחואה\u0004 הרי \u0003לית\u0004 \u0005[אין]\u0006 \u0003בה מעשה!\u0004","\u0003ואמר ריש לקיש: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת ר' \u0003עקיבא היא,\u0004 שאמר: \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003מעשה\u0004 כדי שיתחייב בו. ור' \u0003יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 לשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003כפיפת קומתו\u0004 כשמשתחווה \u0003הוי\u0004 \u0005[הריהי]\u0006 נחשבת \u0003מעשה. מכלל\u0004 הדברים אתה למד \u0003דסבירא ליה\u0004 \u0005[שמסתבר לו]\u0006 \u0003לריש לקיש אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים]\u0006 שכפיפת \u0003קומתו לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003לא הוי\u0004 \u0005[איננה]\u0006 נחשבת \u0003מעשה.\u0004 ואם השתחוואה אינה נחשבת מעשה, \u0003הקשת זרועותיו הוי\u0004 \u0005[הריהי]\u0006 \u0003מעשה?!\u0004","\u0003ואלא כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003ריש לקיש\u0004 שהקשת \u0003זרועותיו הוי\u0004 \u0005[הריהי]\u0006 נחשבת \u0003מעשה זוטא\u0004 \u0005[קטן],\u0006 הרי זה \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של ר' \u0003עקיבא, אבל לרבנן\u0004 \u0005[לחכמים]\u0006 \u0003לא הוי\u0004 \u0005[איננה]\u0006 נחשבת \u0003מעשה\u0004 כלל.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אמאי תני\u0004 \u0005[מדוע\u0006 הוא \u0005שונה]\u0006 במשנתנו לשיטת חכמים: \u0003יצא מגדף שאין בו מעשה? ניתני\u0004 \u0005[שישנה]:\u0006 \u0003יצא מגדף ובעל אוב,\u0004 שבשניהם אין מעשה! ומשיבים: זו אינה קושיה חמורה, כי \u0003חדא מתרתי קתני\u0004 \u0005[אחת משתים הוא שונה],\u0006 והביא רק דוגמה אחת.","ושואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 \u0003בעל אוב ולא ליתני\u0004 \u0005[ושלא ישנה]\u0006 \u0003מגדף!\u0004 ומשיבים: \u0003מגדף איצטריך ליה\u0004 \u0005[נצרך לו לומר],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב כרת דיליה\u0004 \u0005[ונאמר הכרת שלו]\u0006 \u0003במקום קרבן,\u0004 בסמוך לחיוב החטאת (ראה במדבר טו, כח—ל), \u0003אימא מודה ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לרבי עקיבא\u0004 שגם על זה מביאים, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003לא.\u0004","\u0003עולא אמר:\u0004 טעם הדבר שלא נאמר לשיטת חכמים \"יצא מגדף ובעל אוב שאין בו מעשה\", הוא משום ש\u0003בעל אוב דקתני\u0004 \u0005[שהוא שונה\u0006 במשנתנו\u0005]\u0006 הרי זה \u0003במקטר לשד\u0004 הממונה על כישוף זה, וההקטרה היא מעשה גמור. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: אם כן, היינו\u0004 \u0005[זהו]\u0006 \u0003עובד עבודה זרה\u0004 שכבר שנינו במשנתנו, ואין מקום לשנותו ככרת בפני עצמו! \u0003אלא אמר רבא:\u0004 הכוונה היא ל\u0003מקטר לשד\u0004 כמעשה כישוף, \u0003על מנת לחברו,\u0004 כלומר, כדי להביאו אליו ולהשתמש בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אם כן, היינו\u0004 \u0005[זהו]\u0006 \u0003חובר חבר,\u0004 שהוא איסור בפני עצמו בתורה (דברים יח, א), ואין בו כרת! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003התורה אמרה\u0004 כי \u0003חובר חבר כגון זה,\u0004 שמקטר לשד, דינו \u0003בסקילה,\u0004 כחלק מדין בעל אוב, ולכן גם כרת יש בו. שאל אותו אביי: \u0003ואלא חובר חבר\u0004 שהוא \u0003ב\u0004איסור \u0003לאו\u0004 בלבד, שנאמר: \"לא ימצא בך... וחובר חבר\" (שם י—יא), \u0003הדין הוא\u0004 \u0005[איזה הוא]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"וחובר חבר\"\u0004 — \u0003אחד חובר גדול,\u0004 אוסף חיות גדולות, \u0003ואחד חובר קטן, ואפילו חובר לנחשים ועקרבים\u0004 — \u0003חייב.\u0004 ובפרטי ענין זה \u0003אמר אביי: האי מאן דבעי למיצמד זיבורא ועקרבא\u0004 \u0005[מי שרוצה להצמיד,\u0006 לחבר \u0005צירעה ועקרב]\u0006 — \u0003אסור, ואי קאתו בתריה\u0004 \u0005[ואם הם באים אחריו],\u0006 והוא רוצה להינצל מהם — \u0003שרי\u0004 \u0005[מותר].\u0006","ושואלים, לר' \u0003יוחנן\u0004 שאמר: \u0003כפיפת קומתו הוי\u0004 \u0005[הריהי]\u0006 נחשבת \u0003מעשה\u0004 לשיטת חכמים, \u0003עקימת\u0004"],["\u0003שפתיו נהוי\u0004 \u0005[תהיה,\u0006 תיחשב\u0005]\u0006\u0003 מעשה גבי\u0004 \u0005[אצל]\u0006 \u0003מגדף,\u0004 ומדוע לא הוזכר במשנה? \u0003אמר רבא: שאני\u0004 \u0005[שונה]\u0006 \u0003מגדף,\u0004 שאין עקימת שפתיו נחשבת כמעשה לחייב חטאת, \u0003הואיל וישנו בלב,\u0004 כלומר שעיקר העבירה היא במה שהוא מתכוון בליבו, ולא דווקא במה שאומר בשפתיו, \u0003אבל בעלמא\u0004 \u0005[בדרך כלל]\u0006 \u0003עקימת שפתיו הוי\u0004 \u0005[הריהי]\u0006 נחשבת \u0003מעשה.\u0004","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006\u0003 רבי זירא\u0004 ממה ששנינו לגבי ענין אחר: \u0003יצאו עדים זוממין שאין בו מעשה, ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006\u0003 \"על פי\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בהן,\u0004 שהם צריכים להעיד בפיהם, והרי זאת עקימת שפתיים! \u0003אמר רבא: שאני\u0004 \u0005[שונים]\u0006 \u0003עדים זוממין הואיל וישנן בראייה,\u0004 שעיקרה של עדות היא הראיה, שאינה מעשה.","שנינו במשנה בתוך רשימת הכריתות שמביאין חטאת על שגגתן: \u0003האוכל חלב.\u0004 ובענין דומה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"כל חלב שור וכשב ועז לא תאכלו\"\u0004 (ויקרא ז, כג) — בא \u0003לחייב\u0004 מלקות \u0003על כל אחת ואחת,\u0004 שאם אכל חלב שור, חלב עז וחלב כבש — חייב שלושה עונשי מלקות, כדין העובר על מצות לא תעשה שבתורה, אלו \u0003דברי ר' ישמעאל. וחכמים אומרים: אינו חייב אלא אחת.\u0004","ומציעים: \u0003נימא בהא קמיפלגי\u0004 \u0005[האם נאמר שב\u0006עקרון \u0005זה חלוקים הם],\u0006 ש\u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003לוקין על לאו שבכללות,\u0004 כלומר, כשיש לאו שכולל כמה פרטים — לוקים על כל אחד ואחד מן הפרטים, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין לוקין על לאו שבכללות?\u0004","ודוחים: \u0003לעולם סבר\u0004 \u0005[סבור]\u0006 \u0005ר' ישמעאל:\u0006 \u0003אין לוקין על לאו שבכללות, ושאני הכא דמייתרי ליה קראי\u0004 \u0005[ושונה כאן שמיותרים לו הכתובים],\u0006 \u0003נכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 רק \u0003\"כל חלב לא תאכלו\", \"שור וכשב ועז\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לחלק\u0004 במקרה זה מלקות לכל לאו ולאו.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 משיבים על כך: אין זה כתוב מיותר, שכן \u0003אי לא כתיב\u0004 \u0005[אם לא היה כתוב]:\u0006 \u0003\"שור וכשב ועז\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אפילו חלב חיה\u0004 טהורה (כגון צבי) \u0003במשמע,\u0004 שגם הוא אסור — \u0003להכי כתב\u0004 \u0005[משום כך כתבה\u0006 התורה\u0005]\u0006 \u0003\"שור כשב ועז\", למימרא\u0004 \u0005[לומר]:\u0006 שחלב \u0003שור וכשב ועז הוא\u0004 שאסור, \u0003אבל\u0004 של \u0003חיה שרי\u0004 \u0005[מותר].\u0006","ומקשים על הסבר זה למחלוקת: אם כן, \u0003שפיר קאמרי ליה\u0004 \u0005[יפה אומרים לו]\u0006 חכמים לר' ישמעאל, שהרי ודאי צריך הכתוב לומר דבר זה! \u0003אלא היינו טעמא\u0004 \u0005[זה טעמו]\u0006 של ר' ישמעאל, \u0003דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003אם כן,\u0004 שבא רק למעט חיה, \u0003לכתוב\u0004 \u0005[שיכתוב]\u0006 רק \u0003\"כל חלב שור לא תאכלו\", \"כשב ועז\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר \u0003לחלק\u0004 מלקות לכל אחד.","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אי כתב רחמנא\u0004 \u0005[אילו כתבה התורה]\u0006 רק \u0003\"כל חלב שור\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003\"שור\" \"שור\" מסיני,\u0004 שנאסר לכל בהמה לעלות להר, שנאמר \"אם בהמה אם איש לא יחיה\" (שמות יט, יג),","\u0003מה גבי\u0004 \u0005[אצל]\u0006 \u0003סיני,\u0004 אף על פי שנזכרה רק בהמה, \u0003חיה ועוף כיוצא בהן, אף גבי\u0004 \u0005[אצל]\u0006 \u0003אכילה\u0004 של חלב — \u0003חיה ועוף כיוצא בהן, להכי כתב רחמנא\u0004 \u0005[משום כך כתבה התורה]\u0006 \"כל חלב \u0003שור וכשב ועז\", למימרא דהני\u0004 \u0005[לומר ש\u0006חלבם של \u0005אלו]\u0006 \u0003אסור, אבל\u0004 חלב \u0003חיה ועוף שרי\u0004 \u0005[מותר].\u0006","ומקשים: גם לפי הסבר זה, \u0003שפיר קא אמרי ליה\u0004 \u0005[יפה אומרים לו]\u0006 חכמים לר' ישמעאל! \u0003אלא היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של ר' ישמעאל, \u0003דקסבר\u0004 \u0005[שסבור הוא]:\u0006 מדוע הוזכרו שור וכשב ועז? \u0003נכתוב\u0004 \u0005[שיכתוב]\u0006 רק: \u0003\"כל חלב כשב לא תאכלו\", אי נמי\u0004 \u0005[או גם כן]\u0006 שיכתוב: \u0003\"כל חלב עז לא תאכלו\", \"שור וכשב ועז\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לחלק.\u0004","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 כתוב זה אינו מיותר, שכן \u0003אי כתב\u0004 \u0005[אילו כתבה\u0006 התורה\u0005]\u0006 רק \u0003\"כל חלב כשב\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003חלב כשב אסור, ו\u0004חלב של \u0003שור ועז שרי\u0004 \u0005[מותר].\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003מאי אולמיה\u0004 \u0005[מה תוקפו,\u0006 חומרתו\u0005]\u0006 של \u0003כשב?\u0004 הייתי אומר: \u0003משום\u0004 ש\u0003נתרבה באליה\u0004 (הזנב) שלו, שצריך להקריבה על גבי המזבח (ויקרא ג, ט) מה שאין בשור ועז,","\u0003וכדתנא\u0004 \u0005[וכמו ששנה]\u0006 \u0003ר' חנניא: למה מנה הכתוב\u0004 בנפרד מצות הקטרת \u0003אימורין ב\u0004בכור \u0003שור, ואימורים ב\u0004בכור \u0003כשב, ואימורים ב\u0004בכור \u0003עז, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אך בכור שור\u0004 או בכור כשב או בכור עז... ואת חלבם (האימורים, החלקים המובחרים שלהם) תקטיר אשה לריח ניחוח לה'\" (במדבר יח, יז)?","\u0003צריכי\u0004 \u0005[צריכים]\u0006 הם, \u0003דאי כתב\u0004 \u0005[שאילו כתבה\u0006 התורה\u0005]\u0006 רק \u0003שור, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כשב ועז לא ילפינן מיניה\u0004 \u0005[אינם למדים ממנו],\u0006 מפני \u0003דאיכא למיפרך\u0004 \u0005[שיש מקום לפרוך\u0006 את הלימוד ולומר\u0005]\u0006\u0003: מה לשור,\u0004 שיש בו חומרה, \u0003שכן נתרבה בנסכים,\u0004 שהנסכים שמביאים עם קרבן מן הבקר מרובים משל עז וכבש.","ואם תאמר: \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003בכשב ונילף\u0004 \u0005[ונלמד]\u0006 \u0003שור ועז מכשב\u0004 — \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]\u0006 ולומר: \u0003מה לכשב שכן נתרבה באליה.\u0004","ואם תאמר: \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003עז ונילף\u0004 \u0005[ונלמד]\u0006 \u0003שור וכשב מיניה\u0004 \u0005[ממנו]\u0006 — \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]:\u0006 \u0003מה לעז שכן נתרבה אצל עבודה זרה,\u0004 שבחטאת עבודה זרה מביאים דווקא עז (ראה במדבר טו, כז), ולא כבשה, כבשאר חטאות.","ולגופם של דברים אלו שואלים: \u0003מן חד לא ילפינן\u0004 \u0005[מאחד\u0006 מהם \u0005אין אנו למדים]\u0006 לשנים האחרים, \u0003נכתוב תרתי ונילף חדא מתרתי\u0004 \u0005[שתכתוב\u0006 התורה הקטרת אימורים ב\u0005שתים מהן ונלמד אחת משתים]!\u0006 ומשיבים: \u0003הי דין\u0004 \u0005[איזה]\u0006 אחד נלמד משנים? אם \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003שור מכשב ועז\u0004 — \u0003אית להון פירכא\u0004 \u0005[יש להם פירכה]:\u0006 \u0003מה לכשב ועז שכן נתרבו אצל הפסח,\u0004 שבקרבן פסח רק גדי וטלה כשרים, ולא שור!","\u0003לא נכתוב\u0004 \u0005[תכתוב]\u0006 התורה \u0003כשב ונילף\u0004 \u0005[ונלמד]\u0006 \u0003משור ועז\u0004 — \u0003אית להון פירכא\u0004 \u0005[יש להם פירכה]:\u0006 \u0003מה לשור ועז שכן נתרבה אצל עבודה זרה,\u0004 שציבור ששגג באיסור עבודה זרה מביא פר לחטאת (שם כד), ויחיד מביא עז ולא כבשה!","אלא מה תאמר, \u0003לא נכתוב\u0004 \u0005[תכתוב]\u0006 התורה \u0003עז ונילף\u0004 \u0005[ונלמד]\u0006 \u0003משור וכשב\u0004 — \u0003אית להון פירכא\u0004 \u0005[יש להם פירכה]:\u0006 \u0003מה לשור וכשב שכן יש בו צד ריבוי\u0004 לגבי המזבח, ביחס לעז, שנסכי הפר מרובים, ואליית הכבש מוקטרת! \u0003הלכך לא ילפי מהדדי\u0004 \u0005[משום כך לא למדים הם זה מזה].\u0006 ושבים לעיקר הענין, לגבי איסור חלב.","ואומרים: אם כן, \u0003שפיר קא אמרי ליה\u0004 \u0005[יפה אומרים לו]\u0006 חכמים לר' ישמעאל, ואין כאן ייתור ללמוד ממנו ללקות בנפרד על כל אחד מן החלבים! \u0003אלא לעולם טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' ישמעאל כדאמרינן מעיקרא\u0004 \u0005[כמו שאמרנו מתחילה],\u0006 ש\u0003אם כן נכתוב\u0004 \u0005[שתכתוב]\u0006 התורה \u0003\"כל חלב\" ולישתוק\u0004 \u0005[ושלא תוסיף].\u0006 \u0003מאי אמרת\u0004 \u0005[מה אומר אתה],\u0006 \u0003האי דכתב\u0004 \u0005[זה שכתבה]\u0006 התורה \u0003\"שור וכשב ועז\"\u0004 בא כדי \u0003למשרי\u0004 \u0005[להתיר]\u0006 \u0003חלב חיה?\u0004","לא הוצרכנו לכך, \u0003הא כי כתב קרא\u0004 \u0005[הרי כאשר נכתב המקרא]\u0006 של איסור החלב — \u0003בעניינא\u0004 \u0005[בענין]\u0006 של \u0003קדשים\u0004 (קרבנות) הוא נאמר, שלאחר האיסור על אכילת חלב נאמר \"כי כל אוכל חלב מן הבהמה אשר יקריבו ממנה אשה לה' ונכרתה\" וכו' (ויקרא ז, כה), \u0003ו\u0004יש לדרוש את הכתוב במידת \u0003דבר למד מעניינו,\u0004 והואיל ואין מביאים קרבן אלא מן הבהמה — אף דין חלב לא נאמר אלא בבהמה ולא בחיה.","ותמהים: האם \u0003מכלל\u0004 הדברים אתה למד \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 במידת \u0003דבר למד מעניינו?\u0004 והלא אין חולק על כך! ודוחים: \u0003לא, דכולי עלמא ילפינן\u0004 \u0005[לדעת הכל למדים אנו]\u0006 \u0003דבר הלמד מעניינו, והכא בהא פליגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003רבי ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003למידין לאו מלאו (בין מלאו ובין מלאו דכרת),\u0004 שאת הלאו","\u0003\"כל חלב שור וכשב ועז\u0004 לא תאכלו\" (שם כג), למדים \u0003מ\u0004ה\u0003לאו\u0004 של \u0003\"חקת עולם לדרתיכם בכל מושבתיכם כל חלב וכל דם לא תאכלו\"\u0004 (שם ג, יז), \u0003דכתיב בעניינא\u0004 \u0005[שנאמר בענין]\u0006 של \u0003קדשים, ו\u0004הואיל ו\u0003בקדשים לא אית בהון\u0004 \u0005[אין בהם]\u0006 \u0003חיה,\u0004 יש לומר כי \u0003אף\u0004 הלאו \u0003\"כל חלב שור\", כי כתיב ליה סתמא ליכא לספוקי\u0004 \u0005[כאשר הוא נאמר סתם, אין להסתפק]\u0006 שמא מדובר \u0003בחיה, הלכך\u0004 \u0005[משום כך]\u0006 מה שנזכרו \u0003\"שור וכשב ועז\" לחלק הוא דאתא\u0004 \u0005[שבא],\u0006 \u0003לחייב על כל אחת ואחת.\u0004","וכל זה הוא לומר שיש איסור בכל אחד מהם, \u0003ו\u0004אולם לחלק ביניהם לענין מלקות, כשאכלם בבת אחת — \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003לאו\u0004 של \u0003\"כל חלב\" ולאו\u0004 של \u0003\"חקת עולם\" מכרת\u0004 של \u0003\"כי כל אוכל חלב מן הבהמה אשר יקריבו ממנה\u0004 אשה לה' ונכרתה הנפש האוכלת מעמיה\" (שם כה), \u0003מה ההוא לחלק\u0004 שאם אכל בשגגה אחת חלב של שור, של עז ושל כבש, מביא חטאת על כל אחד — \u0003אף הדין\u0004 \u0005[זה]\u0006 \u0003לחלק.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 הם סבורים ש\u0003לאו מלאו ילפינן\u0004 \u0005[למדים אנו],\u0006 \u0003לאו מכרת לא ילפינן\u0004 \u0005[אין אנו למדים].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003היינו טעמייהו דרבנן\u0004 \u0005[זה הוא טעמם של חכמים],\u0006 \u0003כדאמר ליה\u0004 \u0005[כמו שאמר לו]\u0006 \u0003רב מרי לרב זביד\u0004 כששאל אותו בענין אחר: \u0003אלא מעתה,\u0004 שדייקנו מן הכתוב כי אליה של כבש הריהי בכלל חלב הקרבנות שמועלים בו, אם כן \u0003אליה\u0004 של \u0003חולין תיתסר\u0004 \u0005[תיאסר],\u0006 משום \u0003חלב! אמר ליה\u0004 \u0005[לו]\u0006 רב זביד: \u0003עליך,\u0004 על שאלתך \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כל חלב שור וכשב ועז\u0004 לא תאכלו\" (שם), לומר: \u0003דבר השוה בשלשתן בעינן\u0004 \u0005[צריכים אנו]\u0006 באיסור חלב, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 משום שבשור ובעז אין אליה.","\u0003הלכך\u0004 \u0005[על כן]\u0006 יש לומר גם לענייננו: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 הכתוב \u0003\"שור וכשב ועז\"\u0004 — \u0003למישרי\u0004 \u0005[להתיר]\u0006 \u0003אליה\u0004 של \u0003חולין הוא דאתא\u0004 \u0005[שבא],\u0006 ואין ללמוד מכאן חילוק מלקות לכל אחד. \u0003ור' ישמעאל אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 כנגד זה: \u0003אם כן,\u0004 שרק כדי ללמד דבר זה, \u0003לימא קרא\u0004 \u0005[שיאמר המקרא]\u0006 \u0003\"כל חלב שור וכשב\", עז למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא \u0003לחלק\u0004 מלקות לכל אחד.","\u0003אמר ר' חנינא:\u0004 אף שר' ישמעאל סבור כי האוכל חלב שור, כבש ועז לוקה על כל אחד משום אכילת חלב \u0003מודה ר' ישמעאל לענין קרבן, ש\u0004אם אכל חלב שור, חלב עז וחלב כבש בהעלם אחד — \u0003אין מביא אלא חטאת אחת, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003דלא דמי הדין לאו\u0004 \u0005[שלא דומה הלאו הזה]\u0006 \u0003ללאו\u0004 של \u0003עריות,\u0004 שחייב חטאת על כל אחת מן העריות כשבא עליהן בהעלם אחד (כפי שלמדנו לעיל ב,ב מ\"אחותו\"), מפני ששם נאמר לאו נפרד לכל אחת, וכאן הרי יש לאו אחד לכל החלבים.","ובענין חטאת על אכילת חלב \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר בענין חיוב חטאת \"נפש כי תחטא בשגגה מכל מצוות ה' אשר לא תיעשנה ועשה מאחת מהנה\" (שם ד, ב), יש לדרוש כאילו נאמר \u0003\"ועשה אחת\" \"ועשה הנה\"\u0004 — \u0003לחייב על כל אחת ואחת,\u0004","\u0003שאם אכל חלב ו\u0004שוב אכל \u0003חלב,\u0004 אם היה זה מ\u0003שם אחד\u0004 כלומר, אותו סוג של חלב אסור, ואכלו \u0003בשני העלמות,\u0004 שאכל בשוגג, ונודע לו שחטא, ואכל שוב בשוגג ונודע לו — \u0003חייב שתים,\u0004 שתי חטאות. אם אכל חלב אסור משום \u0003שתי שמות,\u0004 כגון חלב שעל הכוליא וחלב שעל המעיים, \u0003בהעלם אחת\u0004 — \u0003חייב שתים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא לרב חסדא: בשלמא\u0004 \u0005[נניח]\u0006 אם אכל \u0003שם אחד בשני העלמות חייב שתים, משום\u0004 ש\u0003העלמות מחלקין,\u0004 שחיוב החטאת הוא במקרה שנעלם ממנו החטא ונודע לו, והרי כאן אירע הדבר פעמיים. \u0003אלא שני שמות בהעלם אחת אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב שתים? הא בעינן\u0004 \u0005[הרי\u0006 במקרה זה, שיש רק לאו אחד, \u0005צריכים אנו]\u0006 \u0003העלמות מוחלקין\u0004 כדי לחייב קרבנות נפרדים, \u0003וליכא\u0004 \u0005[ואין כאן]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון\u0004 שאכל \u0003חלב\u0004 של \u0003נותר,\u0004 מן הקדשים שעבר זמן אכילתם, \u0003דמחייב\u0004 \u0005[ש\u0006הוא \u0005מתחייב\u0006 בכך\u0005]\u0006 גם \u0003משום\u0004 איסור אכילת \u0003נותר ו\u0004גם \u0003משום\u0004 איסור \u0003חלב. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן\u0004 אתה אומר, שמדובר בשני איסורים שונים, ולא בשני סוגי חלב, \u0003ניחייב נמי\u0004 \u0005[שיתחייב גם כן]\u0006 \u0003משום קודש\u0004 שהוא אוכל, וחייב על כך אשם מעילות!","\u0003אלא אמר רב ששת:\u0004 מדובר \u0003כגון\u0004 שאכל \u0003חלב\u0004 של \u0003הקדש, ו\u0004שיטת ר' \u0003יהודה היא,\u0004 המחייב שני עונשי מלקות משום אכילת חלב קדשים. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003אכל חלב נבלה,\u0004 או \u0003אכל חלב מוקדשין\u0004 — \u0003חייב שתים,\u0004 שני עונשי מלקות, משום חלב ומשום נבילה, או משום חלב ומשום איסור של אכילת קודש לזר. \u0003ר' יהודה אומר:\u0004 אכל \u0003חלב מוקדשין\u0004 — \u0003לוקה שלש,\u0004 שבחלב המוקדשים יש שני איסורים שונים של חלב (כמבואר להלן), בנוסף לעצם איסור אכילת קודש על ידי זר.","\u0003מחייכו עלה במערבא\u0004 \u0005[היו צוחקים על כך בארץ ישראל]\u0006 על העמדה זו: \u0003ונוקמה\u0004 \u0005[ושנעמיד\u0006 ברייתא זו\u0005]\u0006 שחייב חטאות נפרדות על שמות שונים של חלב, \u0003כגון\u0004 שאכל \u0003חלב\u0004 של \u0003שור וכשב ועז\u0004 בהעלם אחד, \u0003ו\u0004תאמר ששיטת \u0003ר' ישמעאל היא,\u0004 ש\u0003אמר: לוקה שלש\u0004 אם אכלם במזיד ובהתראה!"],["\u0003אלמא לא אוקמה\u0004 \u0005[מדוע לא העמיד אותה]\u0006\u0003 כר' ישמעאל,\u0004 מפני ש\u0003אמר ר' חנינא: מודה היה רבי ישמעאל לענין קרבן שאינו חייב אלא חטאת אחת,\u0004 ואולם לפי זה \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006\u0003 כ\u0004דעת ר' \u0003יהודה לא מתוקמא\u0004 \u0005[אי אפשר להעמידה],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ר' אליעזר: מודה היה רבי יהודה לענין קרבן שאין מביא אלא חטאת אחת!\u0004","\u0003אלא אמר ריש לקיש משום\u0004 החכם \u0003בר תאוטני: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 שחייב שתי חטאות על אכילת חלב משני שמות — \u0003כגון שאכלן בשני תמחויין\u0004 (קערות), \u0003ואליבא\u0004 \u0005[ולפי שיטתו]\u0006 של ר' \u0003יהושע,\u0004 שאמר: \u0003תמחויין מחלקים,\u0004 שאם אכל משני תמחויים שונים הרי זה כשתי עבירות שונות, וחייב על כל אחת לחוד.","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה ברייתא שהזכרנו: \u0003אכל חלב נבילה\u0004 — \u0003לוקה שתים,\u0004 שני עונשי מלקות, וכן אכל \u0003חלב מוקדשין\u0004 — \u0003לוקה שתים, רבי יהודה אומר:\u0004 אכל \u0003חלב מוקדשין\u0004 — \u0003לוקה שלש.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שיזבי לרבא: בשלמא\u0004 \u0005[נניח]\u0006\u0003 ל\u0004שיטת ר' \u0003יהודה, היינו דכתיבי קראי\u0004 \u0005[זהו שכתובים\u0006 שלושה \u0005מקראות]:\u0006 \u0003\"חקת עולם...\u0004 כל חלב וכל דם לא תאכלו\" (ויקרא ג, יז), \u0003\"כל חלב שור וכשב ועז לא תאכלו\"\u0004 (שם ז, כג), \u0003\"וכל זר לא יאכל קדש\"\u0004 (שם כב, י) — \u0003הא תלתא\u0004 \u0005[הרי שלושה]\u0006 \u0003לאוין\u0004 יש בכך, שנים לאיסור חלב של קדשים, שהרי שני כתובים אלו נאמרו בענין של קדשים, ועוד לאו של אכילת קדשים על ידי זר. \u0003אלא לרבנן מאי טעמייהו\u0004 \u0005[ל\u0006שיטת חכמים מה טעמם]?","ומשיבים: \u0003קסברי\u0004 \u0005[סבורים\u0006 הם\u0005]:\u0006 \u0003לאו\u0004 של \u0003\"חקת עולם\"\u0004 אמנם עוסק \u0003בקדשים, ו\u0004אולם ה\u0003לאו\u0004 של \u0003\"חלב שור\"\u0004 עוסק \u0003ב\u0004חלב \u0003חולין.\u0004 ומעירים: \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 המקראות של איסור החלב להיכתב גם בקדשים וגם בחולין,","\u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 \u0003בקדשים\u0004 בלבד (\"חוקת עולם\"), \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003קדשים הוא דחמירי\u0004 \u0005[שחמורים],\u0006 ולכן אמר הכתוב ש\u0003אסור חלבו, אבל חולין אימא\u0004 \u0005[אמור]\u0006 שלא — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]: \"\u0006\u0003כל חלב שור\".\u0004","\u0003ואי כתב\u0004 \u0005[ואם היתה כותבת]\u0006 רק: \u0003\"כל חלב שור\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003חלב\u0004 של \u0003חולין הוא\u0004 שאסור, \u0003משום\u0004 ש\u0003לא הותר\u0004 איסור חלב \u0003מכללו,\u0004 שלא נמצא בו איסור שהותר, \u0003אבל חלב מוקדשין\u0004 שהותר \u0003מכללו, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מ\u0004ש\u0003הותר בשרן\u0004 של קדשים באכילה — \u0003אישתרי נמי\u0004 \u0005[הותר גם כן]\u0006 \u0003חלבן,\u0004 על כן \u0003צריכי\u0004 \u0005[צריכים]\u0006 שייאמרו שני הכתובים.","\u0003ורבי יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003כי כתיב\u0004 \u0005[כאשר נאמר]\u0006\u0003 \"חלב שור\",\u0004 גם הוא \u0003בעניינא דקדשים כתיב\u0004 \u0005[בענין קדשים נאמר],\u0006 שנאמר שם: \"כי כל אוכל חלב מן הבהמה אשר יקריבו ממנה אשה לה' ונכרתה\" (שם ז, כה), והוא במידת \"דבר הלמד מעניינו\".","ושואלים: \u0003אלא מכלל\u0004 הדברים אתה אומר \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 בשיטת \u0003דבר הלמד מעניינו?\u0004 והרי אין חולק על כך!","ומשיבים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 למדים אנו במדת \u0003דבר הלמד מעניינו, ובהא קמיפלגי\u0004 \u0005[וב\u0006ענין \u0005זה הם חלוקים],\u0006 \u0003רבי יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003למידין\u0004 במדה זו גם \u0003לאו מלאו\u0004 אחר שכתוב באותו ענין (פרשה) \u0003ו\u0004גם \u0003לאו מכרת, ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לאו מלאו ילפינן\u0004 \u0005[למדים אנו],\u0006 \u0003לאו מכרת לא ילפינן\u0004 \u0005[אין אנו למדים],\u0006 והרי מדובר שם בכרת על חלב קדשים.","ושואלים: \u0003אלא ל\u0004דעת ר' \u0003יהודה,\u0004 \"חוקת עולם... \u0003כל חלב וכל דם לא תאכלו\"\u0004 (שם ג, יז) \u0003למאי אתא\u0004 \u0005[למה בא]?\u0006 והרי כבר למדנו איסור חלב קדשים מ\"חלב שור\"! ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך הוא לו]\u0006 כדי \u0003להקיש\u0004 אליו איסור דם, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על פסוק זה: \u0003\"כל חלב וכל דם לא תאכלו\", מה\u0004 אוכל \u0003חלב\u0004 קדשים \u0003לוקה\u0004 עליו \u0003שתים\u0004 — \u0003אף\u0004 אוכל \u0003דם\u0004 קדשים \u0003לוקה שתים,\u0004 אלו \u0003דברי ר' יהודה. וחכמים אומרים: אין בו\u0004 בדם \u0003אלא אזהרה אחת.\u0004 ושואלים: ולשיטת ר' יהודה, לשם מה נצרך ההיקש?","\u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003חלב\u0004 שלוקה \u0003שתים בלא היקישא\u0004 \u0005[היקש]\u0006 — מפני \u0003דכתב ביה תרי קראי\u0004 \u0005[שכתובים בו שני מקראות]\u0006\u0003: \"כל חלב וכל דם לא תאכלו\"\u0004 האמור כאן, וגם \u0003\"כל חלב שור וכשב\",\u0004 אם כן, \u0003דם נמי בלאו היקישא נילקי\u0004 \u0005[גם כן בלי ההיקש שילקה]\u0006 \u0003שתים, דכתיב ביה תרי לאוין\u0004 \u0005[ש\u0006הרי \u0005כתובים\u0006 גם \u0005בו שני\u0006 איסורי \u0005לאו]\u0006\u0003: \"כל חלב וכל דם לא תאכלו\"\u0004 האמור כאן, וכן נאמר \"\u0003וכל דם לא תאכלו בכל מושבתיכם לעוף ולבהמה\"\u0004 (שם ז, כו)!","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003מה חלב לוקה שלש,\u0004 שנים משום איסור חלב ואחד משום \"וכל זר לא יאכל קודש\" (שם כב, י), \u0003אף דם לוקה שלש.\u0004 וגם על כך שואלים: ולשם מה הוצרך ההיקש?","\u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003חלב\u0004 ש\u0003לוקה שלש?\u0004 מפני \u0003דכתיב ביה\u0004 \u0005[שכתובים בו]\u0006 \u0003הלין תרי לאוין\u0004 \u0005[אותם שני הלאוים\u0006 שהזכרנו\u0005]\u0006 \u0003ולאו\u0004 של \u0003זרות, הא תלתא\u0004 \u0005[הרי שלושה],\u0006 אם כן \u0003דם נמי\u0004 \u0005[גם כן]\u0006 יש בו שני לאוים ולאו של זרות!","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 ההיקש, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואיתמעיט\u0004 \u0005[והתמעט]\u0006 \u0003דם מטומאה\u0004 שהאוכל דם קדשים בטומאה אינו חייב על כך משום איסור אכילת קדשים בטומאה — \u0003ליתמעיט\u0004 \u0005[שיתמעט]\u0006 גם מאיסור אכילה ב\u0003זרות,\u0004 על כן \u0003קא משמע לן היקישא\u0004 \u0005[משמיע לנו ההיקש]\u0006 לחלב, שמאיסור זרות לא נתמעט.","ושואלים: \u0003ואלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 הסבורים כי יש בדם קדשים רק אזהרה אחת, ואם כן, אינו חייב עליו גם משום זרות, \u0003הקישא למאי אתא\u0004 \u0005[היקש\u0006 של דם לחלב \u0005למה בא]?\u0006","ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך הוא לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"כל חלב וכל דם לא תאכלו\", מה\u0004 איסור \u0003חלב מיוחד\u0004 לבעל חיים \u0003שחלבו חלוק מבשרו,\u0004 שהחלב אסור והבשר מותר, \u0003ו\u0004פשוט הדבר ש\u0003אין מצטרפין זה עם זה,\u0004 שאם אכל יחד חצי זית חלב וחצי זית בשר — אינו חייב על אכילת כזית איסור, \u0003אף\u0004 באיסור \u0003דם\u0004 מדובר בכל בעל חיים \u0003שדמו חלוק מבשרו,\u0004 שיש בהם שני איסורים שונים, ובמקרה זה אין הבשר והדם מצטרפים לכזית להתחייב משום אכילת איסור,","\u0003אוציא דם שרצים, הואיל\u0004 ש\u0003אין דמן חלוק מבשרן,\u0004 שאין איסור נפרד לדם השרץ — משום כך הבשר והדם \u0003מצטרפין\u0004 לכדי כזית של השרץ.","ושואלים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006הלכה \u0005זו מכאן יוצאת,\u0006 נלמדת\u0005]?\u0006 \u0003מהתם נפקא\u0004 \u0005[משם היא יוצאת],\u0006 שנאמר: \u0003\"וזה לכם הטמא\u0004 בשרץ\" (ויקרא יא, כט) — \u0003לימד על דם השרץ ו\u0004בשר \u0003השרץ שמצטרפין זה עם זה!\u0004","ומשיבים: \u0003אי לאו היקישא\u0004 \u0005[אם לא ההיקש]\u0006 האמור כאן, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 לצרף \u0003ל\u0004ענין \u0003טומאה\u0004 לשיעור כעדשה, \u0003אבל לאכילה אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003אשמעינן היקישא\u0004 \u0005[השמיע לנו ההיקש]\u0006 גם לענין \u0003אכילה.\u0004","\u0003אמר רבינא: הילכך\u0004 \u0005[משום כך],\u0006 לפי מה שאמרנו, \u0003דם נחש ובשרו מצטרפין\u0004 לשיעור כזית, להתחייב משום אכילת שרץ. ותוהים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]\u0006\u0003? היינו היקישא\u0004 \u0005[זהו ההיקש\u0006 עצמו\u0005]!\u0006 ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 רק \u0003שרץ דאיתרבי\u0004 \u0005[שהתרבה]\u0006 דמו \u0003לטומאה\u0004 כבשרו, כפי ששנינו — \u0003איתרבי\u0004 \u0005[התרבה]\u0006 גם לענין \u0003אכילה,\u0004 אבל \u0003נחש דלא איתרבי\u0004 \u0005[שלא התרבה]\u0006 דמו \u0003לטומאה,\u0004 שהרי אינו בכלל שמונה שרצים שפירט הכתוב לענין טומאה (שם כט—ל) — \u0003לא איתרבי\u0004 \u0005[התרבה]\u0006 דמו גם \u0003ל\u0004ענין איסור \u0003אכילה,\u0004 על כן \u0003קא משמע לן היקישא\u0004 \u0005[משמיע לנו ההיקש]\u0006 כי \u0003כל מילי\u0004 \u0005[דבר]\u0006 שאין \u0003דמו חלוק מבשרו משמע\u0004 מכאן שמצטרף.","\u0003אמר רבא: שלש כריתות האמורות בדם\u0004 (ויקרא ז, כז. שם יז, י. שם יד) \u0003למאי\u0004 \u0005[למה]\u0006 הם הוצרכו? \u0003אחת לדם חולין, ואחת לדם קדשים, ואחת לדם התמצית,\u0004 הדם שמתמצה מן הבהמה לאחר צאת הנפש.","ואומרים: \u0003הניחא\u0004 \u0005[זה נוח] ל\u0006דעת ר' \u0003יהודה, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]: דם התמצית\u0006 אסור רק \u0003באזהרה,\u0004 אבל אין בו כרת, ר' \u0003יהודה אומר: בכרת,\u0004","\u0003אלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 הכרת \u0003ההיא למאי אתא\u0004 \u0005[למה באה]?\u0006 \u0003ואפילו ל\u0004שיטת \u0003ר' יהודה,\u0004 הלא \u0003כרת\u0004 שיש בכך \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 \u0003מן\u0004 ריבוי הכתוב \u0003\"כל דם\"!\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על הכתוב \"...אשר יאכל כל דם וכו' והכרתי אותה\" (שם יז, י), \u0003רבי יהודה אומר:\u0004 יכול היה לומר \"אשר יאכל \u0003דם\", מה תלמוד לומר \"כל דם\"?\u0004","שאם היה כתוב \"דם\" \u0003אין לי אלא דם קדשים שהנפש יוצא בו,\u0004 שהוא הדם שמכפר, וכפי שנאמר מיד לאחר מכן: \"כי נפש הבשר בדם הוא ואני נתתיו לכם על המזבח לכפר\" (שם יא), אבל \u0003דם\u0004 בהמת \u0003חולין ודם התמצית\u0004 (אפילו בקדשים) שאין הנפש יוצאה בו, \u0003מנין\u0004 שיש בהם כרת? \u0003תלמוד לומר: \"כל דם\"!\u0004","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: שלוש כריתות שנאמרו בדם, \u0003אחד לדם חולין, ואחד לדם קדשים, ואחד לדם כיסוי\u0004 כלומר, לדם חיה ועוף, שמצוה לכסות את דמם (שם יג).","\u0003ואמר רבא: חמשה לאוין האמורין בדם למה? אחת לדם חולין, ואחת לדם קדשים, ואחת לדם כיסוי, ואחת לדם איברין, ואחת לדם התמצית.\u0004","\u0003אמר ר' אילא:\u0004 אם \u0003אכל\u0004 מחוץ לירושלים \u0003מעשר\u0004 שני של \u0003דגן ו\u0004של \u0003תירוש\u0004 (יין) \u0003ו\u0004של \u0003יצהר\u0004 (שמן) — \u0003לוקה שלש\u0004 פעמים. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין לוקין על לאו שבכללות,\u0004 ונאמר רק לאו אחד על כולם: \"לא תוכל לאכול בשעריך מעשר דגנך תירושך ויצהרך\" (דברים יב, יז)! ומשיבים: \u0003שאני הכא דמייתרי קראי\u0004 \u0005[שונה כאן שמיותרים המקראות],\u0006","\u0003מכדי כתב רחמנא\u0004 \u0005[הואיל וכתבה התורה]:\u0006 \u0003\"ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך\"\u0004 (שם יד, כג), ומכאן אנו למדים: \u0003בפנים,\u0004 בירושלים — \u0003אין\u0004 \u0005[כן],\u0006 אתה אוכל, \u0003בחוץ\u0004 — \u0003לא,\u0004 אם כן, \u0003למה לי דכתב רחמנא\u0004 \u0005[משום מה כתבה התורה]\u0006 שוב: \"\u0003לא תוכל לאכל בשעריך מעשר דגנך ותירשך ויצהרך\"?\u0004 אלא בא הדבר \u0003לחלק,\u0004 שבכל אחד מהם יש איסור לחוד.","ודוחים: \u0003אי מ\u0004הכתוב \u0003ההוא,\u0004 \"ואכלת לפני ה' אלקיך\" וכו', \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 שעוברים על כך \u0003ב\u0004איסור הבא מכלל \u0003עשה, אבל ב\u0004איסור \u0003לאו\u0004 (לא תעשה) \u0003אימא לא\u0004 \u0005[אמור\u0006 ש\u0005אינו\u0006 עובר\u0005],\u0006 \u0003אמטו להכי\u0004 \u0005[משום כך]\u0006"],["\u0003כתב רחמנא\u0004 \u0005[כתבה התורה]: \"\u0006\u0003לא תוכל\"\u0004 (דברים יב, יז) \u0003לאוקמה\u0004 \u0005[להעמיד אותה]\u0006 \u0003בלאו.\u0004","ומקשים: \u0003ועדיין לאו שבכללות הוא!\u0004 ומשיבים: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב]: \"\u0006\u0003לא תוכל לאכלם בשעריך\",\u0004 שהרי הוזכרו קודם לכן \"מעשרותיכם\" (שם יא), ואם כן לחזור ולפרט \u0003\"מעשר דגנך תירשך ויצהרך\" למה לי?\u0004 אין זה אלא כדי \u0003ליחודי\u0004 \u0005[לייחד]\u0006 איסור ומלקות ל\u0003אכילה דכל חד וחד\u0004 \u0005[של כל אחד ואחד].\u0006","ובענין זה \u0003אמר ר' יצחק: האוכל לחם, קלי\u0004 (חיטה קלויה) \u0003וכרמל\u0004 (גרגרי חיטה לחים) לפני זמן העומר — \u0003לוקה שלש\u0004 פעמים, שנאמר: \"ולחם וקלי וכרמל לא תאכלו עד עצם היום הזה עד הביאכם את קרבן אלהיכם\" (ויקרא כג, יד). ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין לוקין על לאו שבכללות!\u0004 ומשיבים: \u0003שאני הכא דמייתר קראי\u0004 \u0005[שונה כאן שמיותרים הכתובים],\u0006","\u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003לחם, ונילף\u0004 \u0005[ונלמד]\u0006 \u0003קלי וכרמל מיניה\u0004 \u0005[ממנו].\u0006 ודוחים: אין זה יתור, שכן \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]\u0006 לימוד זה, ולומר: \u0003מה ללחם שכן נתרבה אצל חלה,\u0004 שיש חיוב הפרשת חלה רק מלחם! ולכן הוצרכנו לקלי וכרמל.","ואומרים: על כל פנים יש יתור בכתוב, \u0003נכתוב\u0004 \u0005[שיכתוב]\u0006 רק \u0003קלי, ולא לכתוב\u0004 \u0005[יכתוב]\u0006 \u0003לחם\u0004 ולא כרמל, \u0003ונילף\u0004 \u0005[ונלמד]\u0006 שניהם \u0003מקלי.\u0004 ודוחים: \u0003לחם מקלי לא אתי\u0004 \u0005[אינו בא,\u0006 נלמד\u0005], משום דקלי איתיה בעיניה\u0006 \u0005[ישנו בעינו,\u0006 כמות שהוא\u0005],\u0006 וניתן היה לומר שרק תבואה שלא נשתנתה נאסרה קודם הקרבת העומר מן התבואה החדשה. אבל \u0003לחם לא איתיה בעיניה\u0004 \u0005[אינו בעינו],\u0006 משום שהוא כבר טחון ואפוי. וכן \u0003כרמל מקלי לא אתי\u0004 \u0005[אינו בא,\u0006 נלמד\u0005],\u0006 למרות שהוא בעינו, \u0003משום\u0004 שקלי \u0003נתרבה אצל מנחות,\u0004 שמנחת העומר באה מקלי, ואילו \u0003כרמל לא נתרבה אצל מנחות!\u0004","ואומרים: עדיין יש יתור, שאם כן \u0003נכתוב\u0004 \u0005[שיכתוב]\u0006 \u0003כרמל ונילף\u0004 \u0005[ונלמד]\u0006 \u0003לחם וקלי מיניה\u0004 \u0005[ממנו].\u0006 ודוחים, \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך]:\u0006 \u0003מה לכרמל שכן לא נשתנה מברייתו\u0004 כלל! ואומרים: מכל מקום יש כאן יתור, שכן גם אם \u0003מן חד לא ילפי\u0004 \u0005[\u0006שניים \u0005מאחד\u0006 מהם \u0005אין למדים],\u0006 \u0003נילף חדא מן תרין\u0004 \u0005[נלמד אחד משנים].\u0006 ודוחים: מאלו שניים רוצה אתה ללמוד על האחד?","\u0003לא נכתוב קרא\u0004 \u0005[שלא יכתוב המקרא]\u0006 \u0003לחם ונילף\u0004 \u0005[ונלמד]\u0006 אותו \u0003מקלי וכרמל\u0004 — \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]:\u0006 \u0003מה לקלי וכרמל דאיתנהון בעיניהון\u0004 \u0005[שישנם בעינם],\u0006 ולא נטחנו! \u0003לא נכתוב קרא\u0004 \u0005[שלא יכתוב המקרא]\u0006 \u0003כרמל ונילף\u0004 \u0005[ונלמד]\u0006 \u0003מלחם וקלי\u0004 — \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]:\u0006 \u0003מה ללחם וקלי שכן נתרבו אצל מנחות,\u0004 ואם כן כל אחד מהם נחוץ!","ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך] ר'\u0006 \u0003יצחק: לא נכתוב קרא\u0004 \u0005[שלא יכתוב המקרא]\u0006 \u0003קלי, ונילף\u0004 \u0005[ונלמד]\u0006 דינו \u0003מלחם וכרמל. מאי פרכת\u0004 \u0005[מה אתה פורך,\u0006 מקשה\u0005]\u0006\u0003? אי פרכת\u0004 \u0005[אם אתה פורך]:\u0006 \u0003מה ללחם שכן נתרבה אצל חלה\u0004 — \u0003כרמל יוכיח,\u0004 שאין בו חיוב חלה, ונאסר באכילה קודם העומר! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 שכרמל \u0003לא נשתנה מברייתו\u0004 — \u0003לחם יוכיח,\u0004 שנשתנה, ונאסר! \u0003הלכך\u0004 \u0005[משום כך]\u0006 \u0003לוקה\u0004 על כל אחד ואחד מהם, \u0003דמייתר\u0004 \u0005[שמיותר]\u0006 הכתוב בענין קלי. ומקשים, ועדיין, מנין שלוקה על כל אחד מהם?","\u0003ואימא\u0004 \u0005[ואמור]:\u0006 על אכילת \u0003קלי דמייתר מחייב חדא\u0004 \u0005[שהוא מיותר חייב אחת],\u0006 \u0003אכולהון מחייב חדא\u0004 \u0005[על כולם,\u0006 לחם וכרמל, \u0005יהיה חייב\u0006 גם כן \u0005אחת],\u0006 שהרי זה לאו שבכללות! ומשיבים: \u0003אם כן,\u0004 שיש לקלי דין בפני עצמו — \u0003נכתוב קרא\u0004 \u0005[שיכתוב המקרא]:\u0006 \u0003\"לחם כרמל וקלי\", אי נמי נכתוב\u0004 \u0005[או גם כן שיכתוב]:\u0006 \u0003\"קלי ולחם וכרמל\", אמאי\u0004 \u0005[מדוע]\u0006 \u0003כתב לקלי באמצע? הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003לחם ב\u0004עונש של \u0003קלי נחייב\u0004 \u0005[יתחייב]\u0006\u0003, ו\u0004כן \u0003כרמל נחייב\u0004 \u0005[יתחייב]\u0006 \u0003ב\u0004עונש של \u0003קלי.\u0004","בעניין אוכל פיגול ונותר, ששנינו במשנה בכלל חייבי הכרת, \u0003אמר ר' ינאי: לעולם אל תהי גזירה שוה קלה בעיניך, שהרי פיגול אחד מגופי תורה\u0004 הוא, שהאוכל מבשר קרבן שנעשתה עבודתו על מנת להקריבו או לאוכלו לאחר זמנו — חייב כרת, \u0003ולא לימדו הכתוב אלא מגזירה שוה.\u0004","ומבארים, שאמר \u0003רבי יוחנן: תני\u0004 \u0005[שנה]\u0006 \u0003זבדא בר לוי\u0004 בברייתא: \u0003נאמר להלן\u0004 לגבי נותר מן הקדשים לאחר זמנם: \u0003\"ואוכליו עונו ישא\u0004 וכו' ונכרתה\" (ויקרא יט, ח), \u0003ונאמר כאן\u0004 במחשבת חוץ לזמנו: \u0003\"והנפש האכלת ממנו עונה תשא\"\u0004 (שם ז, יח), \u0003מה להלן כרת\u0004 — \u0003אף כאן\u0004 העונש הוא \u0003כרת.\u0004","\u0003אמר ר' סימאי: לעולם אל תהי גזירה שוה קלה בעיניך, שהרי\u0004 חיוב כרת על אכילת \u0003נותר,\u0004 ממנו למדנו כרת לעניין פיגול, \u0003אחד מגופי תורה\u0004 הוא, \u0003ו\u0004הוא עצמו \u0003לא לימדו הכתוב אלא מגזירה שוה.\u0004","ומבארים: \u0003מאי היא\u0004 \u0005[מה הוא]?\u0006 שהוא \u0003יליף\u0004 \u0005[לומד]\u0006 מגזירה שווה \"\u0003קדש\" \"קדש\"\u0004 שהכתוב \"ואוכליו עונו ישא\" (שם יט, ח) עוסק בנותר, כיצד? נאמר \u0003\"ואוכליו עונו ישא כי את קדש ה' חלל\"\u0004 (שם) \u0003וכתיב\u0004 \u0005[ונאמר]: \"\u0006\u0003ושרפת את הנותר באש כי קדש\u0004 הוא\" (שמות כט, לד), מה שם מדובר בנותר — אף כאן מדובר בנותר.","וכן \u0003אמר אביי: לעולם אל תהי גזירה שוה קלה בעיניך, שהרי בתו מאנוסתו\u0004 שאם בא עליה חייב כרת — \u0003הן הן גופי תורה, ולא לימדה הכתוב אלא מגזירה שוה.\u0004","שאמר \u0003רבא, אמר לי ר' יצחק בר אבדימי: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר מגזירה שווה \"\u0003הנה\" \"הנה\" לאיסורא\u0004 \u0005[ל\u0006ענין \u0005איסור],\u0006 וכן","\u0003אתא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 מה שכתוב \"\u0003זמה\" \"זמה\" ל\u0004ענין עונש בשרפה (ראה בעיונים).","וכן \u0003אמר רב אשי: אל תהי גזירה שוה קלה בעיניך, שהרי נסקלים\u0004 כלומר, אלו שדינם בסקילה, ולא נאמר בהם הדבר במפורש, \u0003הן הן גופי תורה, ולא לימדה הכתוב אלא מגזירה שוה,\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006\u0003, נאמר כאן: \"דמיהם בם\"\u0004 (ויקרא כ, יא—טז), \u0003ונאמר באוב וידעוני:\u0004 \"באבן ירגמו אותם \u0003דמיהם בם\"\u0004 (שם כז), \u0003מה להלן בסקילה\u0004 — \u0003אף כאן בסקילה.\u0004","שנינו במשנה ברשימת חייבי הכרת: \u0003המפטם\u0004 (הרוקח) \u0003את השמן\u0004 כמו שעשה משה במדבר למשוח את המשכן וכליו. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המפטם את השמן ללמוד בו\u0004 כיצד לעשותו, או שעושה אותו כדי \u0003למוסרו לציבור\u0004 — \u0003פטור,\u0004 ואם עשהו כדי \u0003לסוך\u0004 בו — \u0003חייב. ו\u0004אולם \u0003הסך ממנו\u0004 — \u0003פטור,\u0004 למרות שנעשה כדי לסוך ממנו, \u0003לפי ש\u0004לענין איסור הסיכה — \u0003אין חייבין אלא על סיכת שמן המשחה שעשה משה בלבד,\u0004 שנאמר: \"ואשר יתן ממנו על זר\" (שמות ל, לג) — מזה שעשה משה.","ומעתה דנים בפרטי הדברים: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ללמוד בו\u0004 או \u0003על מנת למוסרו לציבור\u0004 — \u0003פטור.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו ממה שנאמר \u0003\"מתכנתו\"\u0004 (שם ל, לב) בגזירה שווה \u0003מן\u0004 מה שנאמר \u0003\"במתכונתה\"\u0004 ב\u0003קטרת\u0004 (שם לז), והרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003לגבי קטרת:\u0004 \"במתכונתה \u0003לא תעשו לכם\",\u0004 ויש בכך הדגשה: \u0003לכם,\u0004 לצרככם, \u0003הוא\u0004 שאסור לעשות במתכונתה, \u0003אבל\u0004 כדי \u0003למוסרו לציבור\u0004 — \u0003פטור,\u0004 ומתוך כך אנו למדים כי ל\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שמן\u0004 המשחה \u0003נמי\u0004 \u0005[גם כן],\u0006 אם עשאו כדי \u0003למוסרו לציבור\u0004 — \u0003פטור.\u0004","ושואלים: מכיון שיש כאן גזירה שווה, \u0003ותיהדר\u0004 \u0005[ותחזור]\u0006 \u0003קטרת ונילף\u0004 \u0005[ותלמד]\u0006 \u0003משמן, מה שמן כי\u0004 \u0005[כאשר]\u0006 הוא \u0003מפטם\u0004 אותו \u0003לחציין,\u0004 ולא כל הכמות כאחת — \u0003פטור, אף קטרת נמי\u0004 \u0005[גם כן]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מפטם לחציין\u0004 — \u0003פטור! אלמה\u0004 \u0005[למה]\u0006 \u0003אמר רבא: קטרת שפטמה לחציין\u0004 — \u0003חייב, שמן שפטמו לחציין\u0004 — \u0003פטור?\u0004","ומשיבים, \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רבא: גבי\u0004 \u0005[אצל]\u0006 \u0003שמן כתיב\u0004 \u0005[נאמר]\u0006\u0003: \"ובמתכנתו לא תעשו כמוהו\",\u0004 ויש לדייק: \u0003כמוהו\u0004 בדיוק \u0003הוא\u0004 שאסור, \u0003אבל חציו שפיר דמי\u0004 \u0005[מותר].\u0006 אבל \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קטרת דכתיב\u0004 \u0005[שנאמר]\u0006\u0003: \"והקטרת אשר תעשה\u0004 במתכונתה לא תעשו\" — אסור לעשות במתכונתה \u0003כל עשייה\u0004 של \u0003קטרת,\u0004 והרי \u0003אפשר\u0004 שיהא \u0003מקטיר פרס\u0004 (חצי) \u0003שחרית ופרס בין הערבים,\u0004 כפי שאכן נעשה במקדש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמן המשחה\u0004 יש בו \u0003מר דרור\u0004 משקל \u0003חמש מאות\u0004 שקל, \u0003קדה חמש מאות, קנמן בשם חמש מאות, וקנה בשם חמשים ומאתים, נמצאו כולם\u0004 משקל \u0003אלף ושבעה מאות וחמשים\u0004 שקל.","ותוהים: הלא שמותיהם ומשקל כל אחד מהם נזכר בכתוב (שמות ל, כג—כד), וכי ה\u0003תנא מניינא קא משמע לן\u0004 \u0005[חשבון בא להשמיע לנו]\u0006 לכמה הם מצטרפים? ומשיבים: \u0003תנא הא קא קשיא ליה\u0004 \u0005[התנא\u0006 דבר \u0005זה היה קשה לו],\u0006 כלומר, משום כך הוצרך למנין זה, מפני שמלשון הכתוב \"וקנמן בשם מחציתו חמשים ומאתים, וקנה בושם חמשים ומאתים\" (שם כג) \u0003אימא\u0004 \u0005[אמור,\u0006 יכול אתה לומר\u0005]:\u0006 \u0003קנה בשם\u0004 יהיה שיעורו \u0003כקנמן בשם, מה קנמן בשם מחציתו בחמשים ומאתים,\u0004 ושיעורו המלא חמש מאות — \u0003אף קנה בשם\u0004 הכוונה היא \u0003מחציתו חמשים ומאתים, דהוו להו תרין\u0004 \u0005[ש\u0006כך \u0005הריהם שני]\u0006 \u0003אלפים\u0004 בסך כל סממני השמן, לכן הוצרך להשמיענו שמניינם אלף ושבע מאות וחמישים, לומר שקנמן בשם משקלו חמשים ומאתים.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך הוא גם כן],\u0006 שמשקלו חמש מאות! ומשיבים: \u0003אם כן, נכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"קנמן בשם וקנה בשם מחצה ומחצה חמשים ומאתים\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: כשהוא שוקל, בהכרע הוא שוקל,\u0004 מוסיף קצת, כדרך השוקלים, עד שהבשמים יכריעו את הכף, \u0003או עין בעין\u0004 בדיוק גמור \u0003הוא שוקל? אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003רחמנא כתב\u0004 \u0005[התורה אמרה]:\u0006 \u0003\"בד בבד\"\u0004 (שם לד) וכוונתו בדיוק, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003בהכרע?\u0004 ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה\u0004 בענין זה: \u0003הקדוש ברוך הוא יודע הכרעות,\u0004 כלומר, כמה נוסף בהכרע, \u0003אלמא דאית בהו\u0004 \u0005[מכאן שיש בהם]\u0006 \u0003הכרע!\u0004","\u0003אלא\u0004 בוודאי שוקל בהכרע, וכך \u0003אמר רב יהודה: דקנמן בשם אמאי מייתי\u0004 \u0005[מדוע מביאים]\u0006 \u0003מחציתו\u0004 של \u0003חמש מאות,\u0004 כלומר, \u0003חמשים ומאתים בחד זימנא\u0004 \u0005[בפעם אחת],\u0006 \u0003וחמשים ומאתים בחד זימנא\u0004 \u0005[בפעם אחת]?\u0006 והרי \u0003כיון דכולהון\u0004 \u0005[שכולם]\u0006 \u0003חמש מאות הויין\u0004 \u0005[הם],\u0006 \u0003נייתי\u0004 \u0005[שיביא]\u0006 \u0003חמש מאות בבת אחת! שמע מינה\u0004 \u0005[למד מכאן],\u0006 \u0003מדקמייתי לה\u0004 \u0005[מכיון שמביא אותו]\u0006 \u0003לקנמן בשם בתרי זימני\u0004 \u0005[בשתי פעמים],\u0006 מכאן ש\u0003הכרע אית ביה\u0004 \u0005[יש בו],\u0006 כדי להוסיף עליו הכרע בכל פעם, \u0003והקדוש ברוך הוא יודע בהכרעות.\u0004","ושואלים: \u0003ו\u0004לפי זה, \u0003מאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"בד בבד\"? אמר רבינא: שלא יניח משקל במשקל וישקול,\u0004 כלומר, שלא ישקול אחד מן הבשמים, ואחר כך ישקול אחר כנגדו, אלא צריך לשקול כל אחד מהם לעצמו כנגד המשקולת.","בדרך עשיית שמן המשחה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שמן המשחה שעשה משה במדבר משלקו\u0004 (מבשל בו) בשמן את \u0003העיקרין\u0004 שורשי הבשמים הללו, \u0003דברי ר' יהודה. אמר לו ר' יוסי: והלא\u0004 השמן שהיה שם, שהיתה מידתו שנים עשר לוג, אפילו כדי \u0003לסוך\u0004 את \u0003העיקרין אינו סיפק,\u0004 אין בו די, ובוודאי אינו מספיק כדי לשלוק בתוכו! אלא \u0003כיצד עושה? הביאו העיקרין ושלקום\u0004 (הרתיחום) \u0003במים,\u0004 והמים ספגו את הריח שבבשמים, \u0003והציף עליהן\u0004 על המים, את \u0003שמן המשחה, וקלט\u0004 השמן \u0003את הריח, ו\u0004אז \u0003קיפחו\u0004 הסיר את השמן, ונתנו בצלוחית.","\u0003אמר לו ר' יהודה:\u0004"],["\u0003וכי נס אחד נעשה בשמן המשחה? והלא נסים הרבה נעשו בו מתחלתו ועד סופו,\u0004 שהרי \u0003תחלתו לא היה אלא שנים עשר לוג, ובו נמשח המשכן וכליו ואהרן ובניו כל שבעת ימי המלואים, ובו נמשחו\u0004 במשך הדורות \u0003כהנים גדולים ומלכים, וכולו קיים לעתיד לבא,\u0004","\u0003שנאמר: \"שמן משחת קדש יהיה זה לי לדרתיכם\"\u0004 (שמות ל, לא), ומסבירים: \u0003\"זה\" בגימטריא שנים עשר לוגין הויין\u0004 \u0005[הן],\u0006 ש\"זה\" יהיה גם לדורות שלעתיד לבוא. ואם כן מעשה ניסים הוא, וכיון שכך אין להקשות על הנס.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הפסוק \u0003\"ויקח משה את שמן המשחה וימשח את המשכן\"\u0004 (ויקרא ח, י), \u0003רבי יהודה אומר: שמן המשחה שעשה משה במדבר הרבה נסים נעשו בו מתחלתו ועד סופו,\u0004 שהרי \u0003תחלתו לא היה אלא שנים עשר לוגין,\u0004 והלא בדרכו של עולם, כששולקים את הבשמים בשמן, \u0003כמה\u0004 שמן \u0003יורה\u0004 (הקדירה) \u0003בולעת, כמה עיקרין\u0004 (שורשים) כלומר, הבשמים עצמם \u0003בולעין, כמה האור שורף, ו\u0004למרות זאת, \u0003בו נמשח משכן וכליו, אהרן ובניו כל שבעת ימי המלואים,\u0004","\u0003ובו נמשחו כהנים גדולים ומלכים.\u0004 וכל הכהנים הגדולים היו בכלל זה, \u0003ואפילו כהן גדול בן כהן גדול טעון משיחה.\u0004 ומוסיפים: \u0003ואין מושחין מלך בן מלך. ואם תאמר: מפני מה משחו את שלמה\u0004 בן דוד? \u0003מפני מחלוקת אדוניה\u0004 אחיו, שהתנשא לאמר \"אני אמלוך\" (ראה שמואל א א, ה), \u0003ואת יהואש\u0004 משחו \u0003מפני עתליה\u0004 שתפסה את המלוכה (ראה מלכים ב כא, ג), \u0003ואת יהואחז\u0004 בן יאשיהו \u0003מפני יהויקים אחיו, שהיה\u0004 יהויקים \u0003גדול מאחיו שתי שנים.\u0004","ומבררים את פרטי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ואפילו כהן גדול בן כהן גדול טעון משיחה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי מנחת הכהן הגדול: \u0003\"והכהן המשיח תחתיו מבניו\u0004 יעשה אותה\" (ויקרא ו, טו), \u0003נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006\u0003: \"והכהן שתחתיו מבניו\", מאי\u0004 \u0005[מה]\u0006 טעם הוזכר \u0003\"המשיח\"? הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה הוא משמיע לנו],\u0006 שאפילו אם זה שיהיה תחתיו הוא \u0003מבניו, ההוא דמשח\u0004 \u0005[אותו שהוא משוח]\u0006 \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003כהן גדול, ואי לא משח לא הוי\u0004 \u0005[ואם אינו משוח אינו נעשה]\u0006 \u0003כהן גדול.\u0004","ועוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003אין מושחין מלך בן מלך.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר רב אחא בר יעקב, דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת המלך: \"\u0003למען יאריך ימים על ממלכתו הוא ובניו כל הימים\"\u0004 (ראה דברים יז, כ), לומר שירושה \u0003היא\u0004 המלוכה, שבניו מולכים מכוחו, ולכן אין צורך במשיחה חדשה.","ועוד נאמר בברייתא: \u0003ומפני מה משחו את שלמה? מפני מחלוקת אדוניה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 \u0003דכי אתי\u0004 \u0005[שכאשר באה]\u0006 \u0003מחלוקת בעי\u0004 \u0005[צריך]\u0006 \u0003משיחה, ולא כל דבעי מלכא מורית ליה מלכותא\u0004 \u0005[ולא כל\u0006 מי \u0005שרוצה המלך מוריש לו את המלכות],\u0006 ודי בכך? \u0003אמר רב פפא, אמר קרא\u0004 \u0005[המקרא]\u0006 שם: \"למען יאריך ימים וכו' הוא ובניו \u0003בקרב ישראל\"\u0004 — \u0003בזמן ששלום בישראל\u0004 עוברת המלכות מאליה לבניו, ואם לא כן — צריך למשוח מלך מחדש.","ומעירים, \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003אף יהוא בן נמשי לא נמשח\u0004 (ראה מלכים כט, א—ו) \u0003אלא מפני מחלוקת יורם בן אחאב,\u0004 שהיה מלך ישראל באותה שעה, ויהוא מרד בו. ותמהים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הוצרך לטעם זה? \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 שהוצרך למשיחה מפני שמלך \u0003ראשון הוא,\u0004 שהרי לא היה בנו של אחאב! ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך היא שנויה]:\u0006 \u0003מלכי בית דוד מושחין, מלכי ישראל אין מושחין; ואם תאמר: מפני מה משחו יהוא בן נמשי? מפני מחלוקת יורם בן אחאב.\u0004","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מלכי בית דוד מושחין, ואין מלכי ישראל מושחין.\u0004 ומסבירים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לשמואל כשהובא דוד לפניו: \u0003\"קום משחהו כי זה הוא\"\u0004 (שמואל א טז, יב), ויש כאן הדגשה: \u0003זה טעון משיחה, ואין אחר טעון משיחה.\u0004","ועל מה ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 אף יהוא בן נמשי לא נמשח אלא \u0003מפני מחלוקת יורם,\u0004 תוהים: \u0003ומשום מחלוקת יורם בן אחאב נמעל בשמן המשחה,\u0004 שהוא \"שמן משחת קודש\" (שמות ל, לא)? והרי אמרנו שאין מושחים בו מלכי ישראל! ומשיבים, \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב פפא\u0004 להלן ביחס ליהואחז: \u0003באפרסמא דכיא\u0004 \u0005[ב\u0006שמן \u0005אפרסמון טהור]\u0006 משחוהו, ולא בשמן המשחה, \u0003הכא נמי באפרסמא דכיא\u0004 \u0005[כאן גם כן\u0006 \u0005ב\u0006שמן \u0005אפרסמון טהור]\u0006 משחו את יהוא.","שנינו בברייתא: \u0003ואת יהואחז\u0004 בן יאשיהו משחו \u0003מפני יהויקים\u0004 אחיו, \u0003שהיה גדול ממנו שתי שנים.\u0004 ותמהים: \u0003ומי קשיש\u0004 \u0005[והאם\u0006 היה \u0005מבוגר\u0006 ממנו\u0005]\u0006\u0003? והכתיב\u0004 \u0005[והרי נאמר]: \"\u0006\u0003ובני יאשיה הבכור יוחנן והשני יהויקים והשלישי צדקיהו והרביעי שלום\"\u0004 (דברי הימים א ג, טו), \u0003ואמר ר' יוחנן:\u0004 יוחנן \u0003הוא יהואחז, הוא צדקיהו הוא שלום,\u0004 ונמצא שהבן הבכור היה יהואחז, ולא יהויקים!","\u0003אלא\u0004 יש להבין כי \u0003לעולם,\u0004 באמת \u0003יהויקים\u0004 היה \u0003קשיש\u0004 \u0005[מבוגר\u0006 יותר\u0005], ואמאי קרי ליה\u0006 \u0005[ומדוע קרא לו\u0006 הכתוב\u0005]\u0006 ליהואחז \u0003בכור?\u0004 מפני \u0003שהוא\u0004 היה בכור (ראשון) \u0003למלכות.\u0004 ושואלים: \u0003ומי מוקמינן זוטא קמי קשישא\u0004 \u0005[והאם מעמידים אנו\u0006 למלוכה \u0005צעיר לפני המבוגר]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 על יהושפט: \u0003\"ואת הממלכה נתן ליהורם כי הוא הבכור\"\u0004 (דברי הימים ב כא, ג)! ומשיבים: \u0003ההוא\u0004 כלומר, יהורם בן יהושפט, \u0003ממלא מקום אבותיו הוה\u0004 \u0005[היה],\u0006 שהיה כאביו וראוי למלוך במקומו, אבל יהויקים לא היה ממלא מקום אביו, אלא יהואחז.","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם],\u0006 ר' יוחנן: \u0003הוא שלום הוא צדקיה.\u0004 ושואלים: \u0003והא בדרי קחשיב\u0004 \u0005[והרי בשורות,\u0006 בזה אחר זה, \u0005הוא מונה אותם],\u0006 השלישי צדקיהו והרביעי שלום! ומשיבים: מכל מקום איש אחד הוא, \u0003ומאי קרי ליה\u0004 \u0005[ומדוע קרא לו]\u0006 \u0003שלישי? שהוא שלישי לבנים, ומאי קרי ליה\u0004 \u0005[ומדוע קרא לו]\u0006 \u0003רביעי? שהוא רביעי למלכות, משום\u0004 שמלך \u0003יכניה קמיה\u0004 \u0005[לפניו].\u0006 שכך היה הסדר: \u0003בתחלה מלך יהואחז\u0004 (מלכים ב כג, ל), \u0003וסוף\u0004 (לאחר מכן) \u0003מלך יהויקים\u0004 (שם לד), \u0003וסוף מלך יכניה\u0004 בנו של יהויקים (שם כד, ו), \u0003וסוף מלך צדקיה\u0004 (שם יז).","אגב כך מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הוא שלום הוא צדקיה, ולמה נקרא שמו שלום? שהיה שלם במעשיו. דבר אחר:\u0004 נקרא \u0003שלום\u0004 — \u0003ששלם,\u0004 תמה ונגמרה, \u0003מלכות בית דוד בימיו, ומה שמו\u0004 המקורי? \u0003מתניה שמו, שנאמר: \"וימלך\u0004 מלך בבל \u0003את מתניה דדו תחתיו ויסב שמו צדקיה\"\u0004 (שם), ומדוע קרא לו מלך בבל \"צדקיה\"?","שאמר \u0003לו: יה יצדיק עליך את הדין\u0004 שיבוא עליך \u0003אם תמרוד בי,\u0004 שהשביעו בשם ה' שלא ימרוד בו. \u0003שנאמר:\u0004 \"ולתשובת השנה שלח המלך נבוכדנאצר \u0003ויביאהו\u0004 (את יהויכין) \u0003בבלה\u0004 וימלך את צדקיהו\" (דברי הימים ב לו, י), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006\u0003: \"וגם במלך נבוכד נאצר מלך בבל מרד אשר השביעו באלהים\"\u0004 (שם יג).","וביחס למה ששנינו, שמשחו את יהואחז בן יאשיהו, שואלים: \u0003ומי הוה\u0004 \u0005[והאם היה]\u0006 \u0003שמן המשחה\u0004 באותה שעה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 בריייתא\u0005]: משנגנז ארון\u0006 העדות, \u0003נגנז\u0004 עימו \u0003צנצנת המן\u0004 שהניח משה למשמרת לפני ה' (שמות טז, לג), \u0003וצלוחית שמן המשחה, ומקלו של אהרן\u0004 עם \u0003שקדים ופרחים\u0004 שבו, שהונח לפני הארון (במדבר יז, כג),","\u0003וארגז ששגרו פלשתים דורון לאלהי ישראל, שנאמר: \"ואת כלי הזהב אשר השבתם לו אשם תשימו בארגז מצדו\"\u0004 (שמואל א ו, ח). \u0003ומי גנזו\u0004 את הארון? \u0003יאשיה מלך יהודה גנזו, שנאמר: \"ויאמר המלך אל הכהנים תנו את ארון הקדש\u0004 בבית אשר בנה שלמה\" (דברי הימים ב לה, ג);","\u0003ואמר רבי אלעזר:\u0004 מנין שכל אלה צריכים להיות מונחים יחד עם הארון? ביחס לצנצנת \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 בגזירה שווה \u0003\"שם\" \"שם\",\u0004 שנאמר בארון: \"אשר אועד לך שמה\" (שמות ל, ו), ונאמר בצנצנת המן: \"ונתן שמה\" (שם טז, לג).","שמן המשחה \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 בגזירה שווה \u0003\"דורות\" \"דורות\"\u0004 מצנצנת המן שנאמר בה \"לדורותיכם\" (שם), ובשמן המשחה נאמר גם כן \"לדורותיכם\" (שמות ל, לא).","ומקלו של אהרן \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 בגזירה שווה \u0003\"משמרת\" \"משמרת\"\u0004 מצנצנת המן, שנאמר בה \"משמרת\" (שם טז, לג). וגם ממקלו של אהרן (במדבר יז, כה). ואם כן כיצד משחו את יהואחז? \u0003אמר רב פפא:\u0004 לא בשמן המשחה נמשח, אלא \u0003באפרסמא דכיא\u0004 \u0005[ב\u0006שמן \u0005אפרסמון טהור].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מושחין את המלכים כמין נזר\u0004 (כתר) סביב על ראשו, \u0003ואת הכהנים כמין \"כי\".\u0004 ובביאור הענין \u0003אמר רב מנשיה: כמין\u0004 האות \u0003\"כי\" יוני.\u0004 ומעירים: מצאנו סתירה בענין המשיחה, \u0003תני חדא\u0004 \u0005[שנויה ברייתא\u0006 \u0005אחת]:\u0006 \u0003בתחלה מציק\u0004 (יוצק) \u0003שמן על ראשו ואחר כך נותן לו שמן בין ריסי עיניו, ותני אחריתי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בתחלה נותן לו שמן בין ריסי עיניו ואחר כך מציק לו שמן על ראשו!\u0004","ומסבירים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, איכא למאן דאמר\u0004 \u0005[יש מי שאומר]\u0006 שמשיחה \u0003עדיפא,\u0004 ולכן מקדים אותה, \u0003ואיכא למאן דאמר\u0004 \u0005[ויש מי שאומר]\u0006 שיציקה \u0003עדיפא.\u0004 ומבארים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה טעמו של מי שאומר]\u0006 שיציקה \u0003עדיפא\u0004 — \u0003שנאמר: \"ויצק משמן המשחה על ראש אהרן\"\u0004 (ויקרא ח, יב), ורק אחר כך — \"וימשח אותו לקדשו\" (שם), \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שמשיחה \u0003עדיפא\u0004 — \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003שכן נתרבה\u0004 משיחה \u0003אצל כלי שרת,\u0004 ולא נאמרה בהם יציקה.","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במפורש: \u0003\"ויצק\" ולבסוף \"וימשח\"!\u0004 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך יש להבין את הכתוב: \u0003מה טעם \"ויצק\"\u0004 — \u0003משום\u0004 שכבר \u0003\"וימשח אותו לקדשו\".\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מהו שנאמר \u0003\"כשמן הטוב היורד על הראש\u0004 יורד על הזקן זקן אהרן\" (תהלים קלג, ב)? \u0003כמין שתי טיפין מרגליות\u0004 של שמן המשחה \u0003היו תלויות לאהרן בזקנו. אמר רב כהנא, תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006\u0003: כשהוא מספר\u0004 (מדבר) היו הטיפות \u0003עולות\u0004 דרך נס \u0003ויושבות בעיקרי\u0004 (שורשי) שערות \u0003זקנו,\u0004 כדי שלא יפלו תוך כדי שהיה מדבר. \u0003ועל דבר זה היה משה רבינו דואג: שמא חס ושלום מעלתי בשמן המשחה,\u0004 שיצקתי יותר מדי, שהגיע עד לזקנו!","\u0003יצתה בת קול ואמרה: \"כטל חרמון שירד על הררי ציון\"\u0004 (שם ג), \u0003מה טל אין בו מעילה\u0004 שאין קדוש, אלא הפקר לכל — \u0003אף שמן שיורד על זקן אהרן אין בו מעילה.\u0004","\u0003ועדיין אהרן היה דואג, שמא משה לא מעל,\u0004 שעשה מצוה, \u0003ואני מעלתי,\u0004 שאני נהנה מן השמן הריחני שבזקני! \u0003יצתה בת קול ואמרה לו: \"הנה מה טוב ומה נעים שבת אחים גם יחד\"\u0004 (שם א), \u0003מה משה לא מעל, אף אתה לא מעלת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מושחין את המלכים אלא על המעיין,\u0004 לסימן טוב, \u0003כדי שתימשך מלכותן\u0004 כמעיין הנובע ללא הפסק, \u0003שנאמר,\u0004 כאשר ציוה דוד למשוח את שלמה למלך: \u0003\"ויאמר המלך אל בניהו וגו' והורדתם אתו על גחון וגו' ומשח אותו שם\u0004 צדוק הנביא\" (ראה מלכים א א, לג—לד).","אגב ענין זה של עשיית דבר לסימן טוב, \u0003אמר רב אמי: האי מאן דבעי לידע אי משכא שתא אי לא\u0004 \u0005[מי שרוצה לדעת אם תימשך שנתו או לא],\u0006 אם יחיה באותה שנה, \u0003מייתי שרגא בהלין עשרה יומין דבין ריש שתא ליומא דכיפורי\u0004 \u0005[יביא נר באותם עשרה ימים שבין ראש השנה ליום הכיפורים],\u0006 \u0003וניתלי בביתא דלא נשיב זיקא\u0004 \u0005[ויתלה אותו בבית שלא נושבת בו רוח],\u0006 \u0003אי משיך נהוריה נידע דמסיק שתיה\u0004 \u0005[אם נמשך אורו ידע ש\u0006הוא \u0005מוציא,\u0006 משלים \u0005את שנתו].\u0006","\u0003ומאן דבעי נעביד עיסקי\u0004 \u0005[ומי שרוצה לעשות עסקים],\u0006 \u0003ובעי דנידע אי מצלח עיסקי אי לא\u0004 \u0005[ורוצה לדעת אם יצליח העסק אם לא],\u0006 \u0003נירבי תרנגולא\u0004 \u0005[שיגדל תרנגול],\u0006 \u0003אי שמין ושפר נידע דמצלח\u0004 \u0005[אם\u0006 הוא \u0005נעשה שמן ויפה ידע ש\u0006הוא \u0005מצליח].\u0006","\u0003האי מאן דבעי ניפוק באורחא\u0004 \u0005[מי שרוצה לצאת לדרך],\u0006 \u0003ובעי דנידע אי הדר לביתיה\u0004 \u0005[ורוצה לדעת אם יחזור לביתו],\u0006 \u0003ניעול ניקום בביתא דבהתא\u0004 \u0005[שייכנס לתוך בית אפל],\u0006 \u0003אם חזי\u0004 \u0005[רואה]\u0006"],["\u0003בבואה\u0004 (צל) \u0003לבבואה\u0004 של \u0003בבואה\u0004 שלו, \u0003נידע דאתי לביתיה\u0004 \u0005[ידע שיבוא לביתו].\u0006 ומעירים: \u0003ולאו מילתא היא\u0004 \u0005[ולא דבר הוא],\u0006 ואין לעשות כן, \u0003דילמא חלשא דעתיה\u0004 \u0005[שמא תחלש דעתו]\u0006 אם לא יראה את הסימן, \u0003ומתרע מזליה\u0004 \u0005[ויורע מזלו].\u0006","\u0003אמר אביי: השתא דאמרת סימנא מילתא היא\u0004 \u0005[עכשיו שאתה אומר שסימן\u0006 שעושים \u0005דבר של ממש הוא],\u0006 \u0003יהא רגיל איניש\u0004 \u0005[אדם]\u0006 \u0003למיכל ריש שתא\u0004 \u0005[לאכול בראש השנה]\u0006 \u0003קרא ורוביא, כרתי, סילקא ותמרי\u0004 \u0005[דלעת ורוביא, כרישים, תרדים ותמרים],\u0006 שכולם יש בהם סימן טוב.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב משרשיא לבניה\u0004 \u0005[לבניו]:\u0006 \u0003כי בעיתו למיזל למגמר קמיה רבכון\u0004 \u0005[כאשר אתם רוצים ללכת ללמוד לפני רבכם],\u0006 \u0003גרוסו מעיקרא מתניתין והדר עולו קמי רבכון\u0004 \u0005[תלמדו ותחזרו תחילה על המשניות ואחר כך היכנסו לפני רבכם],\u0006 \u0003וכי יתביתו קמי רבכון, חזו לפומיה דרבכון\u0004 \u0005[וכאשר אתם יושבים לפני רבכם, ראו את פיו של רבכם]\u0006 כשמלמד אתכם, \u0003שנאמר: \"והיו עיניך רואות את מוריך\"\u0004 (ישעיהו ל, כ), \u0003וכי גריסיתו שמעתא, גרוסו על מיא\u0004 \u0005[וכאשר אתם גורסים,\u0006 חוזרים \u0005על שמועה, הלכה, גירסו אותה על המים],\u0006 \u0003דכי היכי דמשכי מיא תמשוך שמעתכון\u0004 \u0005[שכמו שנמשכים המים תימשך שמועתכם].\u0006","ועוד אמר להם: מוטב לחיות \u0003אקילקי\u0004 \u0005[באשפות]\u0006 של \u0003מתא מחסיא, ולא אפדני\u0004 \u0005[בארמונות]\u0006 של \u0003פומבדיתא. טב גילדנא סריא למיכל מכותחא דרמי כיפי\u0004 \u0005[טוב\u0006 לאכול \u0005דג קטן מסריח מלאכול כותח\u0006 משובח וחזק \u0005שמשבר סלעים],\u0006 שהוא מזיק.","ושבים לעיקר הדיון, בענין משיחת המלכים נאמר: \"\u0003ותתפלל חנה ותאמר עלץ לבי בה' רמה קרני\"\u0004 (שמואל א ב, א), ומדייקים: \u0003\"רמה קרני\" ולא \"רמה פכי\",\u0004 וסימן הוא: \u0003דוד ושלמה שנמשחו בקרן\u0004 (ראה שם טז, יג. מלכים א א, לט) — \u0003נמשכה מלכותם, שאול ויהוא שנמשחו מן הפך\u0004 (ראה שמואל א י, א. מלכים ב ט, ג—ו) — \u0003לא נמשכה מלכותם.\u0004","שנינו במשנה בין חייבי הכריתות: \u0003המפטם\u0004 (הרוקח) \u0003את הקטרת.\u0004 ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המפטם את הקטרת ללמד בה\u0004 כיצד לעשותה, \u0003או למוסרה לציבור\u0004 — \u0003פטור,\u0004 אם עשאה \u0003להריח בה\u0004 — \u0003חייב. והמריח בה,\u0004 בקטורת של המקדש — \u0003פטור, אלא שמעל,\u0004 נהנה מן ההקדש, ואם היה זה בשוגג צריך להביא קרבן אשם.","ותוהים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 דין \u0003מעילה\u0004 בריח? \u0003והאמר\u0004 \u0005[והרי אמר] ר'\u0006 \u0003שמעון בן פזי אמר ר' יהושע בן לוי משום בר קפרא: קול ומראה וריח\u0004 של נכסי הקדש — \u0003אין בהן משום מעילה,\u0004 אם נהנה מהם!","ומשיבים: \u0003ריח\u0004 רק \u0003אחר שתעלה תמרתו\u0004 (עמוד העשן) של הקטורת, \u0003אין בו משום מעילה,\u0004 שהרי \u0003אין לך דבר אחר שנעשה מצותו ומועלין בו.\u0004","ושואלים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא? והרי תרומת הדשן,\u0004 שמרימים מדשן המזבח ומניחים אצל המזבח, הרי שנעשית \u0003מצותה\u0004 לאחר שכבר נשרפו הקרבנות, ובכל זאת \u0003מועלין בה!\u0004","ומשיבים: אין ללמוד משם, \u0003משום דהוי\u0004 \u0005[שהריהם]\u0006 \u0003תרומת הדשן ובגדי כהונה, שני כתובים הבאים כאחד,\u0004 שנאמר בהם דבר שניתן היה לאומרו באחד מהם, וללמוד ממנו, \u0003וכל שני כתובין הבאין כאחד אין מלמדים\u0004 לשאר דיני התורה.","ואומרים: \u0003הניחא לרבנן\u0004 \u0005[זה נוח ל\u0006שיטת \u0005חכמים],\u0006 \u0003אלא ל\u0004שיטת \u0003ר' דוסא מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר על בגדי הכהן הגדול שלובש ביום הכיפורים: \"\u0003והניחם שם\"\u0004 (ויקרא טז, כג), \u0003מלמד שטעונין גניזה.\u0004","\u0003רבי דוסא אומר: כשירין הן לכהן הדיוט\u0004 (שהרי גם הם בגדי לבן), \u0003ומה תלמוד לומר \"והניחם שם\"?\u0004 כוונתו — \u0003שלא ישתמש בהן\u0004 הכהן הגדול \u0003ביום הכפורים אחר.\u0004 ואם כן, מדוע לא נלמד מתרומת הדשן לשאר דברים?","ומשיבים: \u0003משום דהוי\u0004 \u0005[שהריהם]\u0006 \u0003תרומת הדשן ועגלה ערופה שני כתובין הבאין כאחד\u0004 לענין זה, \u0003וכל שני כתובין הבאין כאחד אין מלמדין.\u0004 ומבארים: \u0003תרומת הדשן מאי\u0004 \u0005[מה]\u0006 \u0003היא? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006\u0003: \"ושמו אצל המזבח\"\u0004 (שם ו, ג), \u0003מלמד שטעונין גניזה. עגלה ערופה מאי\u0004 \u0005[מה]\u0006 \u0003היא? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]: \"\u0006\u0003וערפו שם את העגלה בנחל\"\u0004 (דברים כא, ד), \u0003מלמד שטעונין גניזה.\u0004","ומוסיפים: \u0003ולמאן דאמר\u0004 \u0005[ו\u0006אפילו \u0005ל\u0006דעת \u0005מי שאומר]\u0006 בדרך כלל: \u0003שני כתובין הבאים כאחד מלמדין,\u0004 מכל מקום \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי אין מלמדין, משום דהוי תרי מיעוטי\u0004 \u0005[שיש שני מיעוטים]\u0006 בכתוב, \u0003בתרומת הדשן כתיב\u0004 \u0005[נאמר]\u0006\u0003 \"ושמו\"\u0004 (ויקרא ו, יג), וההדגשה היא: \u0003הדין אין\u0004 \u0005[זה כן],\u0006 צריך לגנוז אותו, \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 \u0003לא,\u0004 וכן \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003עגלה ערופה כתיב\u0004 \u0005[נאמר]:\u0006 \"העגלה הערופה\" (דברים כא, ו), ללמד: העגלה ה\u0003ערופה אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 \u0003לא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פיטום\u0004 (רקיחת) \u0003הקטרת\u0004 כיצד? \u0003הצרי, והציפורן, והחלבנה, והלבונה\u0004 — כל אחד מהם \u0003משקל שבעים של שבעים מנה\u0004 (מאה דינר). \u0003מור, וקציעה, שיבולת נרד, וכרכום\u0004 — \u0003משקל ששה עשר של ששה עשר מנה. הקושט\u0004 — \u0003שנים עשר\u0004 מנה, \u0003קילופה\u0004 — \u0003שלשה, וקנמון תשעה. בורית כרשינה\u0004 — \u0003תשעה קבין, יין קפריסין\u0004 — \u0003סאין תלתא קבין תלתא\u0004 \u0005[שלושה סאים ו\u0006עוד \u0005שלושה קבים,\u0006 חצי סאה\u0005]\u0006\u0003. אם אין לו יין קפריסין מביא חמר חיוריין עתיק\u0004 \u0005[יין לבן ישן].\u0006 \u0003מלח סדומית\u0004 מביאים \u0003רובע\u0004 הקב. \u0003מעלה עשן,\u0004 שהוא עשב שגורם שייתמר עשן הקטורת יפה — \u0003כל שהוא. ר' נתן אומר: אף כיפת הירדן כל שהוא.\u0004","\u0003ואם נתן בה דבש\u0004 בקטורת — \u0003פסלה,\u0004 שנאמר: \"כי כל שאור וכל דבש לא תקטירו ממנו אשה לה'\" (ויקרא ב, יא). ואם \u0003חיסר אחת מכל סממניה,\u0004 והקטירה — \u0003חייב מיתה. ר' שמעון אומר: הצרי\u0004 שהוזכר לעיל \u0003אינו אלא שרף\u0004 הנוטף \u0003מעצי הקטף,\u0004 ולא עץ הקטף עצמו! ועוד, \u0003בורית כרשינה\u0004 שהוזכרה, אינה חלק מהסממנים, אלא \u0003ששפין\u0004 (משפשפים) \u0003בה את הציפורן כדי שתהא נאה.\u0004 וכן \u0003יין קפריסין\u0004 שהוזכר הוא זה \u0003ששורין בו את הציפורן כדי שתהא עזה. והלא מי רגלים יפין לה\u0004 לצורך זה, \u0003אלא שאין מכניסין מי רגלים למקדש\u0004 מפני הכבוד.","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר לר' \u0003יוסי בר' חנינא,\u0004 שאמר ביחס לקטורת: \u0003\"קדש היא קדש תהיה לכם\"\u0004 (ראה שמות ל, לו—לז), לומר: \u0003כל מעשיה לא יהו אלא בקדש.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו במסכת שקלים: \u0003המקדיש נכסיו והיו בה דברים הראויין לקרבנות הציבור\u0004 — \u0003ינתנו לאומנין\u0004 העובדים עבור המקדש \u0003בשכרן.\u0004","ויש לשאול: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003דברים הראויין\u0004 לקרבנות הציבור, שאדם מקדיש משלו, \u0003מאי נינהו\u0004 \u0005[מה הם]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בהמה וחיה\u0004 — הרי \u0003תנא ליה\u0004 \u0005[שנה אותו,\u0006 את דינם\u0005]\u0006 במשנה אחרת! \u0003אי\u0004 \u0005[אם]\u0006 \u0003יינות שמנים וסלתות\u0004 — גם כן \u0003תנא ליה\u0004 \u0005[שנה אותו]!\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר על \u0003קטרת\u0004 שאדם מקדיש משלו? ואם כן, קטורת נעשית גם מחוץ למקדש!","\u0003אמר ר' אושעיא:\u0004 מדובר \u0003באותה\u0004 קטורת \u0003הניתנת לאומנים בשכרן,\u0004 שנעשתה כדינה בקודש, ואומנים אלו חזרו והקדישוה מנכסיהם. \u0003דתניא\u0004 \u0005[ששנויה\u0006 משנה\u0005]:\u0006 הואיל ובכל שנה צריך להביא קטורת מהתרומה החדשה של מחצית השקל, \u0003מותר הקטרת,\u0004 מה שנותר בסוף השנה, \u0003מה היו עושין בה? היו מפרישין ממנה\u0004 בשיעור \u0003שכר האומנין, ומחללין אותה על מעות האומנין, ו\u0004לאחר שנתחללה קדושתה על המעות \u0003נותנין אותן\u0004 (את הקטורת) \u0003לאומנין בשכרן, וחוזרים ולוקחין\u0004 (וקונים) \u0003אותה\u0004 מן האומנים \u0003מתרומה חדשה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף:\u0004 כיצד ייתכן להעמיד משנה זו באומן שהקדיש את מותר הקטורת שקיבל בשכרו? \u0003הא בכולהו מותרות תני\u0004 \u0005[הרי בכל המותרות\u0006 \u0005הוא שונה]\u0006 שלאחר שנותנים אותם לאומנים בשכרם \u0003חוזרין ולוקחין אותה מתרומה חדשה,\u0004 ובכלל זה מותר הקטורת, כפי ששנינו זה עתה, \u0003והכא\u0004 \u0005[וכאן]\u0006 במקדיש נכסיו \u0003לא תני\u0004 \u0005[אינו שונה]\u0006 כן, ומכאן שאין מדובר בקטורת!","\u0003אלא אמר רב יוסף:\u0004 מדובר פה \u0003באחד מסממני הקטרת,\u0004 שאדם הקדיש בתוך נכסיו, ולא בקטורת שכבר נרקחה, שהיא אינה נעשית אלא בקודש, וכדברי ר' יוסי בר' חנינא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קטרת היתה נעשית\u0004 מ\u0003שלש מאות ששים ושמונה מנה,\u0004 כפי ששנינו לעיל; \u0003שלש מאות ששים וחמשה כנגד ימות\u0004 שנת \u0003החמה,\u0004 ועוד \u0003שלשה מנין יתירין\u0004 על אלה, \u0003שמהן מכניס כהן גדול מלא חפניו ביום הכיפורים,\u0004 לצורך הקטרה בקודש הקודשים, \u0003והשאר ניתנת לאומנין בשכרן.\u0004","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 משנה\u0005]\u0006\u0003: מותר הקטרת מה היו עושין בה? מפרישין ממנה שכר האומנין, ומחללין אותה על מעות האומנין, ונותנין אותן\u0004 את הקטורת \u0003לאומנין בשכרן, וחוזרין ולוקחין\u0004 (קונים) \u0003אותה\u0004 את הקטורת הזו מן האומנים \u0003מתרומת הלשכה\u0004 של השנה הבאה."],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מותר הקטרת\u0004 מאותם שלושה מנים שבכל שנה, הצטבר במשך השנים, כך ש\u0003אחת לששים או לשבעים שנה, היו מפטמין אותה\u0004 את הקטורת לשנה החדשה \u0003לחצאין,\u0004 כלומר, לא היו צריכים אלא מחצית הכמות. \u0003לפיכך יחיד שפיטם\u0004 קטורת \u0003לחצאין\u0004 כדי להריח בה — \u0003חייב\u0004 משום \"והקטורת אשר תעשה, במתכונתה לא תעשו לכם\" (שמות ל, לז), \u0003דברי רבן שמעון בן גמליאל שאמר משום הסגן,\u0004 סגן הכהנים.","והוסיף: \u0003אבל\u0004 על פיטום \u0003שליש\u0004 הכמות או \u0003רביע\u0004 הכמות \u0003לא שמעתי. וחכמים אומרים: בכל יום מתקן\u0004 קטורת לאותו יום \u0003במתכונתה,\u0004 לפי היחס הראוי בין הסממנים השונים, \u0003והיה מכניס\u0004 ומקטיר על מזבח הזהב.","ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרבא,\u0004 שאמר \u0003רבא: שמן המשחה שפטמו\u0004 לחצאין, על מנת לסוך בו — פטור, אבל הקטורת שפיטמה כדי להריח בה, אפילו \u0003לחצאין\u0004 — \u0003חייב, דכתיב\u0004 \u0005[שנאמר]\u0006\u0003: \"והקטרת אשר תעשה\u0004 במתכונתה לא תעשו לכם\" (שם) — \u0003כל שתעשה, והא\u0004 \u0005[והרי]\u0006 \u0003אפשר דעבדה\u0004 \u0005[שעושה אותה]\u0006 \u0003פרס בשחרית ופרס בין הערבים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היו מחזירין אותה\u0004 את הקטורת \u0003למכתשת פעמים בשנה, בימות החמה\u0004 מכניסים אותה \u0003פזורה\u0004 — כדי \u0003שלא תתעפש, בימות הגשמים צבורה\u0004 — \u0003כדי שלא תפוג ריחה. וכשהוא שוחק\u0004 את הקטורת, היה השוחק \u0003אומר: \"הדק היטב, היטב הדק\", דברי אבא יוסי בן יוחנן.\u0004","\u0003ו\u0004הקטורת בשיעור \u0003שלש מנין יתירין\u0004 על מנין ימות החמה \u0003שמהן כהן גדול מכניס מלא חפניו ביום הכפורים, נותן אותה למכתשת בערב יום הכפורים, ושוחקן יפה יפה\u0004 שוב, \u0003כדי שתהא דקה מן הדקה, כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר ביום הכפורים \"קטורת סמים \u0003דקה\"\u0004 (ויקרא טז, יב), \u0003מה תלמוד לומר? והלא כבר נאמר \"ושחקת ממנו הדק\"\u0004 (שמות ל, לו), \u0003מה תלמוד לומר \"דקה\"\u0004 — \u0003כדי שתהא דקה מן הדקה.\u0004","ביחס למה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003כשהוא שוחק, אומר \"היטב הדק, הדק היטב\",\u0004 מעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר לר' \u0003יוחנן,\u0004 שאמר ר' \u0003יוחנן: כשם שהדיבור רע ליין,\u0004 שכשמדברים בזמן עשיית היין — מזיק הדבר ליין, \u0003כן הדיבור יפה לבשמים.\u0004","\u0003אמר ר' יוחנן: אחד עשר סממנין\u0004 שנשנו בברייתא \u0003נאמרו לו למשה בסיני,\u0004 שלא כולם כתובים בתורה. \u0003אמר רב הונא: מאי קראה\u0004 \u0005[מהו המקרא]\u0006 המלמד על אחד עשר הסממנים? שנאמר \"קח לך סמים נטף ושחלת וחלבנה סמים ולבונה זכה\" (שמות ל, לד). \u0003\"קח לך סמים\"\u0004 — הרי \u0003תרי\u0004 \u0005[שנים],\u0006 ועוד \u0003\"נטף ושחלת וחלבנה\"\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003חמשה, ו\"סמים\" אחריני\u0004 \u0005[אחרונים]\u0006 שכתובים שם — עוד \u0003חמשה, הא\u0004 \u0005[הרי]\u0006 \u0003עשרה, \"ולבונה זכה\"\u0004 — \u0003חד\u0004 \u0005[אחד],\u0006 \u0003הא חד סרי\u0004 \u0005[הרי אחד עשר].\u0006","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודרוש את הכתוב כך: \u0003\"סמים\"\u0004 — \u0003כלל, \"נטף ושחלת וחלבנה\"\u0004 — \u0003פרט, \"סמים\"\u0004 — \u0003חזר וכלל,\u0004 ולפי המידות שהתורה נדרשת בהן, \u0003כלל ופרט וכלל\u0004 — \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט,\u0004 ונאמר כך: \u0003מה הפרט\u0004 ה\u0003מפורש,\u0004 נטף ושחלת וחלבנה, \u0003דבר שקיטר ועולה,\u0004 שעשנו מיתמר למעלה, \u0003וריחו נודף\u0004 — \u0003אף כל דבר שקיטר ועולה וריחו נודף!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003אם כן\u0004 אם רק לצורך כלל ופרט, \u0003לכתוב קרא חד פרטא\u0004 \u0005[שיכתוב המקרא\u0006 רק \u0005פרט אחד]!\u0006 \u0003לאיי, מיצרך צריכי\u0004 \u0005[לא כן, צריכים הם\u0006 כולם\u0005]\u0006\u0003, דאי כתב\u0004 \u0005[שאם\u0006 היה \u0005כותב]\u0006 רק \u0003\"נטף\",\u0004 שהוא מין אילן, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מין אילן\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל גידולי קרקע\u0004 (עשבים הצומחים מן הקרקע) — \u0003לא, משום הכי\u0004 \u0005[כך]\u0006 \u0003כתב: \"ושחלת\"\u0004 (צפורן). \u0003ואי כתב\u0004 \u0005[ואם היה כותב]\u0006 רק: \"\u0003ושחלת\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003גידולי קרקע\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אבל מין אילן אימא\u0004 \u0005[אמור]\u0006 שלא, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003כתב: \"נטף\".\u0004","\u0003וחלבנה לגופיה אתא\u0004 \u0005[לגופו בא],\u0006 לומר שצריך להקטירה, \u0003מפני שריחה רע,\u0004 ולא היינו עושים כן מדעתנו! ודוחים: \u0003אם כן,\u0004 שדורשים פסוק זה ב\"כלל ופרט וכלל\", אין צורך ב\"סמים\" הראשון לשם כלל, \u0003מ\"קח לך\"\u0004 בלבד \u0003נפקא ליה\u0004 \u0005[יוצא לו\u0006 הכלל\u0005].\u0006","וחוזרים ושואלים: וכיצד מדייק אתה מן הפסוק אחד עשר סממנים? \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003\"סמים\" בתראי תרין נינהו כ\"סמים\" קדמאי\u0004 \u0005[\"סמים\" האחרונים שנים הם כ\"סמים\" הראשונים]!\u0006 ומשיבים: \u0003אם כן, נכתוב\u0004 \u0005[שיכתוב]\u0006 \u0003\"סמים\" \"סמים\" בהדי הדדי\u0004 \u0005[ביחד]\u0006\u0003, ו\u0004ב\u0003סוף נכתוב\u0004 \u0005[שיכתוב] \"\u0006\u0003נטף ושחלת וחלבנה\".\u0004 אלא בא הדבר ללמד ש\"סמים\" האחרונים הם כנגד כל הראשונים.","ומעירים: החכם \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו של\u0005]\u0006 \u0003רבי ישמעאל תני\u0004 \u0005[שנה]:\u0006 \u0003\"סמים\"\u0004 — \u0003כלל, \"נטף שחלת וחלבנה\"\u0004 — \u0003פרט, \"סמים\"\u0004 — \u0003חזר וכלל, כלל ופרט וכלל\u0004 — \u0003אי אתה דן אלא כעין הפרט, מה הפרט מפורש דבר שקיטר ועולה וריחו נודף\u0004 — \u0003אף כל דבר שקיטר ועולה וריחו נודף.\u0004","ויש לשאול: \u0003או אינו\u0004 כן, \u0003אלא\u0004 יש לפרש את ה\u0003כלל\u0004 האחרון \u0003בכלל\u0004 (כמו הכלל) ה\u0003ראשון, ופרט\u0004 האחרון \u0003בפרט\u0004 (כמו הפרט) ה\u0003ראשון?\u0004 על כך \u0003אמרת\u0004 (אומר אתה) \u0003לאו,\u0004 לא ניתן לומר כן. \u0003הא אין לך עליך לדון בלשון אחרון\u0004 שהצעת, \u0003אלא בלשון ראשון.\u0004","ומבארים את הברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003או אינו אלא כלל בכלל ראשון, ופרט בפרט ראשון? אמרת: לאו, הא אין עליך לדון.\u0004 ושואלים: \u0003מאי קושיא\u0004 \u0005[מהי הקושיה]\u0006 \"או אינו אלא כלל בכלל ראשון\"? ומשיבים, \u0003הכי קא קשיא ליה\u0004 \u0005[כך\u0006 היה \u0005קשה לו]:\u0006 שמא נאמר כי \u0003\"סמים\" בתראי תרי, כי סמים קדמאי תרין\u0004 \u0005[\"סמים\" האחרונים שנים\u0006 הם, \u0005כמו\u0006 ש\u0005\"סמים\" הראשונים\u0006 הם \u0005שנים]!\u0006 \u0003הדר ושני כדשנין\u0004 \u0005[חזר ותירץ כמו שתירצנו\u0006 קודם\u0005],\u0006 שאם \u0003כן, נכתוב קרא\u0004 \u0005[יכתוב המקרא]\u0006\u0003: \"סמים סמים נטף ושחלת וחלבנה\".\u0004","ושואלים: \u0003ומאי\u0004 \u0005[ומהו]\u0006 ששאל \"או אינו אלא... \u0003פרט בפרט ראשון\"?\u0004 ומשיבים: \u0003הכי קא קשיא ליה\u0004 \u0005[כך\u0006 היה \u0005קשה לו]:\u0006 הואיל ולמדים אנו במידת \"כלל ופרט וכלל\", לכל שהוא מעין הפרט המפורש בכתוב, וכפי שנאמר לעיל ש\u0003מיני אילנות ילפי\u0004 \u0005[למדים]\u0006 \u0003מן נטף, וגידולי קרקע ילפי\u0004 \u0005[למדים]\u0006 \u0003משחלת,\u0004 אם כן, \u0003ולילפי נמי\u0004 \u0005[ושילמדו גם כן]\u0006 \u0003מלבונה זכה, דאייתי בחד צד\u0004 \u0005[שיש בה צד אחד],\u0006 \u0003דניתי\u0004 \u0005[שיביא]\u0006 \u0003דבר שריחו נודף ואף על פי שאין קוטר ועולה!\u0004","\u0003הדר אמר\u0004 \u0005[חזר ואמר]:\u0006 \u0003אם כן, נכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003ללבונה זכה במיצעי\u0004 \u0005[באמצע],\u0006 בין \"סמים\" הראשון ל\"סמים\" השני, יחד עם נטף ושחלת וחלבנה, \u0003ותילף מינה\u0004 \u0005[ותלמד ממנה].\u0006 אלא, מתוך שנכתבה לאחר \"סמים\" השני — אין היא נדונת כפרט שבין שני הכללים.","ודוחים: \u0003אי כתביה\u0004 \u0005[אם היה כותב]\u0006 את \u0003לבונה זכה במיצעי\u0004 \u0005[באמצע],\u0006 \u0003הויין תרי עשר\u0004 \u0005[הריהם שנים עשר]\u0006 סממנים: \"סמים\" — שנים, נטף ושחלת וחלבנה ולבונה זכה — ארבעה, וביחד ששה, ועוד ששה מ\"סמים\" הכתוב בסוף, ולפי המסורת יש רק אחד עשר. ומשיבים: \u0003אם כן,\u0004 אם רק משום כך, \u0003נכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003לבונה זכה במיצעי\u0004 \u0005[באמצע],\u0006 \u0003וחלבנה לבסוף.\u0004 אלא ממה שהביא לבונה זכה לאחר \"סמים\" האחרון, למדנו כי אין למדים ממנה במידת כלל ופרט וכלל, ורק מה שקוטר ועולה כשר לקטורת. \u0003ריש לקיש אמר: מגופה\u0004 של המילה \"קטורת\" למדים דין זה, שכן \u0003מה לשון \"קטרת\"? דבר שקוטר ועולה.\u0004","\u0003אמר רב חנא בר בזנא אמר ר' שמעון חסידא: כל תענית שאין בה מפושעי ישראל\u0004 שמשתתפים בה בתענית ותפילה, \u0003אינה תענית, שהרי חלבנה ריחה רע, ו\u0004בכל זאת \u0003מנאה הכתוב עם סממני קטרת. אביי אמר, מהכא\u0004 \u0005[מכאן]\u0006 למדים זאת: \"\u0003ואגדתו על ארץ יסדה\"\u0004 (עמוס ט, ו), לומר, שבזמן שכולם מאוגדים יחד בארץ — אז היא מתייסדת ומתקיימת.","שנינו במשנתנו בין חייבי הכריתות: \u0003והסך בשמן המשחה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הסך בשמן המשחה לבהמה וכלים\u0004 — \u0003פטור, לגוים ולמתים\u0004 — \u0003פטור.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בהמה וכלים\u0004 פטור, \u0003דכתיב\u0004 \u0005[שנאמר]: \"\u0006\u0003על בשר אדם לא ייסך\"\u0004 (שמות ל, לב), \u0003ובהמה וכלים לאו אדם הוא;\u0004 סך על \u0003מתים נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור,\u0004 שכיון \u0003דמית ליה\u0004 \u0005[שמת לו]\u0006 — \u0003מת מיקרי\u0004 \u0005[\u0006הוא \u0005נקרא],\u0006 \u0003ולאו אדם. אלא\u0004 סך על \u0003גוים, אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור? הא\u0004 \u0005[הרי]\u0006 \u0003אדם נינהו\u0004 \u0005[הם]!\u0006","ומשיבים: \u0003לאיי\u0004 \u0005[לא כן\u0006 הדבר\u0005], דכתיב\u0006 \u0005[ש\u0006הרי \u0005נאמר]: \"\u0006\u0003ואתן צאני צאן מרעיתי אדם אתם\"\u0004 (יחזקאל לד, לא), לומר: \u0003אתם קרויין \"אדם\" ואין הגוים קרויין \"אדם\".\u0004","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 לגבי השלל שנלקח ממדין: \"\u0003ונפש אדם ששה עשר אלף\"\u0004 (במדבר לא, מ)! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכתוב \u0003ההוא\u0004 בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003בהמה,\u0004 שנמנתה שם גם כן.","ושואלים, \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006\u0003: \"ואני לא אחוס על נינוה...\u0004 אשר יש בה הרבה משתים עשרה רבו אדם\" (יונה ד, יא), ולא היו מישראל! ומשיבים: הכתוב \u0003ההוא\u0004 גם כן בא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003בהמה,\u0004 שהרי נוסף מיד לאחר מכן: \"ובהמה רבה\".","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר מדוע הסך משמן המשחה על גוים פטור — \u0003כדקתני תנא קמיה\u0004 \u0005[כמו ששנה התנא לפני] ר'\u0006 \u0003אלעזר: כל שישנו בסך,\u0004 שהוא מצווה שלא לסוך (את עצמו או אחרים) — \u0003ישנו בבל ייסך,\u0004 אסור לסוך אותו, \u0003וכל שאינו בסך,\u0004 וכגון גוי, שאינו מצווה באיסורי התורה — \u0003אינו בבל ייסך.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הסך בשמן המשחה לבהמה וכלים, לגוים ומתים\u0004 — \u0003פטור, למלכים ולכהנים,\u0004 לאחר שכבר נמשחו — ר' \u0003מאיר מחייב, ור' יהודה פוטר.\u0004 ושואלים: \u0003וכמה יסוך ויהא חייב? ר' מאיר אומר: כל שהוא, ר' יהודה אומר: כזית.\u0004 ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006\u0003 ר' יהודה\u0004 מתחילה כי הסך \u0003פטור,\u0004 אם כן על מה הוא מתחייב? ומשיבים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003פטר ר' יהודה\u0004 — הרי זה \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מלכים וכהנים, גבי\u0004 \u0005[אצל]\u0006 \u0003הדיוט\u0004 הוא \u0003מחייב.\u0004 ושואלים: ר' \u0003מאיר ור' יהודה במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006","\u0003אמר ר' יוסף: בהא פליגי\u0004 \u0005[בזה\u0006 הם \u0005חלוקים]\u0006\u0003, ר' מאיר סבר\u0004 \u0005[סבור]\u0006\u0003: \"על בשר אדם לא ייסך\"\u0004 (שמות ל, לב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003וכתיב\u0004 \u0005[נאמר]\u0006\u0003: \"ואשר יתן ממנו על זר\u0004 ונכרת מעמיו\" (שם לג), ומלשון האיסור יש ללמוד על חיוב הכרת, \u0003מה סיכה\u0004 שאסר הכתוב היא בשיעור \u0003כל שהוא,\u0004 שהרי לא מצאנו לה שיעור מוגדר — \u0003אף נתינה\u0004 שנזכרה בחיוב הכרת \u0003כל שהוא.\u0004","\u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003נתינה על זר מנתינה דעלמא\u0004 \u0005[שבכלל],\u0006 \u0003מה נתינה דעלמא\u0004 \u0005[שבכלל]\u0006 שיעורה \u0003כזית, אף נתינה\u0004 שעל \u0003זר\u0004 — \u0003כזית. אבל סיכה\u0004 שנצטוינו \u0003למימשח\u0004 \u0005[למשוח בו]\u0006 את המלכים \u0003וכהנים\u0004 — \u0003דברי הכל\u0004 אין לה שיעור, והיא \u0003כל שהוא. ואמר\u0004","\u0003רב יוסף: במאי פליגי\u0004 \u0005[במה חלוקים] ר'\u0006 \u0003מאיר ור' יהודה גבי\u0004 \u0005[אצל]\u0006 \u0003מלכים וכהנים\u0004 האם חייבים על סיכתם? ר' \u0003מאיר סבר\u0004 \u0005[סבור]\u0006\u0003: \"ואשר יתן ממנו על זר\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003ומלך וכהן השתא זרים נינהו\u0004 \u0005[עכשיו זרים הם],\u0006 ששוב אין צורך לקיים בהם משיחה. ור' \u0003יהודה סבר\u0004 \u0005[סבור]:\u0006 לענין האיסור לתת ממנו על זר \u0003בעינן עד דאיכא\u0004 \u0005[צריכים אנו עד שיש בו]\u0006 \u0003זר מתחלתו ועד סופו, ומלך וכהן מעיקרא לאו זרים הוו\u0004 \u0005[מתחילה לא זרים היו],\u0006 שהרי בתחילה נמשחו בשמן המשחה.","\u0003אמר רב איקא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי: ואזדו לטעמייהו\u0004 \u0005[והולכים בזה\u0006 ר' מאיר ור' יהודה \u0005לטעמיהם],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006"],["\u0003בת כהן שנישאת לישראל,\u0004 ולכן אינה רשאית לאכול בתרומה, \u0003ואכלה בתרומה\u0004 — \u0003משלמת את הקרן\u0004 לכהן, \u0003ו\u0004אם היה זה בשגגה \u0003אינה משלמת את החומש\u0004 שמוסיף זר האוכל תרומה (ויקרא כב, יד), שהרי אינה זרה ממש, משום שיכולה לחזור לכהונה אם ימות בעלה בלא בנים, \u0003ומיתתה,\u0004 אם זנתה — \u0003בשריפה\u0004 כבת כהן.","אבל בת כהן ש\u0003ניסת לאחד מן הפסולין\u0004 לכהונה, ובכך נתחללה מן הכהונה — \u0003משלמת קרן וחומש, ומיתתה בחנק,\u0004 כשאר בנות ישראל, אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: אחת זו ואחת זו,\u0004 גם הנישאת לפסול — \u0003משלמת הקרן ואינה משלמת החומש, ומיתתה בשריפה,\u0004 הואיל ולא היתה זרה מתחילתה. והיא שיטת ר' יהודה, בן מחלוקתו הקבוע של ר' מאיר, כפי שהסברנו לעיל לענין נתינה משמן המשחה על מלך, שצריך שיהא זר מתחילה ועד סוף.","\u0003אמר רב יוסף: מחלוקת\u0004 ר' מאיר ור' יהודה היא \u0003בנתינת שמן המשחה ובשינויי דשנינן\u0004 \u0005[וב\u0006אותם \u0005תירוצים שתירצנו]\u0006 והסברנו בענין זה, שלדעת ר' מאיר חייבים בכל שהוא, שהרי נאמרה בה לשון סיכה, ולדעת ר' יהודה בכזית, \u0003אבל נתינה דעלמא\u0004 \u0005[בכלל],\u0006 וכגון האיסור לתת לבונה על מנחת החוטא (ויקרא ה, יא) — \u0003דברי הכל כזית.\u0004","\u0003גופא\u0004 \u0005[\u0006דנים \u0005לגופו]\u0006 של דבר שהזכרנו. \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003ר' אלעזר: כל שישנו בסך,\u0004 שאסור לסוך את עצמו או את אחרים — \u0003ישנו בבל ייסך,\u0004 אסור לסוך אותו, \u0003וכל שאינו בסך,\u0004 וכגון גוי, שלא חייב במצוות — \u0003אינו בבל ייסך. אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: \u0003שפיר קאמרת\u0004 \u0005[יפה אמרת],\u0006 \"על בשר אדם \u0003לא ייסך\" כתיב\u0004 \u0005[נאמר]\u0006 (שמות ל, לב), ומשמעו שאסור לסוך אותו, \u0003וקרי ביה\u0004 \u0005[וקוראים בו]\u0006 גם \u0003\"לא יסיך\",\u0004 שהוא אסור לסוך אחרים, ומי שהוא בכלל \"לא יסיך\" הריהו בכלל \"לא ייסך\".","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב חנניה קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא: מנין לכהן גדול שנטל משמן המשחה שעל ראשו ונתן על בני מעיו\u0004 (בטנו), \u0003מנין שהוא חייב? שנאמר: \"על בשר אדם לא ייסך\"\u0004 (שם). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי, מאי שנא מהא דתניא\u0004 \u0005[במה שונה\u0006 הדבר \u0005מזו ששנויה\u0006 בברייתא]: \u0003כהן שסך\u0004 בעצמו \u0003בשמן של תרומה, בן בתו\u0004 של אותו כהן, שהוא \u0003ישראל, מתעגל\u0004 (מתמרח) \u0003בו\u0004 בשמן זה \u0003ואינו חושש\u0004 לאיסור הנאה של זר מתרומה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 לגבי תרומה, \u0003\"ומתו בו כי יחללהו\"\u0004 (ויקרא כב, ט) \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003כיון דחלליה\u0004 \u0005[שחיללו\u0006 הכהן\u0005],\u0006 שהשתמש בו לצורכו — \u0003הא איתחיל\u0004 \u0005[הרי התחלל],\u0006 נעשה חולין, ומותר לזר. \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003שמן המשחה כתיב\u0004 \u0005[נאמר]\u0006\u0003: \"כי נזר\u0004 שמן משחת \u0003אלהיו עליו\"\u0004 (שם כא, יב), \u0003\"שמן משחה\" קרייה רחמנא\u0004 \u0005[קראה אותו התורה],\u0006 ללמד \u0003דאף על גב דאיתא עליו לא איתחיל\u0004 \u0005[שאף על פי ש\u0006הוא \u0005ישנו עליו,\u0006 לאחר שנמשח, \u0005לא התחלל],\u0006 אלא עדיין הוא בקדושתו.","שנינו במשנה: \u0003על אלו חייבין על זדונו\u0004 כרת ועל שגגתו חטאת, ועל לא הודע (ספק חטאת) שלהם אשם תלוי. ובהמשך לכך \u0003קתני\u0004 \u0005[הוא שונה]:\u0006 \u0003חוץ ממטמא מקדש וקדשיו.\u0004 ושואלים: \u0003ממאי מפיק ליה\u0004 \u0005[ממה\u0006 הוא \u0005מוציא אותו]?\u0006 והלא גם מטמא מקדש וקדשיו חייב כרת וחטאת! ומשיבים: \u0003הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003חוץ ממטמא מקדש וקדשיו שאין מביא אשם תלוי\u0004 על ספקו.","ושואלים, \u0003וניתני נמי\u0004 \u0005[וישנה גם כן]:\u0006 \u0003חוץ ממי שעבר עליו יום הכיפורים, ש\u0004גם הוא \u0003אין מביא אשם תלוי\u0004 על הספק! \u0003אמר ריש לקיש: כי קתני\u0004 \u0005[כאשר הוא שונה]\u0006 במשנה את הפטורים מאשם תלוי הרי זה \u0003היכא דאיתיה\u0004 \u0005[במקום שישנו]\u0006 \u0003חטאת,\u0004 ספק חטא שצריך כפרה, \u0003ורחמנא פטריה\u0004 \u0005[והתורה פטרה אותו]\u0006 מלהביא אשם תלוי. אבל מי ש\u0003עבר עליו יום הכיפורים ליתיה\u0004 \u0005[אין בו]\u0006 \u0003חטאת,\u0004 ספק חטא שצריך כפרה, \u0003דקא כפר ליה\u0004 \u0005[ש\u0006הרי \u0005כיפר לו]\u0006 יום הכיפורים.","\u0003ר' יוחנן אמר:\u0004 מדובר במשנה \u0003במבעט, דקאמר\u0004 \u0005[שאומר]:\u0006 \u0003אין יום הכפורים מכפר,\u0004 ובמקרה זה אין יום הכיפורים מכפר עליו, \u0003דאי הדר ביה בתר\u0004 \u0005[שאם חוזר בו אחר]\u0006 \u0003יום הכיפורים, בעי לאיתויי\u0004 \u0005[צריך להביא]\u0006 \u0003אשם תלוי.\u0004 ומעירים: \u0003וריש לקיש,\u0004 שלא הסביר כן, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003מבעט נמי\u0004 \u0005[גם כן]\u0006 \u0003מכפר עליה\u0004 \u0005[עליו]\u0006 \u0003יום הכיפורים.\u0004","ומעירים: \u0003ובפלוגתא\u0004 \u0005[ו\u0006דבר שנוי \u0005במחלוקת]\u0006 של אמוראים כמה דורות לאחר מכן: \u0003האומר \"לא יתכפר לי חטאתי\",\u0004 החטאת שמקריבים עבורי, \u0003אביי אמר:\u0004 חטאת זו \u0003אינה מכפרת, רבא אמר: מכפרת.\u0004 ומסבירים, \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אמר: לא תיקרב,\u0004 איני רוצה שתקרב — \u0003דכולי עלמא לא פליגי דלא\u0004 \u0005[הכל אינם חלוקים שאינה]\u0006 \u0003מכפרת, דכתיב\u0004 \u0005[ש\u0006הרי זה \u0005נאמר]\u0006\u0003: \"יקריב אותו לרצנו\"\u0004 (שם א, ג), וקרבן שקרב שלא לרצונו ודאי אינו מועיל. אלא \u0003כי פליגי\u0004 \u0005[כאשר הם חלוקים]\u0006 הרי זה שאמר: \u0003תיקרב\u0004 החטאת \u0003ולא תכפר, אביי אמר: אין מכפרת, דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר לא תכפר. רבא אמר: מכפרת,\u0004 ש\u0003כיון\u0004 שאמר \u0003תיקרב,\u0004 ולכך אינו מתנגד — \u0003כפרה ממילא אתי\u0004 \u0005[מאליה באה].\u0006","ומעירים: \u0003והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003רבא\u0004 מדבריו, שהאומר \"לא תכפר עלי חטאתי\" — מכפרת. \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהא יום הכיפורים מכפר\u0004 בין \u0003על\u0004 ה\u0003שבין\u0004 מן העבירות שבידם \u0003ו\u0004בין \u0003על שאין שבין? ו\u0004לכאורה \u0003דין,\u0004 סברה הגיונית \u0003הוא, ומה חטאת ואשם מכפרין ויום הכפורים מכפר, מה חטאת ואשם אין מכפרין אלא על השבין\u0004 — אף יום הכפורים אין מכפר אלא על השבין! ויש לדחות:","\u0003לא, אם אמרת בחטאת ואשם שאין מכפרין על המזיד כשוגג, תאמר ביום הכפורים\u0004 שמרובה כפרתו, \u0003שמכפר על המזיד כשוגג? והואיל ומכפר על המזיד כשוגג,\u0004 אולי הוא \u0003מכפר\u0004 גם \u0003על שבין ו\u0004גם \u0003על שאין שבין!\u0004 לכך \u0003תלמוד לומר:\u0004 \"אך בעשור לחודש השביעי הזה יום הכיפורים הוא\" (ויקרא כג, כז), ולשון \u0003\"אך\" חלק,\u0004 מכפר הוא לשבים, ואינו מכפר לשאינם שבים.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שבין\" ו\"שאין שבין\"? אלימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003\"שבין\"\u0004 הוא אלה שחטאו ב\u0003שוגג, \"לא שבין\"\u0004 — אלה שחטאו במזיד, \u0003הא קתני\u0004 \u0005[הרי הוא שונה]:\u0006 \u0003לא אם אמרת בחטאת ואשם\u0004 שאין מכפרים על המזיד כשוגג. ומכאן שעניינים שונים הם!","\u0003אלא\u0004 תאמר ש\"שבין\" הוא מי שעומד בתשובתו מתחילה ועד סוף, ו\"אין שבין\" הוא \u0003כי הא\u0004 \u0005[כמו זו]\u0006 של \u0003עולא\u0004 ש\u0003אמר\u0004 בשם ר' \u0003יוחנן: אכל חלב\u0004 בשוגג \u0003והפריש קרבן\u0004 חטאת, וקודם שהקריבו \u0003נשתמד\u0004 (המיר דתו) \u0003ו\u0004אחר כך \u0003חזר בו\u0004 בתשובה — \u0003הואיל ונדחה\u0004 הקרבן בשעה שנשתמד \u0003ידחה.\u0004 והציעה הברייתא כי הוא הדין למי שנשתמד ועבר עליו יום הכיפורים, שלמרות שחזר בו — לא יכפר עליו יום הכיפורים הבא.","הבנה זו יש לדחות, שכן גם לגבי חטאת, \u0003נהי דאידחי\u0004 \u0005[אם אמנם נדחה]\u0006 ה\u0003קרבן\u0004 מן המזבח, ולכן שוב אינו ראוי להקרבה, כמו אם נפל בו מום ונרפא, הלוא \u0003גברא בר\u0004 \u0005[האיש בן]\u0006 \u0003כפרה הוא,\u0004 והרי יכול להביא חטאת נוספת ויתכפר לו! \u0003אלא\u0004 יש לפרש כי \u0003\"שבין\"\u0004 כוונתו — שאמר: \"\u0003יכפר עלי חטאתי\", \"שאין שבין\"\u0004 — שאמר: \"\u0003לא תכפר, עלי חטאתי\". שמע מינה\u0004 \u0005[למד מכאן]\u0006 מן הברייתא שחטאת אינה מכפרת על האומר: \"לא תכפר עלי חטאתי\", והוא שלא כדברי רבא מתחילה. אלא בוודאי חזר בו.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה] בין ברייתא זו, ששנינו בה שיום הכיפורים אינו מכפר אלא לשבים, למה ששנינו בברייתא אחרת: \u0003יכול לא יהא יום הכפורים מכפר אלא על\u0004 מי \u0003שנתענה בו ולא עשה בו מלאכה, וקראו מקרא קודש,\u0004 אבל מי שלא \u0003נתענה בו, ועשה בו מלאכה, ולא קראו מקרא קודש, יכול לא יהא יום כיפורים מכפר? תלמוד לומר: \"י ום הכפורים הוא\"\u0004 (ויקרא כג, כז), \u0003מכל מקום\u0004 הוא מכפר. ומעירים: \u0003ותרוייהו\u0004 \u0005[ו\u0006הרי שתיהן], שתי הברייתות, \u0003סתם סיפרא הוא,\u0004 ששתיהן שנויות בספרא (מדרש ההלכה לספר ויקרא) בסתם, וסתם ספרא ר' יהודה. ואם כן \u0003קשיין אהדדי\u0004 \u0005[קשות\u0006 הן \u0005זו על זו]!\u0006","\u0003אמר אביי, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו בה שיום הכיפורים מכפר רק על השבים — דברי \u0003רבי\u0004 היא \u0003אליבא\u0004 \u0005[לפי\u0006 שיטת] \u0003ר' יהודה, הא\u0004 \u0005[זו]\u0006 ששנינו בה שיום הכיפורים מכפר בכל אופן — דברי \u0003רבי אליבא דידיה\u0004 \u0005[לפי שיטתו שלו],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005], \u0003רבי אומר: כל עבירות שבתורה, בין עשה תשובה ובין לא עשה תשובה\u0004\u0006\u0003 — יום הכפורים מכפר, \u0004","\u0003חוץ מפורק עול\u0004 מצוות ממנו, \u0003ומגלה פנים בתורה,\u0004 שנוהג בה בחוצפה וזלזול, \u0003ומפר ברית בשר\u0004 (מילה), \u0003שאם עשה תשובה\u0004 — \u0003יום הכפורים מכפר, ואם לאו\u0004 — \u0003אין יום הכפורים מכפר.\u0004 ואם כן, לפי שיטת רבי יום הכיפורים מכפר גם על שאינם שבים.","\u0003רבא אמר: הא והא רבי אליבא דנפשיה\u0004 \u0005[זו וזו\u0006 דברי \u0005רבי לפי שיטת עצמו],\u0006 \u0003ומודה רבי בעבירות\u0004 של \u0003יום הכפורים גופיה\u0004 \u0005[עצמו],\u0006 כגון שאכל או עשה מלאכה ביום הכיפורים — ש\u0003לא מכפר\u0004 הכיפורים אלא לשבים. \u0003דאי לא תימא הכי\u0004 \u0005[שאם אינך אומר כך],\u0006 \u0003כרת\u0004 של \u0003יום הכפורים ל\u0004שיטת \u0003רבי, כיון\u0004 שבכל \u0003שעתא ושעתא\u0004 \u0005[שעה ושעה]\u0006 יום הכיפורים \u0003מכפר, היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותו]\u0006 שיהיה חייב כרת על כך? אלא מדובר במי שאינו שב מעבירות אלו ביום הכיפורים.","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה\u0006 בדבר]? \u0003דילמא דעבד עבידתא כולי ליליא\u0004 \u0005[שמא\u0006 חייב כרת במקרה \u0005שעשה מלאכה כל הלילה]\u0006 \u0003ובהדי עמוד השחר מית\u0004 \u0005[מת],\u0006 \u0003דלא הוה יממא דלכפר ליה\u0004 \u0005[שלא היה יום שיכפר לו],\u0006 ואין כפרה אלא ביום עצמו שנאמר: \"כי ביום הזה יכפר עליכם\" (ויקרא טז, ל)! ומשיבים: \u0003תינח כרת דליליא\u0004 \u0005[נניח כרת ש\u0006עבר עליו ב\u0005לילה],\u0006 \u0003כרת דיממא\u0004 \u0005[של היום]\u0006 \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותו]?\u0006 והרי בכל שעה הוא מתכפר! אלא מכאן שעל עבירות של יום הכיפורים עצמו אינו מכפר.","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה\u0006 בזה]? \u0003דילמא בהדי דקאכל נהמא חנקתיה אומצא\u0004 \u0005[שמא\u0006 ייתכן הדבר אם \u0005בזמן שאכל לחם חנקתו אומצת הבשר\u0006 שאכל עמו ומת\u0005],\u0006 \u0003דלא הוה ליה שהות ביממא דלכפר ליה\u0004 \u0005[שלא היתה לו שהות ביום שיכפר].\u0006 \u0003אי נמי דעבד עבידתיה\u0004 \u0005[או גם כן שעשה מלאכתו]\u0006 \u0003סמוך לשקיעת החמה,\u0004 בסוף היום, ולא הספיק להתכפר. \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 \u0003בהדי דעביד עבידתיה פסקיה מרא לשקיה ומית\u0004 \u0005[בזמן שעשה מלאכתו חתך המעדר\u0006 שעבד בו את שוקו ומת], \u0003דלא הוה ליה שהות ביממא דלכפר ליה\u0004 \u0005[שלא היתה לו שהות ביום שיכפר לו].\u0006","שנינו במשנה \u0003וחכמים אומרים: אף המגדף,\u0004 שנאמר בקרבן החטאת: \"תורה אחת יהיה לכם לעושה בשגגה\" (במדבר טו, כט), יצא מגדף שאינו עושה מעשה. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003אף המגדף שאין בו מעשה,\u0004 כלפי מה מתייחסים הדברים?","ומסבירים: \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003שמעו לר' עקיבא דתני\u0004 \u0005[ש\u0006הוא שונה] במשנתנו ברשימת הכריתות (שמביאים על שגגתן חטאת) \u0003בעל אוב, ולא תני\u0004 \u0005[שונה]\u0006 \u0003ידעוני,\u0004 ו\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 ידעוני שלא \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003קרבן\u0004 — \u0003משום דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003מעשה,\u0004 והלא \u0003מגדף\u0004 ששנינו במשנה שמביא עליו קרבן, \u0003נמי לית ביה\u0004 \u0005[גם כן אין בו]\u0006 \u0003מעשה!\u0004","ובענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מגדף מביא קרבן\u0004 חטאת על שגגתו, \u0003הואיל ונאמר בו כרת, דברי ר' עקיבא, ואומר: \"ונשא חטאו\"\u0004 (ויקרא כד, טו). ושואלים: \u0003וכללא\u0004 \u0005[וכלל]\u0006 \u0003הוא,\u0004 שכל \u0003היכא דכתיב ביה\u0004 \u0005[מקום שכתוב בו]\u0006 \u0003כרת מייתי\u0004 \u0005[מביא]\u0006 \u0003קרבן? והא\u0004 \u0005[והרי]\u0006 \u0003פסח ומילה דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 \u0003כרת, ולא מייתי\u0004 \u0005[ואינו מביא]\u0006 \u0003קרבן!\u0004"],["ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003מגדף מביא קרבן הואיל ובא בו\u0004 דין \u0003כרת במקום קרבן,\u0004 שאותה פרשה עוסקת בדין החטאת (ראה במדבר טו, כז—לא), \u0003דברי ר' עקיבא; קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מיגו דבעי מכתב כרת בעלמא\u0004 \u0005[מתוך שהיה צריך לכתוב כרת בסתם],\u0006 \u0003וכתיב\u0004 \u0005[וכתוב]\u0006 בו \u0003כרת במקום קרבן, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי הוא \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003קרבן\u0004 על שגגתו.","ומה שנאמר, \u0003ואומר: \"חטאו ישא\"\u0004 (במדבר ט, יג) — \u0003אתא לרבנן\u0004 \u0005[בא ל\u0006דברי \u0005חכמים]\u0006 הסבורים שאינו מביא קרבן, \u0003והכי קאמר\u0004 \u0005[וכך אומר]\u0006\u0003 ר' עקיבא לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003אמריתו\u0004 \u0005[אומרים אתם]\u0006 \u0003מגדף לית ביה\u0004 \u0005[אין בו]\u0006 \u0003מעשה,\u0004 שהרי \u0003מהו מגדף\u0004 — \u0003מברך\u0004 (מקלל) \u0003את השם. אלא כרת דכתיב\u0004 \u0005[שנאמר\u0006 בו] \"את ה' הוא מגדף ונכרתה\" (שם טו, ל) \u0003למאי אתא\u0004 \u0005[למה בא]\u0006 אם לא כדי לחייבו בקרבן?","\u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003ליתן כרת למקלל,\u0004 ללמד שמה שנאמר בספר ויקרא (כד, טו): \"איש כי יקלל ונשא חטאו\", עניינו כרת, והוצרכנו לכך כדי ללמוד ממנו בגזירה שווה כרת למי שהיה צריך לעשות פסח שני ולא עשאו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003במקלל: (\"חטאו ישא האיש ההוא\") [\" ונשא חטאו\"], וכתיב\u0004 \u0005[ונאמר]\u0006\u0003 ב\u0004מי שלא עשה גם \u0003פסח שני: \"חטאו ישא\"\u0004 (במדבר ט, יג), \u0003מה להלן\u0004 במקלל, \"ונשא חטאו\" הוא \u0003כרת\u0004 — \u0003אף כאן\u0004 בפסח שני, \"חטאו ישא\" — \u0003כרת.\u0004","ובענין מגדף \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \"\u0003את ה'\u0004 הוא \u0003מגדף\"\u0004 (שם טו, ל), יש להבינו כאילו נאמר \"מגרף\", \u0003איסי בן יהודה אומר, כאדם האומר לחבירו: גירפתה\u0004 (קינחת) \u0003הקערה וחיסרתה,\u0004 פגעת בקערה עצמה; \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מגדף מברך את השם הוא.\u0004","\u0003ר' אלעזר בן עזריה אומר, כאדם האומר לחבירו גירפתה הקערה\u0004 הוצאתה ממנה הכל, \u0003ולא חיסרתה; קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מגדף היינו\u0004 \u0005[הריהו]\u0006 \u0003עובד עבודה זרה,\u0004 אבל אינו פושט ידו בשם ה'.","וכן \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא אחרת]: \"\u0003את ה'\u0004 הוא מגדף\", \u0003רבי אלעזר בן עזריה אומר: בעובד עבודה זרה הכתוב מדבר, וחכמים אומרים: לא בא הכתוב אלא ליתן כרת למברך השם.\u0004","\u0003יש\u0004 נשים \u0003מביאות קרבן\u0004 יולדת, וחטאת העוף שבו \u0003נאכל\u0004 על ידי הכהנים, \u0003ויש מביאות קרבן ואינו נאכל, ויש שאינם מביאות\u0004 כלל.","ומפרטים, אלו \u0003מביאות קרבן ונאכל: המפלת\u0004 ולד שצורתו \u0003כמין בהמה, חיה\u0004 או \u0003עוף, דברי ר' מאיר. וחכמים אומרים:\u0004 אינה מביאה קרבן \u0003עד שיהא בו מצורת אדם.\u0004","\u0003המפלת\u0004 כמין \u0003סנדל,\u0004 שאין לו צורה, \u0003או שיליא\u0004 שהעובר מצוי בה, \u0003או שפיר\u0004 (עובר) \u0003מרוקם,\u0004 שניכרת בו צורת ולד, \u0003ו\u0004כן ולד \u0003היוצא מחותך, וכן שפחה\u0004 כנענית של ישראל \u0003שהפילה, מביאה קרבן ונאכל.\u0004","\u0003ואלו מביאות\u0004 קרבן \u0003ואינן נאכלות: המפלת ואין\u0004 איש \u0003יודע מה הפילה, ושתי נשים שהפילו\u0004 באותו מקום, \u0003אחת\u0004 הפילה ולד \u0003ממין פטור\u0004 מקרבן, \u0003ואחת ממין חובה,\u0004 ואין ידוע מה הפילה כל אחת — צריכה כל אחת מהן להביא קרבן יולדת, שמא היא החייבת, והחטאת אינה נאכלת. \u0003אמר ר' יוסי: אימתי? בזמן שהלכו זה למזרח וזה למערב,\u0004 וכל אחת מהן באה בנפרד להקריב את קרבנה. \u0003אבל אם היו שתיהן עומדות\u0004 יחד — \u0003שתיהן מביאות קרבן\u0004 חטאת אחד עבור שתיהן, \u0003ו\u0004הוא \u0003נאכל.\u0004","\u0003אלו שאין מביאות\u0004 קרבן, מפני שמה שהפילו אינו קרוי ולד: \u0003המפלת שפיר\u0004 שהיה \u0003מלא מים,\u0004 או \u0003מלא דם מלא גנינים\u0004 (גוונים שונים), וכן \u0003המפלת כמין דגים וחגבים ושקצים ורמשים,\u0004 וכן \u0003המפלת יום ארבעים\u0004 להריונה, וכן \u0003יוצא דופן,\u0004 שנולד על ידי ניתוח ולא בלידה רגילה. \u0003ר' שמעון\u0004 היה \u0003מחייב ביוצא דופן\u0004 קרבן לידה.","ומבררים: \u0003שפחה\u0004 שילדה \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שהיא מביאה קרבן יולדת? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בפרשת היולדת \"דבר אל \u0003בני ישראל\"\u0004 (ויקרא יב, ב), \u0003אין לי אלא בני ישראל, גיורת ושפחה\u0004 כנענית \u0003מנין? תלמוד לומר: \"אשה\u0004 כי תזריע\" (שם), כל אשה.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"וכן שפחה\"?\u0004 לשם מה הדגשה זו? ומסבירים, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 כל מצו‍ת שהאשה חייבת בה עבד כנעני \u0003חייב בה,\u0004 וכן שפחה — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים] \u0003בדבר ששוה בין איש ובין אשה. אבל\u0004 קרבן \u0003יולדת,\u0004 כיון שבנשים \u0003איתא\u0004 \u0005[ישנו]\u0006 \u0003באנשים ליתא\u0004 \u0005[איננו],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 שלא \u0003תחייב\u0004 \u0005[תתחייב]\u0006 בו \u0003שפחה, אהכי תנא\u0004 \u0005[משום כך שנה]\u0006 במשנתנו: \"וכן \u0003שפחה\".\u0004","שנינו במשנה \u0003אלו מביאין קרבן,\u0004 ובהמשך שנינו כי לדעת ר' יוסי שתי נשים שהפילו, אחת ממין פטור ואחת ממין חובה, אם היו שתיהן לפנינו — מביאות קרבן ונאכל. ושואלים: \u0003מאי עבדין\u0004 \u0005[מה הן עושות]?\u0006 \u0003מייתין תרוייהו חד\u0004 \u0005[מביאות שתיהן כאחד]\u0006 \u0003קרבן ודאי\u0004 לעולה, \u0003וחטאת עוף\u0004 מספק, \u0003ומתני\u0004 \u0005[ומתנות]\u0006 שאם זו חייבת בחטאת הרי היא שלה, ואם לא הריהי של האחרת.","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו] לר'\u0006 \u0003יוסי תנאה\u0004 \u0005[\u0006פתרון של \u0005תנאי]\u0006 בחטאת? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שתי נשים שאחת מהן אכלה בשוגג חתיכת חלב, וחייבת חטאת, ואינן יודעות מי מהן, ר' שמעון אומר: מביאות שניהן חטאת אחת, ר' \u0003יוסי אומר: אין שניהן מביאות חטאת אחת. אלמא\u0004 \u0005[מכאן]\u0006 שלר' \u0003יוסי לית ליה תנאה\u0004 \u0005[אין לו תנאי]!\u0006","\u0003אמר רבא: מודה ר' יוסי במחוסר כפרה,\u0004 כגון בקרבן יולדת, שעושים בו תנאי. \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם ר' \u0003יוחנן: מודה ר' יוסי במחוסר כפרה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר]? \u0003התם בעי גברא\u0004 \u0005[שם,\u0006 בחטאת הבאה על חטא, \u0005צריך האיש]\u0006 \u0003ידיעה\u0004 ודאית שחטא כדי להביא קרבן, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006\u0003: \"או הודע אליו חטאתו\"\u0004 (שם ד, כח), \u0003הילכך לא מתיין ומתני\u0004 \u0005[משום כך אינן מביאות ומתנות],\u0006 \u0003אבל הכא כי מתיין\u0004 \u0005[כאן כאשר מביאות]\u0006 הנשים \u0003קרבן\u0004 — הרי זה רק כדי \u0003לאישתרויי\u0004 \u0005[להיות מותרות]\u0006 \u0003באכילת קדשים.\u0004","ודבר זה מפורש בדברי ר' יוסי \u0003כדתני סיפא דההיא\u0004 \u0005[כמו ששנה בסופה של אותה\u0006 משנה]: ר' \u0003יוסי אומר: כל חטאת שהיא באה על חטא\u0004 — \u0003אין שתים מביאות אותה,\u0004 משמע שחטאת שאינה באה על חטא — מביאות.","שנינו במשנה: \u0003אלו שאין מביאות\u0004 וכו', \u0003ר' שמעון מחייב ביוצא דופן.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון? אמר ריש לקיש, אמר קרא\u0004 \u0005[המקרא]\u0006\u0003: \"ואם נקבה תלד\"\u0004 (ויקרא יב, ה), ויכול היה לכתוב \"ואם נקבה\", שהרי ביולדת מדובר שם, אלא \u0003לרבות לידה אחרת, מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — \u0003יוצא דופן.\u0004","ושואלים: \u0003ורבנן מאי טעמא\u0004 \u0005[וחכמים,\u0006 הפוטרים ביוצא דופן, \u0005מה טעמם]?\u0006 \u0003אמר ר' מני בר פטיש:\u0004 נאמר \"\u0003אשה כי תזריע וילדה\"\u0004 (שם כ) — \u0003עד שתלד ממקום שמזרעת\u0004 (מתעברת), ואם הלידה היא ממקום אחר, כגון מדופן הרחם — אין זו נחשבת לידה.","אשה שילדה בת, מונה ארבעה עשר ימי טומאה, וששים וששה ימי טהרה (שדם שהיא רואה אז אינו מטמא כדם הנדה), וביום השמונים ואחד מביאה קרבנה (שם יב, א—ח), וכל נפל שתפיל בתוך שמונים הימים אינו מחייב אותה בקרבן נוסף. ונחלקו בדין \u0003המפלת לאור\u0004 (ליל) היום ה\u0003שמונים ואחד\u0004 לאחר לידתה, ש\u0003בית שמאי פוטרין מן הקרבן, ובית הלל מחייבין.\u0004","\u0003אמרו בית הלל לבית שמאי: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003אור שמונים ואחד מיום שמונים ואחד,\u0004 שאם הפילה בו חייבת קרבן נפרד? \u0003אם שיוה לו לטומאה,\u0004 שדמה טמא בליל שמונים ואחד כמו ביומו, \u0003לא ישוה לו לקרבן?\u0004","\u0003אמרו להם בית שמאי: לא, אם אמרתם במפלת יום שמונים ואחד,\u0004 שחייבת בקרבן נוסף, \u0003שכן\u0004 כבר \u0003יצאה לשעה שהיא ראויה להביא בה קרבן, תאמר במפלת לאור שמונים ואחד, ש\u0004בשעה שהפילה עדיין \u0003לא יצאה לשעה שהיא ראויה להביא בה קרבן?\u0004 שהרי אין מקריבים קרבן בלילה.","\u0003אמרו להן בית הלל: והלא המפלת יום שמונים ואחד שחל להיות בשבת תוכיח, שלא יצאה לשעה שהיא ראויה להביא בה קרבן,\u0004 שאין מקריבים קרבנות יחיד בשבת, \u0003ו\u0004גם אתם מודים ש\u0003חייבת קרבן\u0004 נוסף אם הפילה בשבת זו!","\u0003אמרו להן בית שמאי: לא, אם אמרתם יום שמונים ואחד שחל להיות בשבת, שאף על פי שאינו ראוי לקרבן יחיד,\u0004 מכל מקום \u0003ראוי לקרבן ציבור,\u0004 שמקריבים בשבת קרבנות ציבור שזמנם קבוע, \u0003תאמר במפלת לאור שמונים יום ואחד, שאין הלילה ראוי\u0004 כלל להקרבה, \u0003לא לקרבן יחיד ולא לקרבן ציבור?\u0004","\u0003והדמים\u0004 שמטמאים בליל שמונים ואחד \u0003אינן מוכיחים\u0004 לחייב קרבן אם תפיל אז, \u0003ש\u0004הרי \u0003המפלת בתוך מלאת\u0004 שמונים הימים — \u0003דמיה טמאים\u0004 כדין יולדת, \u0003ו\u0004מכל מקום \u0003פטורה מן הקרבן.\u0004"],["כהמשך לדיון שבמשנה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006\u0003: אמרו להן בית הלל לבית שמאי: הרי הוא אומר\u0004 \"ובמלאת ימי טהרה לבן או \u0003לבת\"\u0004 (ויקרא יב, ו), והיה יכול לכתוב \"ולבת\", ונכתב \"או לבת\" — \u0003לרבות אור שמונים ואחד,\u0004 שאם הפילה בו ולד — חייבת בקרבן נוסף.","מסופר, ר' \u0003הושעיא הוה שכיח קמיה\u0004 \u0005[היה מצוי לפני]\u0006\u0003 בר קפרא,\u0004 היה לומד לפניו, \u0003שבקיה ואתא קמיה\u0004 \u0005[עזב אותו והלך ללמוד לפני] ר'\u0006 \u0003חייא. יומא חד פגע ביה\u0004 \u0005[יום אחד פגש בו]\u0006 ר' הושעיא בבר קפרא, \u0003בעא מיניה\u0004 \u0005[שאל אותו]:\u0006 \u0003זב,\u0004 שאם ראה שלוש ראיות צריך להביא קרבן ביום השמיני לטהרתו, \u0003שראה\u0004 שוב \u0003שלש ראיות\u0004 של זוב \u0003בליל שמיני, מה בית הלל אומרים בדבר זה?\u0004 האם צריך להביא קרבן נפרד על טומאה זו, כמו הנטמא ביום השמיני עצמו?","וצדדי השאלה: האם \u0003טעמייהו\u0004 \u0005[טעמם]\u0006 של בית \u0003הלל\u0004 שמצריכים קרבן נוסף \u0003במפלת בלילה\u0004 של שמונים ואחד, הוא \u0003משום\u0004 יתור הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \"או \u0003לבת\", אבל זב שראה שלש ראיות בליל שמיני\u0004 — \u0003פטרי\u0004 \u0005[פוטרים\u0006 הם\u0005],\u0006 \u0003דלא מייתרי קראי\u0004 \u0005[ש\u0006הרי \u0005אין הכתובים\u0006 בו \u0005מיותרים],\u0006 \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 ומיולדת למדנו למקרים אחרים, וחייב להביא קרבן נוסף על טומאה זו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר קפרא: מה בבלי\u0004 (ר' חייא, שעלה מבבל) \u0003אומר בדבר זה? אישתיק\u0004 \u0005[שתק]\u0006\u0003 ר' הושעיא, לא אמר כלום. אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר קפרא:\u0004 וכי \u0003צריכין\u0004 אנו \u0003לדברי עייא\u0004 (חייא)? הבה \u0003נחזור על הראשונות,\u0004 ששנינו בברייתא: \u0003הרי הוא אומר \"לבת\"\u0004 — \u0003לרבות אור שמונים ואחד,\u0004 ומשמע שרק בענין יולדת אמורים הדברים.","ומציעים: \u0003נימא כתנאי\u0004 \u0005[האם נאמר\u0006 ששאלה זו שנויה כמחלוקת תנאים]: \u0003זב שראה שלש ראיות בליל שמיני, תני חדא\u0004 \u0005[שנויה ברייתא אחת]:\u0006 \u0003מביא\u0004 קרבן נפרד על זיבה זו, \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אינו מביא. מאי לאו תנאי היא\u0004 \u0005[האם לא מחלוקת תנאים היא],\u0006 \u0003דהא דתניא\u0004 \u0005[שזו ששנויה]\u0006 \u0003מביא, קסבר\u0004 \u0005[סבור הוא]\u0006 התנא: \u0003לילה,\u0004 למרות שאין מקריבים בו, \u0003אין\u0004 נחשב למחוסר \u0003זמן,\u0004 וכאילו נעשה זב ביום השמיני עצמו, \u0003והדתני\u0004 \u0005[וזה ששונה]\u0006 \u0003אין מביא, קסבר\u0004 \u0005[סבור הוא]\u0006 שלילה \u0003מחוסר זמן,\u0004 ועדיין לא הגיע זמנו של הקרבן על הזיבה הראשונה?","\u0003אמר רב הונא בר אחא אמר ר' אלעזר: הני תנאי סברי\u0004 \u0005[\u0006שני \u0005התנאים הללו סבורים]\u0006 ש\u0003לילה מחוסר זמן,\u0004 ולדברי שניהם, אם ראה שלוש ראיות בליל שמיני אינו מביא קרבן נוסף. \u0003והא דתניא\u0004 \u0005[וזו ששנויה]\u0006 שאם ראה שלוש בליל שמיני \u0003מביא\u0004 — עוסקת \u0003בזב בעל שתי ראיות,\u0004 שכיון שכבר נטהר, ואינו חייב בקרבן לזיבתו הראשונה — טומאה חדשה היא. \u0003והדתניא\u0004 \u0005[וזו ששנויה]\u0006 \u0003אין מביא\u0004 — \u0003בזב בעל שלש ראיות,\u0004 שחייב בקרבן, ועדיין לא הגיע זמן קרבנו.","ושואלים: אם היה זה \u0003זב בעל שתי ראיות, מאי למימרא\u0004 \u0005[מדוע הוצרך לומר]\u0006 שמביא? פשוט הדבר! ומשיבים, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003דוקא ראה בליל שמיני\u0004 מביא קרבן, \u0003אבל\u0004 אם ראה \u0003ביממא\u0004 \u0005[ביום]\u0006 ה\u0003שביעי\u0004 — \u0003לא, משום שקסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003כל ראייה\u0004 של זיבה \u0003שסותרת\u0004 את ימי הטהרה, שצריך לחזור ולמנות שבעה נקיים — \u0003אין מביאה לידי קרבן.\u0004","\u0003אמר רבא: אמאי אוקימתא להא דתניא\u0004 \u0005[על מה העמדת את זו ששנויה]\u0006 שזב שראה שלוש ראיות בליל שמיני \u0003אין מביא\u0004 קרבן נוסף — \u0003בזב בעל שלש ראיות,\u0004 אם כן, \u0003ליתנייה\u0004 \u0005[שישנה אותה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 הרשימה ששנינו בפרק הבא, של \u0003חמשה מביאין קרבן אחד על עבירות\u0004 (טומאות) \u0003הרבה!\u0004 ומשיבים: \u0003לא פסיקא\u0004 \u0005[אין זה דבר פסוק,\u0006 חתוך\u0005],\u0006 מפני שיש בזב שראה בליל שמיני מקרים שונים, ולא בכולם הדין כן, שאמר ר' \u0003יוחנן: ראה אחת בלילה\u0004 של שמיני \u0003ושתים ביום\u0004 השמיני — \u0003מביא\u0004 קרבן נוסף, ראה \u0003שתים\u0004 ראיות \u0003בלילה\u0004 של שמיני \u0003ואחת ביום\u0004 — \u0003אין מביא.\u0004","ולגופם של דברי ר' יוחנן, \u0003אמר רב יוסף: תדע,\u0004 יש לי הוכחה לכך שאם ראה \u0003אחת בלילה\u0004 של שמיני \u0003ושתים ביום מביא\u0004 על כך קרבן, \u0003דהא\u0004 \u0005[שהרי]\u0006 בכלל, \u0003ראייה ראשונה\u0004 של זב דינה כמו \u0003שכבת זרע בעלמא\u0004 \u0005[בלבד],\u0006 שהרואה זיבה פעם אחת טובל וטהור בערב, כמו בעל קרי, \u0003ואילו חזי תרתין אחרנייתא מצטרפי להו\u0004 \u0005[אם הוא רואה שתי ראיות מצטרפות הן]\u0006 לראשונה, לעשותו זב ולחייבו קרבן.","\u0003אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מידי איריא\u0004 \u0005[כלום שייך\u0006 הדבר\u0005]?\u0006 אין מכאן הוכחה, שהרי \u0003ראייה ראשונה של זב חזייה\u0004 \u0005[ראה אותה]\u0006 \u0003בזמן חיובא\u0004 \u0005[\u0006שיש בו \u0005חיוב\u0006 קרבן\u0005],\u0006 ולכן היא מצטרפת לשתיים שאחריה, אבל ראיה \u0003אחת בלילה\u0004 שמיני, \u0003כיון דלאו בזמן חיובא חזייה\u0004 \u0005[שלא בזמן חיוב\u0006 קרבן על שתי הראיות הבאות \u0005ראה אותה],\u0006 \u0003אי לאו דאשמעינן\u0004 \u0005[אם לא שהשמיענו] ר'\u0006 \u0005יוחנן שמצטרף,\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003לא תצטרף.\u0004","\u0003ועל מה שאמר ר' יוחנן שאם ראה שתים בליל שמיני אינו מביא קרבן נוסף, מפני שלילה מחוסר זמן, ועדיין לא הגיע זמן הקרבן של הזיבה הראשונה, שואלים: ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן לילה מחוסר זמן?\u0004","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003חזקיה:\u0004 נזיר שנטמא בטומאת מת, ונטהר, וצריך להביא קרבן ביום השמיני, וחזר ו\u0003נטמא ביום\u0004 השמיני — מביא קרבן נוסף. נטמא \u0003בלילה\u0004 שמיני — \u0003אין מביא,\u0004 שלילה מחוסר זמן, ועדיין לא הגיע זמן קרבנו הראשון. ור' \u0003יוחנן אמר: אפילו\u0004 נטמא \u0003בלילה\u0004 — \u0003מביא\u0004 קרבן נוסף. הרי שלדעתו לילה אינו מחוסר זמן!","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אומר] ר'\u0006 \u0003יוחנן\u0004 לענין זב, שאם ראה \u0003שתים בלילה ואחת ביום אין מביא\u0004 — הרי זה \u0003לדברי האומר\u0004 לילה \u0003מחוסר זמן,\u0004 אבל הוא אינו סבור כן.","ותמהים: \u0003לדברי האומר פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006\u0003, ואין בכך חידוש! ומשיבים: ההלכה הראשונה, במקרה שראה אחת בלילה ושתים ביום\u0004 היא \u0003איצטריכא ליה\u0004 \u0005[הוצרכה לו],\u0006 להשמיענו שחייב קרבן נוסף אפילו לשיטה זו, ואגב כך נאמרה גם ההלכה השניה. ומדוע הוצרכה אותה הלכה? שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דלאו בזמן חיובא קחזי ליה\u0004 \u0005[שלא בזמן החיוב\u0006 של הראיות הנוספות \u0005הוא רואה אותה],\u0006 את הראיה הראשונה, לכן \u0003לא תצטרף, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שלמרות זאת היא מצטרפת.","\u0003האשה שיש עליה ספק חמש לידות,\u0004 שאין ידוע אם חייבת עליהן קרבן (ומביאה קרבן ואינו נאכל), \u0003ו\u0004כן אם היו עליה \u0003ספק חמש זיבות\u0004 — \u0003מביאה קרבן אחד,\u0004 ומאותה שעה נטהרה \u0003ואוכלת בזבחים, ואין השאר עליה חובה.\u0004 היו עליה \u0003חמש זיבות ודאות\u0004 או \u0003חמש לידות ודאות\u0004 — \u0003מביאה קרבן אחד ואוכלת בזבחים, ו\u0004אולם במקרה זה \u0003השאר עליה חובה.\u0004","\u0003מעשה שעמדו קינין בירושלים ב\u0004מחיר של \u0003דינר זהב,\u0004 שהסוחרים הפקיעו את מחיריהם בגלל הביקוש הרב לקרבנות יולדת וזבה, \u0003אמר רבן שמעון בן גמליאל\u0004 בשבועה: \u0003המעון הזה, לא אלין הלילה עד שיהיה\u0004 שוויים \u0003בדינרין\u0004 של כסף! \u0003בסוף נכנס לבית דין ולמד: האשה שיש עליה חמש לידות ודאות\u0004 או \u0003חמש זיבות ודאות\u0004 — \u0003מביאה קרבן אחד ואוכלת בזבחים ואין השאר עליה חובה,\u0004 וכך הוזלו \u0003ועמדו קינין ביום ההוא ברבעתים,\u0004 ברבע דינר כסף כל אחד, שכבר לא היה ביקוש גדול כל כך לקינים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האשה שיש עליה \u0003חמש לידות ודאי\u0004 ו\u0003חמש זיבות ספק, או חמש לידות ודאי וחמש לידות ספק\u0004 — \u0003מביאה שתי קינין, אחת על הודאי ואחת על הספק, של ודאי נאכלת והשאר עליה חובה, של ספק אין נאכלת ואין השאר עליה חובה.\u0004","\u0003ר' יוחנן בן נורי אומר: על\u0004 קרבנות \u0003ודאי תאמר: על האחרונה\u0004 אני מביאה אותו, \u0003ותפטר.\u0004 על \u0003של ספק, אם יש\u0004 קרבן \u0003ודאי ביניהן, תאמר: על הודאי\u0004 אני מביאה, \u0003ותפטר. ואם לאו, תאמר: על אחד מהן\u0004 אני מביאה (ולאו דווקא על האחרונה), \u0003ותפטר. ר' עקיבא אומר: בין על הודאי בין על הספק,\u0004 כלומר, אפילו על הוודאי \u0003תאמר: על אחת מהן\u0004 אני מביאה, \u0003ותפטר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרב פפא, אימא לך משמיה\u0004 \u0005[אומר לך משמו]\u0006 של \u0003רבא: הני תנאי במאי פליגי\u0004 \u0005[תנאים אלו במה נחלקו],\u0006 ש\u0003ר' יוחנן בן נורי\u0004 שמצריך להביא דווקא על האחרונה, \u0003מדמי להון\u0004 \u0005[מדמה אותם]\u0006 את קורבנות היולדת \u0003לחטאת\u0004 הבאה על חטא, \u0003דמאן\u0004 \u0005[שמי]\u0006 ש\u0003חייב חמש חטאות\u0004 אינו מתכפר \u0003עד דמייתי כולהון\u0004 \u0005[שמביא את כולן]\u0006 \u0003ו\u0004רק הקרבן שמביא ב\u0003סוף מכפר ליה\u0004 \u0005[לו\u0006 לגמרי\u0005],\u0006 \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 ורק אם הביאה על האחרונה — נתכפרה כדי לאכול קדשים.","ור' \u0003עקיבא מדמי להון לטבילין\u0004 \u0005[מדמה אותם לטבילות],\u0006 \u0003דמאן דמחייב\u0004 \u0005[שמי שחייב]\u0006 \u0003חמש טבילות, כיון דטביל חדא זימנא איטהר\u0004 \u0005[כיון שטבל פעם אחת נטהר],\u0006 \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה],\u0006 וברגע שהביאה קרבן על אחד מהם — נטהרה ומותרת לאכול קדשים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא: אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 ש\u0003ר' יוחנן בן נורי לחטאת מדמי להן\u0004 \u0005[מדמה אותן],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 בקרבנות \u0003של ספק תאמר: על אחת מהן, ותפטר? אילו מאן דמחייב\u0004 \u0005[מי שחייב]\u0006"],["\u0003חמש אשמות תלויין\u0004 על חמישה מקרים של ספק חטאת, \u0003כי מייתי חד מי מיפטר\u0004 \u0005[כאשר\u0006 הוא \u0005מביא אחד האם הוא נפטר]\u0006 מלהביא את האחרים? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003זה הכלל: כל שחלוקין בחטאות,\u0004 שצריך להביא חטאת על כל אכילה ואכילה כשנודע לו שחטא — \u0003חלוקין באשמות\u0004 תלויים, כאשר יש ספק אם חטא!","\u0003אלא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לטבילות מדמי להון\u0004 \u0005[מדמים אותם]\u0006 את חטאות היולדת או הזבה, ומעיקר הדין די שתאמר: על אחת מהן אני מביאה. \u0003ובחוששין לפשיעה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003רבי יוחנן בן נורי\u0004 שלדעתו צריכה לומר: על האחרונה אני מביאה, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לפשיעה,\u0004 שאם תאמר: על אחת מהן אני מביאה, ותיפטר, כשתלד בשנה הבאה תהא סבורה שאין צורך להביא קרבן על כל לידה, ותפשע ולא תביא. אבל כשמחייבים אותה לומר שהיא מביאה על האחרונה הרי זה מלמד שכולן הוצרכו לכפרה. \u0003ורבי עקיבא\u0004 שלדעתו די שתאמר: על אחת מהן אני מביאה, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 \u0003לפשיעה.\u0004","","\u0003ארבעה מחוסרי כפרה,\u0004 שצריכים קרבן לגמר טהרתם, כדי להתירם לאכול מבשר הקדשים, \u0003וארבעה מביאין\u0004 קרבן \u0003על הזדו‍ן כשוגג.\u0004","\u0003ואלו הן מחוסרי כפרה: הזב, והזבה, והיולדת, והמצורע.\u0004","\u0003רבי אליעזר בן יעקב אומר: גר\u0004 גם הוא \u0003מחוסר כפרה,\u0004 ואינו אוכל בקדשים למרות שמל וטבל לשם גירות, \u0003עד שיזרוק\u0004 הכהן \u0003עליו\u0004 (עבורו) את \u0003הדם\u0004 של קרבנו על המזבח. \u0003נזיר\u0004 מחוסר כפרה — \u0003ליינו ותגלחתו וטומאתו,\u0004 שאסור לשתות יין ולהתגלח ולהיטמא למתים, עד שיביא קרבנותיו.","שנינו שארבעה מחוסרי כפרה הם: זב וזבה, יולדת ומצורע. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003זב וזבה דמני להון בתרין\u0004 \u0005[שמונה אותם\u0006 התנא \u0005בשנים]\u0006 — \u0003משום\u0004 ש\u0003חלוקה טומאתו,\u0004 ש\u0003זב לא מטמא\u0004 אם ראה זוב \u0003באונס,\u0004 מחמת סיבה חיצונית, כגון חולי או אכילת מאכלים מסויימים, \u0003וזבה לא מטמאה ב\u0004רצף של שלוש \u0003ראיות\u0004 ביום אחד \u0003כ\u0004פי שהיא נטמאת \u0003בימים,\u0004 אם ראתה שלושה ימים רצופים. ומנין שזב אינו מיטמא באונס?","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"איש איש כי יהיה זב מבשרו\" (ויקרא טו, ב), ויש לדייק: \u0003\"מבשרו\",\u0004 כלומר מחמת עצמו, \u0003ולא מחמת אונסו. ו\u0004כן הזב \u0003מיטמא בראיות כבימים\u0004 — כמו \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]: תלה הכתוב את הזכר בראיות ואת הנקבה בימים. ו\u0006לעומתו \u0003זבה מטמאה\u0004 גם \u0003באונס, ולא מטמאה בראיות כבימים;\u0004 והלוא","\u0003מצורע ומצורעת נמי\u0004 \u0005[גם כן]\u0006 \u0003חלוקה טומאתן,\u0004 ש\u0003מצורע טעון פריעה ופרימה, דכתיב\u0004 \u0005[שנאמר]: \"\u0006\u0003בגדיו יהיו פרמים וראשו יהיה פרוע\"\u0004 (שם יג, מה), \u0003ואסור בתשמיש המטה, ו\u0004אילו \u0003מצורעת אינה טעונה פריעה ופרימה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"איש צרוע הוא\" (שם מד) \u0003אין לי אלא איש\u0004 שחלים עליו דיני הצרעת, \u0003אשה מנין? כשהוא אומר\u0004 מיד לאחר מכן שוב: \u0003\"והצרוע\u0004 אשר בו הנגע\" (שם מה), ו\"צרוע\" הוא לשון סתמית — \u0003הרי כאן שנים,\u0004 כלומר, לא רק איש אלא גם אשה.","","\u0003אם כן מה תלמוד לומר\u0004 מתחילה \u0003\"איש\",\u0004 ולא אשה? \u0003נתקו\u0004 (העביר אותו) \u0003הכתוב מענין של מעלה לענין של מטה,\u0004 להמשך הכתוב: \"בגדיו יהיו פרומים וראשו יהיה פרוע\", \u0003לומר: איש פורע ופורם ואין האשה פורעת ופורמת. ו\u0004כן מצורעת \u0003מותרת בתשמיש המטה, שנאמר: \"וישב מחוץ לאהלו שבעת ימים\"\u0004 (שם יד, ח) \u0003ולא מחוץ לאהלה.\u0004","\u0003הלכך נמנינהו בתרין\u0004 \u0005[אם כך נמנה אותם,\u0006 מצורע ומצורעת, גם כן \u0005בשניים],\u0006 כמו זב וזבה! ומשיבים: \u0003זב וזבה עיקר טומאתן חלוקה,\u0004 זב בראיות וזבה בימים, הזב במראה לובן (כעין שכבת זרע) והזבה בדם, אבל \u0003מצורע ומצורעת אין עיקר טומאתן חלוקה, האי והאי\u0004 \u0005[זה וזה]\u0006 שיעור הנגע שבהם \u0003כגריס\u0004 של פול \u0003הוא\u0004. שנינו במשנה, \u0003רבי אליעזר בן יעקב אומר: גר מחוסר\u0004 כפרה ו\u0003כו'.\u0004 ושואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 \u0003מאי טעמא לא תני\u0004 \u0005[מה טעם אינו שונה]\u0006 \u0003גר?\u0004 ומשיבים: \u0003כי קתני מדעם דמישרי למיכל\u0004 \u0005[כאשר הוא שונה\u0006 הרי זה \u0005דבר שמתיר לאכול]\u0006 \u0003בקדשים,\u0004 אבל \u0003גר כי קא מייתי\u0004 \u0005[כאשר הוא מביא]\u0006 \u0003קרבן\u0004 הרי זה כדי \u0003לאכשורי נפשיה למיעל\u0004 \u0005[להכשיר אותו לבוא]\u0006 \u0003בקהל\u0004 ישראל.","","ושואלים: \u0003ונזיר מאי טעמא לא תני\u0004 \u0005[מה טעם לא שנה]\u0006 אותו התנא ברשימת מחוסרי הכפרה? ומשיבים: \u0003סוף סוף נזיר נמי כי מייתי\u0004 \u0005[גם כן כאשר מביא]\u0006 \u0003קרבן\u0004 — \u0003לאישתרויי למישתי\u0004 \u0005[להתירו לשתות]\u0006 \u0003יין\u0004 של \u0003חולין הוא,\u0004 ולא כדי להתירו באכילת קדשים. ושואלים: \u0003ורבי אליעזר\u0004 בן יעקב, \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 \u0003נזיר\u0004 מפני שקרבנו בא \u0003למישרי נפשיה\u0004 \u0005[להתיר אותו]\u0006 בשתיית יין, \u0003ניתני נמי\u0004 \u0005[שישנה גם כן]\u0006 \u0003נזיר טמא!\u0004 ומשיבים: נזיר טהור קרבנו מתירו בדבר_מה, ולכן הוא נחשב מחוסר כפרה. אבל נזיר טמא \u0003כי קא מייתי\u0004 \u0005[כאשר הוא מביא]\u0006 \u0003קרבן,\u0004 אין זה כדי להתירו בדבר, אלא \u0003למיחל עליה\u0004 \u0005[להחיל עליו]\u0006 \u0003נזירות בטהרה הוא\u0004 בא.","","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גר מעוכב לאכול בקדשים עד שיביא קינו,\u0004 שני תורים או שני בני יונה, \u0003הביא פרידה\u0004 (עוף) \u0003אחת שחרית\u0004 — \u0003אוכל בקדשים לערב,\u0004 ויכול להביא את האחרת לאחר זמן. \u0003כל הקינין שבתורה אחד חטאת ואחד עולה, כאן\u0004 בגר — \u0003שתיהן עולות.\u0004","\u0003הביא חובתו מן הבהמה,\u0004 בהמה אחת לעולה — \u0003יצא,\u0004 וכן אם הביא \u0003עולה ושלמים\u0004 — \u0003יצא,\u0004 אבל אם הביא \u0003מנחה ושלמים\u0004 — \u0003לא יצא.\u0004 וטעם הדבר שיוצא בקרבן בהמה, שכן \u0003לא אמרו\u0004 שיביא \u0003קן אלא להקל\u0004 עליו.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003מנחה ושלמים\u0004 ש\u0003לא יצא\u0004 — מפני \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"וכי יגור אתכם גר וכו' ועשה ריח ניחוח לה' \u0003כאשר תעשו כן יעשה\"\u0004 (במדבר טו, יד), \u0003מה אתם\u0004 כשנכנסתם לברית בהר סיני, הקרבתם \u0003עולה ושלמים,\u0004 שנאמר: \"ויעלו עולות ויזבחו זבחים שלמים\" (שמות כד, ה) — \u0003אף גר\u0004 יביא \u0003עולה ושלמים;\u0004 \u0003אם כן,\u0004 אם הביא \u0003חובתו אחת מן הבהמה\u0004 גם כן \u0003לא תיסגי עליה בגוויה\u0004 \u0005[לא יהיה די בכך],\u0006 \u0003דהכתיב\u0004 \u0005[שהרי נאמר]: \"\u0006\u0003כאשר תעשו כן יעשה\",\u0004 עולה ושלמים! \u0003אמר רב פפא, יש לומר:\u0004 קל וחומר הוא, אם \u0003ל\u0004קרבן מן ה\u0003עוף איתרבי\u0004 \u0005[התרבה]\u0006 הגר בכתוב, \u0003לעולת בהמה לא כל שכן?\u0004","","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שלמדנו מריבוי הכתוב, \u0003אפילו מנחה נמי\u0004 \u0005[גם כן]\u0006 יביא! ומשיבים, \u0003מיעט קרא\u0004 \u0005[הכתוב],\u0006 שנאמר \u0003\"כן\u0004 יעשה\", ולא פחות.","ואומרים: \u0003ועוף היכא איתרבי\u0004 \u0005[היכן נתרבה]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]: \"\u0006\u0003כאשר תעשו כן יעשה\", מה אתם\u0004 נכנסתם לברית ב\u0003עולה ושלמים\u0004 — \u0003אף הוא\u0004 הגר \u0003עולה ושלמים, שנאמר: \"ככם כגר\"\u0004 (שם); \u0003מנין לרבות את העוף? תלמוד לומר: \"אשה ריח ניחח לה'\"\u0004 (שם), \u0003איזה דבר שכולו לה'? הוי אומר עולת העוף.\u0004"],["\u0003יכול שאני מרבה אפילו מנחה,\u0004 שמקריב אותה כליל? \u0003תלמוד לומר: \"כן\u0004 יעשה\", למעט מנחה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 על פסוק זה: וכי יגור אתכם גר וכו' \u0003יעשה אשה ריח ניחח לה'\"\u0004(במדבר טו, יד), \u0003שומע אני כל שעולה לאשים\u0004 (על אש המזבח) \u0003אפילו מנחה? תלמוד לומר: \"כאשר תעשו כן יעשה\"\u0004 (שם), \u0003מה אתם\u0004 הבאתם קרבנות של \u0003מיני דמים\u0004 כשנכנסתם לברית בהר סיני, שנאמר \"ויעלו עולות ויזבחו זבחים שלמים\" (שמות כד, ה), \u0003אף הם\u0004 הגרים מביאים \u0003מיני דמים.\u0004","ויש לשאול: \u0003אי,\u0004 אם לדרך זו, נאמר: \u0003מה אתם\u0004 הקרבתם \u0003עולה ושלמים, אף הם עולה ו\u0004גם \u0003שלמים! תלמוד לומר\u0004 בפסוק לאחר מכן: \u0003\"ככם כגר יהיה\"\u0004 (במדבר טו, טו), ויש כאן הדגשה: \u0003לכם הקשתיו,\u0004 שהייתם צריכים למיני דמים כדי להיכנס לברית, \u0003ולא לדבר אחר,\u0004 כלומר \u0003ל\u0004כל \u0003קרבנותיכם.\u0004","\u0003רבי אומר:\u0004 מכאן למדים דינו של קרבן הגר, שמה שנאמר: \u0003\"ככם\u0004 כגר\" (שם) כוונתו — \u0003כאבותיכם, מה אבותיכם לא נכנסו לברית אלא במילה וטבילה והרצאת\u0004 (זריקת) \u0003דם\u0004 קרבן על המזבח — \u0003אף הם לא יכנסו לברית אלא במילה וטבילה והרצאת דמים\u0004 כל שהיא.","ולפי זה די לכאורה בקרבן אחד של עוף, ואולם \u0003להביא פרידה אחת\u0004 כלומר, רק עוף אחד — \u0003אי אפשר, שלא מצינו בכל התורה כולה\u0004 קרבן של עוף אחד, ולכן צריך להביא קן של שני עופות. ומכל מקום יכול להביא בהמה אחת לעולה, שכן \u0003לא אמרו\u0004 שיביא \u0003קן אלא להקל עליו.\u0004","ושואלים: \u0003ולא\u0004 מצאנו קרבן של פרידה אחת? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בעולת העוף \u0003\"והקריבו\u0004 הכהן\" (ויקרא א, טו) \u0003מה תלמוד לומר? לפי ש\u0004בפסוק הקודם \u0003נאמר בתורים: \"והקריב\u0004 מן התורים\" (שם יד), בלשון רבים, \u0003שומע אני\u0004 ש\u0003האומר \"הרי עלי עולת העוף\"\u0004 — \u0003לא יפחות משני פרידין?\u0004 על כן \u0003תלמוד לומר: \"והקריבו\"\u0004 בלשון יחיד — שיכול אדם להתנדב \u0003אפילו פרידה אחת!\u0004 ומשיבים: קרבן \u0003חובה,\u0004 כמו קרבנו של הגר, \u0003מיהא לא אשכחן\u0004 \u0005[על כל פנים לא מצאנו]\u0006 שמביא רק פרידה אחת.","ומקשים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003יולדת, דמתיא\u0004 \u0005[שמביאה]\u0006 \u0003בן יונה או תור לחטאת\u0004 (שם יב, ו)! ומשיבים: אין מכאן קושיה, \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003כבש בהדה\u0004 \u0005[יחד איתה].\u0006 ושבים לדון בעיקר דברי רבי.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מה אבותיכם לא נכנסו לברית אלא\u0004 במילה וטבילה והרצאת דם. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מילה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]: \"\u0006\u0003כי מלים היו כל העם היצאים\u0004 (ממצרים)\" (יהושע ה, ה), \u0003אי נמי מהכא\u0004 \u0005[או גם כן\u0006 ראיה מכאן]: שנאמר בתיאור גאולת מצרים \u0003\"ואעבר עליך ואראך מתבוססת בדמיך ואמר לך בדמיך חיי\"\u0004 (יחזקאל טז, ו), ודרשו חכמים \"דמיך\" — דם פסח ודם מילה.","וכן \u0003הרצאת דמים\u0004 היתה שם — \u0003דכתיב\u0004 \u0005[שנאמר]: \"\u0006\u0003וישלח את נערי בני ישראל\u0004 ויעלו עולות ויזבחו זבחים שלמים\" (שמות כד, ה), \u0003אלא טבילה מנלן\u0004 \u0005[מנין לנו]\u0006 שהיתה בהר סיני? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]: \"\u0006\u0003ויקח משה חצי הדם ויזרק על העם\"\u0004 (ראה שם ו—ח), \u0003ואין הזאה בלא טבילה.\u0004","ושואלים: \u0003אלא מעתה,\u0004 שמדין תורה צריך להיכנס לברית בשלושה דברים אלה, \u0003האידנא דליכא\u0004 \u0005[עכשיו,\u0006 בזמן הזה, \u0005שאין]\u0006 \u0003קרבן לא נקבל גרים! אמר רב אחא בר יעקב:\u0004 נאמר \u0003\"וכי יגור אתכם גר\u0004 או \u0003אשר בתוככם\u0004 לדורותיכם\" (במדבר טו, יד), ומכאן שיש גר גם כשאין מקדש.","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גר בזמן הזה צריך שיפריש רובע\u0004 דינר \u0003לקינו,\u0004 שכשייבנה המקדש יקנה קרבן בכסף זה. \u0003אמר ר' שמעון: כבר נמנה עליו רבן יוחנן בן זכאי\u0004 על הלכה זו, העמיד אותה להכרעה של חכמים, \u0003ובטלה, מפני התקלה,\u0004 שלא ישתמשו בכסף זה לחולין. \u0003אמר רב אידי בר גרשום אמר רב אדא בר אהבה: הלכה כר' שמעון,\u0004 שגר אינו מפריש רובע לקינו.","\u0003ואיכא דמתני לה על הדא\u0004 \u0005[ויש ששונים אותה,\u0006 את הלכה זו של רב אדא, \u0005על זו],\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003גר תושב,\u0004 גוי היושב עמנו, שקיבל על עצמו שלא לעבוד עבודה זרה, \u0003מותר לעשות מלאכה בשבת ל\u0004צורך \u0003עצמו, כישראל\u0004 שעושה מלאכה \u0003בחולו של מועד,\u0004 לצורך דבר האבד.","\u0003ר' עקיבא אומר:\u0004 גר תושב עושה מלאכה בשבת \u0003כישראל ביום טוב,\u0004 כלומר, רק צרכי אוכל נפש. ר' \u0003יוסי אומר: גר תושב עושה בשבת לעצמו כ\u0004פי ש\u0003ישראל\u0004 עושה \u0003בחול. ר' שמעון אומר: אחד גר תושב, ואחד עבד ואמה התושבים, עושין מלאכה בשבת לעצמן כישראל בחול.\u0004 ועל כך אמר רב אידי בר גרשום בשם רב אדא בר אהבה שהלכה כר' שמעון.","\u0003אלו מביאין\u0004 קרבן \u0003על הזדון כשוגג: הבא על שפחה\u0004 חרופה, שצריך להביא קרבן אשם (ראה ויקרא יט, כ—כב), \u0003ונזיר שנטמא\u0004 שצריך להביא כבש לאשם ושני תורים או שני בני יונה, אחד לחטאת ואחד לעולה (ראה במדבר ו, ט—יב), \u0003ו\u0004על \u0003שבועת העדות,\u0004 שנשבע לשקר שאינו יודע עדות לחבירו, וצריך להביא קרבן (ויקרא ה, א), \u0003ו\u0004על \u0003שבועת הפקדון\u0004 שנשבע לשקר שחפץ של חבירו אינו בידו, וצריך להביא אשם (שם כא—כו).","\u0003חמשה מביאין קרבן אחד על עבירות הרבה,\u0004 שלמרות שעברו אותה עבירה פעמים אחדות, מביאים רק קרבן אחד, \u0003וחמשה מביאין קרבן עולה ויורד,\u0004 המשתנה לפי מצבו הכלכלי של החייב. \u0003אלו מביאין קרבן אחד על עבירות הרבה: הבא על שפחה ביאות הרבה, ונזיר שנטמא טומאות הרבה.\u0004","שנינו במשנה: אלו מביאין על הזדון כשוגג וכו'. ומבררים: \u0003הבא על השפחה, מנלן\u0004 \u0005[מנין לנו]?\u0006","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]: \"\u0006\u0003וכפר עליו הכהן באיל האשם\u0004 לפני ה' \u0003על חטאתו אשר חטא\"\u0004 (ויקרא יט, כב), כפל הלשון \"חטאתו אשר חטא\" \u0003מלמד שמביא קרבן אחד על עבירות הרבה,\u0004 ומה שנאמר שם: \u0003\"באיל האשם... ונסלח לו מחטאתו אשר חטא\"\u0004 בכפל לשון, בא \u0003לעשות שוגג כמזיד,\u0004 שגם כך וגם כך חייב בקרבן.","ועוד מבררים: ה\u0003נזיר שנטמא מנלן\u0004 \u0005[מנין לנו]\u0006 שמביא על הזדון כשוגג?","\u0003דכתיב\u0004 \u0005[שנאמר]: \"\u0006\u0003וכי ימות מת עליו בפתע פתאם\"\u0004 (במדבר ו, ט), \"\u0003פתע\"\u0004 — \u0003זה שוגג, וכן הוא אומר: \"אם בפתע בלא איבה הדפו\"\u0004 (שם לה, כב); \u0003\"פתאם\"\u0004 — \u0003זה אונס, וכן הוא אומר: \"ויאמר ה' פתאם אל משה\u0004 ואל אהרן ואל מרים צאו שלשתכם\" (שם יב, ד), בעל כרחם.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]: \"\u0006\u0003פתאם\"\u0004 — \u0003זה מזיד, וכן הוא אומר: \"ערום ראה רעה ונסתר ופתאים עברו ונענשו\"\u0004 (משלי כב, ג), ומפרשים \"פתאים\" מלשון \"פתאום\". והרי אין אדם נענש (\"עברו ונענשו\") אלא אם היה מזיד.","ושואלים: אם כן, \u0003נכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 בענין נזיר \u0003\"פתאם\", דמשמע\u0004 \u0005[שמשמעו]\u0006 שנטמא \u0003שוגג, ומשמע מזיד, ומשמע אונס; מזיד ואונס\u0004 — \u0003כדאמר\u0004 \u0005[כמו שנאמר\u0006 לעיל\u0005],\u0006 \u0003ומשמע נמי\u0004 \u0005[ומשמעו גם כן]\u0006 \u0003שוגג\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006\u0003: \"פתי יאמין לכל דבר\"\u0004 (שם יד, טו), כלומר טועה, והוא השוגג; \u0003ולא נכתוב קרא\u0004 \u0005[ושלא יכתוב המקרא]\u0006 כלל את המילה \u0003\"פתע\"!\u0004","ומשיבים: \u0003אי כתב קרא\u0004 \u0005[אם היה כותב המקרא]\u0006 רק \u0003\"פתאם\",\u0004 ש\u0003משמע\u0004 לפעמים \u0003שוגג, ומשמע מזיד, ומשמע\u0004 גם \u0003אונס, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 נזיר \u0003כי מייתי\u0004 \u0005[כאשר מביא]\u0006 \u0003קרבן\u0004 — \u0003בשוגג\u0004 הוא מביא, \u0003מידי דהוי אתורה\u0004 \u0005[כמו שהוא\u0006 הדין \u0005בכל התורה]\u0006 \u0003כולה,\u0004 שמביא קרבן רק על השוגג, \u0003אבל אונס ומזיד אימא\u0004 \u0005[אמור]\u0006 שלא יתחייב, לכך","\u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"פתע\"\u0004 ששוגג \u0003הוא, לגלויי עליה\u0004 \u0005[לגלות על]\u0006 \u0003\"פתאם\"\u0004 האמור שם ש\u0003אונס ומזיד הוא,\u0004 לומר \u0003דאפילו הכי חייב רחמנא\u0004 \u0005[שאפילו כך חייבה התורה]\u0006 להביא קרבן.","ועוד מבררים: מה ששנינו במשנה ש\u0003שבועת העדות\u0004 מביא עליה קרבן בין אם נשבע בשוגג ובין במזיד, \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003בכולן,\u0004 בכל אלו השנויים באותה פרשה (ויקרא ה, ב—ד) שמביא עליהם קרבן עולה ויורד, כגון על טומאת קדשים ועל שבועת ביטוי, \u0003נאמר \"ונעלם\u0004 ממנו\", ואילו \u0003כאן,\u0004 בשבועת העדות (שם א) \u0003לא נאמר \"ונעלם\",\u0004 הרי זה בא \u0003לחייב\u0004 בעניינה \u0003על השוגג כמזיד.\u0004","ועל מה ששנינו: \u0003שבועת הפקדון\u0004 מביא על המזיד כשוגג, מבארים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003יליף\u0004 \u0005[לומד הוא]\u0006 בגזירה שווה \"\u0003תחטא\" \"תחטא\" משבועת העדות,\u0004 שבשבועת העדות נאמר \"נפש כי תחטא\" (שם), וכן בשבועת הפקדון (שם כא).","שנינו במשנה: \u0003חמשה מביאין קרבן אחד על עבירות הרבה,\u0004 ובתוכם \u0003קתני\u0004 \u0005[הוא שונה]:\u0006 \u0003הבא על השפחה ביאות הרבה.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה?","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006\u0003: \"וכפר עליו הכהן באיל האשם על חטאתו אשר חטא\"\u0004 (ויקרא יט, כב) — כפל הלשון \"חטאתו אשר חטא\" \u0003מלמד שמביא קרבן אחד על עבירות הרבה,\u0004 ומה שנאמר: \u0003\"באיל האשם... ונסלח לו מחטאתו אשר חטא\"\u0004 — מלמד על שני סוגי חטא, \u0003לעשות מזיד כשוגג.\u0004","ומקשים: \u0003והא קרא כי כתיב\u0004 \u0005[והרי המקרא כאשר הוא כתוב]\u0006 \u0003במזיד כתיב\u0004 \u0005[\u0006הוא \u0005כתוב]\u0006 שנאמר שם \"בקורת תהיה\", וכוונתו לעונש מלקות, והרי אין לוקים אלא על המזיד! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 להיפך: \u0003לעשות שוגג כמזיד.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006\u0003 ר' חנינא טירנאה מר' יוחנן: הבא על חמש שפחות חרופות בהעלם אחת,\u0004 שלא נודע לו בינתיים האיסור שבדבר, \u0003מהו?\u0004 האם \u0003חייב על כל אחת ואחת\u0004 קרבן, \u0003או אינו חייב אלא אחת? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003חייב על כל אחת ואחת.\u0004","שאל אותו ר' חנינא: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 מקרה זה \u0003מחמש העלמות בשפחה אחת,\u0004 שמביא רק קרבן אחד, כפי ששנינו במשנתנו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אין שפחה אחת גופין מוחלקין,\u0004 אלא גוף אחד הוא, ולכן נחשב זה לעבירה אחת לענין קרבן, ואילו \u0003חמש שפחות גופין מוחלקין\u0004 הן.","שאל אותו ר' חנינא: \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 \u0003דגבי\u0004 \u0005[שאצל]\u0006 \u0003שפחה\u0004 יש משמעות לגופין \u0003מוחלקין? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003לאו אמרת גבי\u0004 \u0005[האם אין אתה אומר אצל]\u0006 \u0003עריות\u0004 שהביטוי \u0003\"ו\u0004 אל \u0003אשה\"\u0004 (שם יח, יט) בא \u0003לחלק\u0004 איסור וחיוב חטאת \u0003על כל אשה ואשה? גבי\u0004 \u0005[אצל]\u0006 \u0003שפחה נמי כתיב\u0004 \u0005[גם כן נאמר]: \"\u0006\u0003אשר ישכב את אשה שכבת זרע\u0004"],["\u0003והיא שפחה\"\u0004 (ויקרא יט, כ), לשון \"והיא שפחה\" מלמדת \u0003לחלק על כל שפחה ושפחה.\u0004","שנינו במשנה כי \u0003נזיר שנטמא טומאות הרבה\u0004 (פעמים רבות) מביא קרבן אחד. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן?","\u0003אמר רב חסדא:\u0004 שיטת ר' \u0003יוסי בר' יהודה היא,\u0004 שאמר: \u0003נזירות\u0004 חדשה של \u0003טהרה\u0004 — \u0003מ\u0004יום ה\u0003שביעי\u0004 של טהרתו \u0003הוא דחיילא עליה\u0004 \u0005[שחלה עליו].\u0006 \u0003ומשכחת לה\u0004 \u0005[ו\u0006לפיכך \u0005מוצא אתה אותה]\u0006 שנטמא טומאות הרבה, כלומר, שחלה עליו נזירות ונטמא, ושוב חלה עליו נזירות ונטמא — \u0003כגון שנטמא ב\u0004יום ה\u0003שביעי\u0004 לטהרתו, ונטהר שבעה ימים, \u0003וחזר ונטמא בשביעי, וכיון\u0004 שבכל פעם שחזר ונטמא עדיין \u0003לא יצא שעה הראויה להקריב בה קרבן,\u0004 שהוא היום השמיני לטהרתו — \u0003אינו חייב אלא קרבן אחד.\u0004","\u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003רבי, כיון\u0004 ש\u0003אמר רבי: נזירות\u0004 של \u0003טהרה עד שמיני לא חיילא עליה\u0004 \u0005[חלה עליו],\u0006 לא ייתכן שיביא קרבן אחד על טומאות הרבה, שהרי \u0003אי\u0004 \u0005[אם]\u0006 במקרה ש\u0003נטמא בשביעי\u0004 ונטהר \u0003וחזר ונטמא בשביעי\u0004 לטהרתו — \u0003כולה טומאה אריכתא\u0004 \u0005[ארוכה]\u0006 \u0003היא,\u0004 שלא יצא עדיין מטומאתו הראשונה;","\u0003אי\u0004 \u0005[אם]\u0006 במקרה שנטמא \u0003בשמיני\u0004 ונטהר \u0003וחזר ונטמא בשמיני\u0004 לטהרתו השניה, \u0003כיון\u0004 שיצאת \u0003שעה שראוייה להקריב\u0004 בה \u0003קרבן\u0004 — \u0003מחייב\u0004 \u0005[חייב]\u0006 \u0003על כל אחת ואחת! אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ששיטת ר' \u0003יוסי בר' יהודה\u0004 היא.","\u0003ומאי\u0004 \u0005[ומה היא]\u0006 שאמר \u0003ר' יוסי בר' יהודה? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בנזיר שנטמא ונטהר \u0003\"וקדש את ראשו ביום ההוא\"\u0004 (במדבר ו, יא), שמתחיל למנות נזירותו מחדש — הרי זה \u0003ביום הבאת קרבנותיו,\u0004 היום השמיני, \u0003דברי רבי.\u0004","\u0003ר' יוסי בר' יהודה אומר: ביום תגלחתו,\u0004 שהוא היום השביעי.","ועוד ברשימת המביאים קרבן אחד על עבירות הרבה: \u0003המקנא לאשתו על ידי אנשים הרבה,\u0004 שאם אמר לה שלא תיסתר עם פלוני ועם פלוני, ונסתרה עמהם, כשנבדקת במים המאררים — מביא מנחת סוטה אחת על כולם. \u0003ו\u0004כן \u0003מצורע שנתנגע נגעים הרבה,\u0004 שהיה בו נגע צרעת ונטהר, וקודם שהביא קרבנותיו חזר ונצטרע.","\u0003הביא\u0004 שתי \u0003ציפרין\u0004 ביום הראשון לטהרתו (ויקרא יד, ד—ז), \u0003ו\u0004קודם שהביא קרבנותיו ביום השמיני \u0003נתנגע\u0004 שוב — \u0003לא עלו לו\u0004 הציפורים הללו \u0003עד שיביא חטאתו, ר' יהודה אומר: עד שיביא אשמו.\u0004","שנינו במשנה שהמקנא לאשתו על יד אנשים הרבה מביא קרבן אחד. ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דין זה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006\u0003: \"זאת תורת הקנאת\"\u0004 (במדבר ה, כט), בלשון רבים — \u0003תורה אחת לקנויין הרבה.\u0004","שנינו: \u0003מצורע שנתנגע נגעים הרבה\u0004 מביא קרבן אחד. ומבררים, \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת\u0004 תהיה \u0003תורת המצורע\"\u0004 (ויקרא יד, ב), לומר: \u0003תורה אחת למצורעים הרבה,\u0004 כלומר, גם למי שנצטרע פעמים הרבה.","שנינו: \u0003הביא ציפרין ונתנגע\u0004 — \u0003לא עלו לו עד שיביא חטאתו, ר' יהודה אומר: עד שיביא אשמו,\u0004 והניסוח \"לא עלו לו\" משמעו שאם חזר ונתנגע קודם שהביא חטאתו, לכשיירפא מצרעתו צריך לחזור ולהביא ציפורים נוספות גם על הפעם הראשונה.","ומקשים, \u0003והאמרת\u0004 \u0005[והרי אמרת]:\u0006 \u0003אין מביא אלא קרבן אחד\u0004 על נגעים הרבה! ומתרצים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך היא שנויה]:\u0006 מצורע שנתנגע נגעים הרבה, כגון \u0003הביא ציפרין\u0004 וחזר \u0003ונתנגע\u0004 — \u0003אין מביא אלא קרבן אחד. ו\u0004כן \u0003לאקבועי\u0004 \u0005[להיקבע]\u0006 דינו של המצורע \u0003בעניות ובעשירות,\u0004 האם עליו להביא קרבן עני או קרבן עשיר (ראה ויקרא פרק יד) — \u0003לא מיקבע\u0004 \u0005[אינו נקבע],\u0006 \u0005עד שיביא חטאת, ואילו\u0006 \u0003ר' יהודה אומר:\u0004 אינו נקבע כעני או עשיר \u0003עד שיביא אשמו.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 משנה אחרת: \u0003מצורע שהביא אשמו והעשיר\u0004 — \u0003הכל הולך אחר\u0004 זמן הקרבת ה\u0003חטאת,\u0004 שזהו הזמן שבו נקבעת העניות ועשירות, \u0003דברי ר' שמעון. ר' יהודה אומר: הכל הולך אחר אשם. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006\u0003, ר' אליעזר בן יעקב אומר: הכל הולך אחר ציפרין.\u0004","\u0003אמר רב יהודה אמר רב: שלשתן מקרא אחד דרשו, שנאמר בענין זה: \"וזאת תורת אשר בו נגע צרעת אשר לא תשיג ידו בטהרתו\"\u0004 (ויקרא יד, לב) — ר' \u0003שמעון סבר\u0004 \u0005[סבור]:\u0006 הכוונה היא ל\u0003דבר המכפרו,\u0004 והיא החטאת, \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 הכוונה היא ל\u0003דבר המכשירו,\u0004 באכילת קדשים, והוא האשם. \u0003ר' אליעזר בן יעקב אומר: דבר הגורם לו טהרה, ומאי נינהו\u0004 \u0005[ומה הם]?\u0006 \u0003ציפרין.\u0004","בין אלו המביאים קרבן אחד על טומאות הרבה, \u0003האשה שילדה ולדות הרבה,\u0004 וכגון שילדה בת, שצריכה למנות ארבעה עשר ימי טומאה, ושישים וששה ימי טהרה, ובמלאת שמונים הימים צריכה להביא קרבן. \u0003והפילה בתוך\u0004 אותם \u0003שמונים\u0004 יום \u0003נקבה,\u0004 ושוב \u0003חזרה והפילה בתוך שמונים\u0004 להפלה \u0003נקבה,\u0004 שאינה מתחייבת בקרבן עד לאחר מלאת ימי הטהרה של הלידה האחרונה, ובמלאת ימים אלה תביא קרבן אחד על כולן.","\u0003ו\u0004כן \u0003המפלת תאומים\u0004 וכגון שנתעברה שלושה עוברים, והפילה את השני בתוך מלאת של הראשון, ואת השלישי בתוך מלאת של השני — מביאה קרבן אחד על כולם.","\u0003ר' יהודה אומר: מביאה\u0004 קרבן \u0003על\u0004 הוולד \u0003הראשון ואינה מביאה על\u0004 הלידה \u0003השניה,\u0004 שהיתה לפני מלאת ימי הטהרה של הוולד הראשון. \u0003מביאה על השלישי,\u0004 שנולד לאחר מלאת ימי טהרה של הלידה הראשונה, \u0003ואינה מביאה על הרביעי,\u0004 שנולד לפני מלאת ימי הטהרה של הוולד השלישי.","שנינו במשנה כי האשה שילדה ולדות הרבה מביאה קרבן אחד. ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתני תנא קמיה\u0004 \u0005[ששנה חוזר המשניות לפני]\u0006 \u0003רב ששת: \"זאת תורת הילדת לזכר ולנקבה\"\u0004 (שם יב, ז) — \u0003מלמד שמביאה קרבן אחד על ולדות הרבה. יכול\u0004 תביא קרבן אחד \u0003אף על הלידה ועל הזיבה? תלמוד לומר: \"זאת\",\u0004 למעט.","ותמהים, \u0003קתני\u0004 \u0005[הרי הוא שונה]:\u0006 \u0003יכול על הלידה ועל הזיבה אינה מביאה אלא קרבן אחד; אלא מעתה, אכלה דם\u0004 בשוגג ונתחייבה חטאת, \u0003ו\u0004גם \u0003ילדה, הכי נמי\u0004 \u0005[כך גם כן]\u0006 היינו אומרים ש\u0003אין מביאה אלא קרבן אחד?\u0004 הלוא לידה וזיבה שני דברים שונים הם!","ומשיבים, \u0003אימא הכי\u0004 \u0005[אמור כך]:\u0006 \u0003יכול\u0004 תביא קרבן אחד \u0003על הלידה שלפני מלאת,\u0004 כלומר, על לידתה הראשונה, \u0003ועל הלידה שלאחר מלאת? תלמוד לומר: \"זאת\".\u0004","שנינו במשנה: \u0003הפילה בתוך שמונים\u0004 נקבה וחזרה והפילה בתוך שמונים נקבה, מביאה קרבן אחד על כולן. ר' יהודה אומר: מביאה על הראשון, ואינה מביאה על השני (שנולד לפני מלאת ימי טהרת הלידה הראשונה), מביאה על השלישי שנולד לאחר מלאת של הראשונה, ואינה מביאה על הרביעי שנולד לפני מלאת של השלישי. ואומרים: \u0003כשתמצי לומר,\u0004 כשתדקדק ותגיע למיצוי הדברים, \u0003לדברי ר' יהודה\u0004 — \u0003ולד ראשון גורם\u0004 לקרבן, \u0003ומ\u0004לידת \u0003ולד ראשון\u0004 היא מ\u0003ונה\u0004 שמונים יום, והנולד לאחר מכן טעון קרבן נפרד. \u0003לדברי חכמים\u0004 — \u0003ולד שני\u0004 (כלומר, האחרון) \u0003גורם\u0004 לחיוב הקרבן, \u0003ומולד שני מונה\u0004 שמונים יום.","ותוהים: \u0003כשתמצי לומר? פשיטא\u0004 \u0005[פשוט הוא],\u0006 \u0003הכי איתא\u0004 \u0005[כך הוא\u0006 מפורש\u0005]!\u0006 ומשיבים: \u0003מפלת תאומים איצטריך ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שבמפלת \u0003תאומים מודה רבי יהודה לרבנן\u0004 \u0005[לחכמים],\u0006 שכיון שעיבורם בזמן אחד הוא, יש לראות את הכל כלידה אחת, וללכת אחר לידת האחרון, שהיא נחשבת סוף הלידה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמונה מן הלידה הראשונה, והנולד לאחר מלאת ימי הראשון מחייב קרבן נוסף.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם ללומדים]:\u0006"],["\u0003בטומאה מה לי אמר ר' יהודה?\u0004 מה סבור הוא? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003עד כאן לא קאמר ליה\u0004 \u0005[אומר לו]\u0006 \u0003ר' יהודה\u0004 ש\u0003ולד שני כמאן דליתיה דמי\u0004 \u0005[כמי שאינו נחשב]\u0006 — \u0003אלא לענין קרבן,\u0004 וטעמו: \u0003כיון\u0004 שלא \u0003יצאה שעה שראויה להקריב בה קרבן\u0004 על הוולד הראשון, \u0003הואיל וכן ולד שני כמאן דליתיה דמי\u0004 \u0005[כמי שאינו הוא נחשב],\u0006 \u0003אבל לענין\u0004 ימי \u0003טומאה ו\u0004ימי \u0003טהרה אימא סבירא ליה\u0004 \u0005[אמור שהוא סבור]\u0006 שהוולד השני \u0003כמאן דאיתיה דמי\u0004 \u0005[כמי שישנו הוא נחשב]\u0006\u0003, ו\u0004לפיכך כשיולדת את השני \u0003מפסקא\u0004 \u0005[מפסיקה]\u0006 ספירת ימי ה\u0003טומאה\u0004 של ה\u0003שני\u0004 את ימי הטהרה של הראשון, \u0003ו\u0004לאחר מכן חוזרת ו\u0003ממלא יומי\u0004 \u0005[ממלאה,\u0006 משלימה \u0005ימי]\u0006 \u0003טהרה\u0004 של הראשון, \u0003והדר מונה יומי\u0004 \u0005[ואחר כך מונה ימי]\u0006 \u0003טהרה לשני.\u0004","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לר' יהודה,\u0004 גם אם הוא מחשיב את הוולד השני כמי שישנו, \u0003חומרא הוא דאית ליה\u0004 \u0005[\u0006צד \u0005חומרה\u0006 בזה \u0005הוא שיש לו],\u0006 שנוהגת ימי טומאתו של שני בתוך ימי טהרה של הראשון, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 אם נאמר שחוזרת ומשלימה ימי טהרה לראשון — \u0003קולא הוא,\u0004 שאפילו אם רואה דם בימים אלו טהורה היא, \u0003וקולא לית ליה\u0004 \u0005[אין לו],\u0006 שהוא חושש רק להחמיר.","\u0003אמר רב הונא מסורא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003יולדת, שוחטין\u0004 עליה את הפסח בארבעה עשר בניסן \u0003וזורקין עליה\u0004 את דמו \u0003ביום ארבעים ל\u0004לידת \u0003זכר וביום שמונים לנקבה,\u0004 מפני שהיא יכולה לאכול ממנו בליל חמישה עשר.","והיינו מתקשים בדבר: \u0003עד כאן\u0004 אתה מתיר? והלוא בליל חמישה עשר עדיין \u0003טמאה היא,\u0004 שהרי היא מביאה את קרבנה ביום הארבעים ואחד (לזכר), ורק אז מותרת לאכול קדשים! \u0003ואמר רב חסדא: הא מני\u0004 \u0005[\u0006וברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת ר' \u0003יהודה הוא,\u0004 שאמר במשנתנו: \u0003ולד שני כמאן דליתיה דמי\u0004 \u0005[כמי שאינו הוא נחשב].\u0006 ומדובר באשה שילדה שני זכרים יום אחר יום, וערב הפסח חל ביום הארבעים לוולד השני, שהוא היום הארבעים ואחד לוולד הראשון.","\u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 ש\u0003בטומאה סבירא ליה\u0004 \u0005[סבור]\u0006\u0003 ר' יהודה\u0004 ש\u0003ולד שני כמאן דאיתיה דמי\u0004 \u0005[כמי שישנו הוא נחשב],\u0006 \u0003היכי שחטינן עלה\u0004 \u0005[איך אנו שוחטים עליה]\u0006 \u0003ביום ארבעים\u0004 ללידתו? הלוא \u0003לאורתא נמי לא מציא אכלה\u0004 \u0005[לערב גם כן אינה יכולה לאכול]\u0006 בקדשים עד שתביא קרבנה למחרת! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שגם \u0003ל\u0004ענין \u0003טהרה ולטומאה סבירא ליה\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה\u0004 ש\u0003ולד שני כמאן דליתיה דמי\u0004 \u0005[כמי שאינו הוא נחשב]!\u0006","ודוחים: \u0003לעולם אימא לך\u0004 \u0005[אומר לך]:\u0006 \u0003לטומאה ולטהרה סבירא ליה\u0004 \u0005[סבור] ר'\u0006 \u0003יהודה\u0004 שולד \u0003שני כמאן דאיתיה דמי\u0004 \u0005[כמי שישנו\u0006 הוא \u0005נחשב],\u0006 \u0003וכי תניא ההיא\u0004 \u0005[וכאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 ששוחטים עליה את הפסח ביום הארבעים לזכר — הרי זה \u0003בפסח הבא בטומאה,\u0004 כאשר רוב העם או הכהנים נטמאו בטומאת מת, ואז הפסח נאכל בטומאה.","ושואלים: \u0003ומי אכלה\u0004 \u0005[והאם\u0006 במקרה זה יולדת \u0005אוכלת\u0006 ממנו\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006\u0003: פסח הבא בטומאה, לא יאכלו ממנו זבים וזבות, נדות ויולדות,\u0004 אלא רק טמאי מת!","ומשיבים: מה שנאמר במשנה \u0003ההיא\u0004 שזבים וזבות וכו' \u0003לא אכלי\u0004 \u0005[אוכלים]\u0006 מן הפסח הבא בטומאה הרי זה \u0003כי לא טבילן\u0004 \u0005[כאשר\u0006 עדיין \u0005לא טבלו]\u0006 מטומאתם. לעומת זאת, \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 לגבי יולדת, ש\u0003שוחטין וזורקין עליה\u0004 ביום הארבעים לזכר, טעם הדבר הוא — \u0003דהא\u0004 \u0005[שהרי]\u0006 כבר \u0003טבלה\u0004 בליל השמיני ללידה, בגמר ימי טומאתה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מדוע מדובר בברייתא ביום הארבעים ללידת הזכר? והלוא כבר \u0003משמיני דיליה\u0004 \u0005[שלו],\u0006 שאז היא טובלת מטומאתה, \u0003הוא דחזיא\u0004 \u0005[ש\u0006היא \u0005ראויה]\u0006 שישחטו עליה, ותאכל את הפסח!","ומשיבים: \u0003משמיני לא חזיא\u0004 \u0005[\u0006עדיין \u0005אינה ראויה],\u0006 שכן \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 התנא: \u0003טבול יום\u0004 של \u0003זב,\u0004 זב ביום שטבל מטומאתו — \u0003כזב\u0004 שלא טבל \u0003דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ואינו אוכל מן הפסח הבא בטומאה. והוא הדין ליולדת זכר, שמהיום השמיני ועד סוף יום הארבעים הריהי \"טבולת יום ארוך\".","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003ביום ארבעים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא חזיא\u0004 \u0005[\u0006עדיין \u0005אינה ראויה]!\u0006 ודוחים: \u0003לאיי\u0004 \u0005[לא כן],\u0006 \u0003ביום ארבעים חזיא\u0004 \u0005[ראויה היא],\u0006 מפני שהיא יכולה לאכול מן הפסח בערב, שכן \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 התנא של ברייתא זו: \u0003מחוסר כפורים\u0004 של \u0003זב,\u0004 שטבל וכבר העריב שמשו, ואינו מחוסר אלא קרבן — \u0003לאו כזב דמי\u0004 \u0005[אינו נחשב כזב],\u0006 ומותר לאכול מן הפסח הבא בטומאה, והוא הדין ליולדת במוצאי יום הארבעים לזכר.","ושואלים, \u0003ולרבא\u0004 שאמר: \u0003מחוסר כפורים\u0004 של \u0003זב כזב דמי\u0004 \u0005[נחשב],\u0006 \u0003הא מתנייתא היכי מתרץ לה\u0004 \u0005[אותה ברייתא איך הוא מתרץ,\u0006 מיישב \u0005אותה]?\u0006 \u0003אמר רב אשי: רבא\u0004 אינו מסביר ברייתא זו ביום הארבעים או השמונים ללידה, אלא הוא \u0003מתרץ לה\u0004 \u0005[אותה]\u0006 באשה שהפילה \u0003ביום ארבעים ליצירת\u0004 כלומר, להריון של \u0003זכר וביום שמונים ליצירת נקבה, ו\u0004דעת ר' \u0003ישמעאל היא,\u0004 שאמר: \u0003לזכר\u0004 זמן היצירה הוא \u0003ארבעים ואחד, לנקבה שמונים ואחד,\u0004 והמפילה ביום ארבעים ליצירת זכר, או שמונים ליצירת נקבה — אינה טמאה טומאת לידה.","ומקשים: \u0003סוף סוף\u0004 מדוע שוחטים עליה את הפסח? \u0003תיפוק\u0004 \u0005[תצא]\u0006 \u0003לי\u0004 שטמאה \u0003היא משום נדה,\u0004 שראתה דם בזמן הלידה! ומשיבים: מדובר \u0003בלידה יבישתא\u0004 \u0005[יבישה],\u0006 שלא היה בה דם. ומקשים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך, מה\u0006 בא התנא \u0005לומר]?\u0006 ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אי אפשר לפתיחת הקבר\u0004 (הרחם) \u0003בלא דם,\u0004 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003אפשר לפתיחת הקבר בלא דם.\u0004 ושבים לדיון בדעת ר' יהודה, האם לשיטתו משלימים ימי טהרה לוולד הראשון.","\u0003אמר ר' שמעיה, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: נאמר ביולדת נקבה \"וששים יום וששת ימים תשב על דמי טהרה\" (ויקרא יב, ה) — \u0003יכול\u0004 מונה ששים ימים אלה \u0003בין רצופין בין מפוזרין,\u0004 וכגון שהפילה באמצעם, ונטמאה, שמשלימה לאחר מכן את ימי הטהרה של הראשון? \u0003תלמוד לומר: \"י ום\",\u0004 ומלה זו מיותרת, אלא באה ללמדנו: \u0003מה יום רצוף\u0004 — \u0003אף ששים כולן רצופין.\u0004 ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אלימא רבנן\u0004 \u0005[אם תאמר\u0006 לשיטת \u0005חכמים],\u0006 \u0003מי אית לרבנן\u0004 \u0005[האם יש לחכמים]\u0006 אפשרות של ימי טהרה \u0003מפוזרין?\u0004 והלוא לשיטתם, המפלת בתוך מלאת — מונה רק לוולד השני!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 דעת ר' \u0003יהודה היא. ומדקא יהיב לה\u0004 \u0005[ומ\u0006מה \u0005שהוא נותן לה]\u0006 \u0003ששים רצופים בהדי הדדי\u0004 \u0005[יחד],\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שגם אם \u0003חומרא אית ליה\u0004 \u0005[יש לו]\u0006\u0003 לר' יהודה,\u0004 לנהוג ימי טומאה לשני, אבל \u0003קולא לית ליה\u0004 \u0005[אין לו]\u0006 להשלים לראשון ימי טהרה!","ודוחים: \u0003לא, לעולם\u0004 ברייתא זו \u0003רבנן\u0004 \u0005[דעת חכמים]\u0006 \u0003היא,\u0004 הסבורים שמונה ימי טומאה וטהרה לוולד השני. \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]?\u0006 \u0003ליולדת\u0004 (מפילה) \u0003זכר מתוך שמונים של נקבה,\u0004 שבתוך שמונים היום של הנקבה נשלמו ימי טומאה וטהרה של הזכר. ובמקרה זה היה מקום לומר שאין מניינו של השני מבטל את הראשון, אלא לאחר שתמנה לזכר ימי טומאה תשלים את ימי הטהרה של הנקבה. לכן נאמר שצריך שיהיו שישים ושישה הימים רצופים, ומונה רק שישים ושישה ימי טהרה של הנקבה, ולא יותר.","ומקשים: \u0003סוף סוף\u0004 לא תיתכן מציאות כזו שנעמיד בה את הברייתא, שהרי \u0003שלמין יומי דקדמאה\u0004 \u0005[נשלמים\u0006 שמונים \u0005הימים של הראשון,\u0006 הנקבה\u0005]\u0006 \u0003ועד כאן דבתראה לא שלמין\u0004 \u0005[ועדיין\u0006 הימים \u0005של האחרון לא נשלמים],\u0006 ואם כן, אין להעמיד ברייתא זו כשיטת חכמים, \u0003דהא רבנן\u0004 \u0005[שהרי חכמים]\u0006 \u0003לולד שני מנו\u0004 \u0005[מונים\u0006 הם\u0005]!\u0006 ומתרצים: \u0003אלא משכחת לה לרבנן\u0004 \u0005[מוצא אתה לחכמים]\u0006 אפשרות עקרונית לימי טהרה מפוזרים — \u0003ביולדת תאומים, נקבה קדמייתא\u0004 \u0005[ראשונה]\u0006 \u0003וזכר בתראה\u0004 \u0005[אחרון],\u0006 \u0003וכגון דילידתיה\u0004 \u0005[שילדה את]\u0006 הזכר \u0003בתראה\u0004 \u0005[האחרון] ב\u0006יום ה\u0003עשרים ליומי\u0004 \u0005[לימי]\u0006 \u0003טהרה\u0004 של הנקבה, \u0003דבעיא מינקט ליה\u0004 \u0005[שצריכה לשמור לו]\u0006 \u0003שבעה יומי\u0004 \u0005[ימי]\u0006 \u0003טומאה\u0004 של לידה (תאומים נקבה),","\u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003יכול היכא\u0004 \u0005[במקום]\u0006 ש\u0003ילדה תאומים, נקבה מעיקרא\u0004 \u0005[בתחילה]\u0006 \u0003וזכר לבסוף, תפסיק טומאה\u0004 של \u0003לידה\u0004 של הזכר \u0003במיצעי\u0004 \u0005[באמצע],\u0006 \u0003ונימני\u0004 \u0005[ונספור]\u0006 \u0003לה\u0004 לנקבה \u0003ששה וששים מפוזרין? תלמוד לומר: \"יום\", מה יום כולו רצוף\u0004 — \u0003אף ששים כולם רצופין.\u0004 ושבים לבירור שיטת ר' יהודה, האם לדעתו משלימים ימי טהרה לוולד הראשון.","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא לענין יולדת זכר: \"ו \u0003שלשים\u0004 יום ושלשת ימים תשב בדמי טהרה\" (ויקרא ה, ד) — \u0003יכול\u0004 שלושים \u0003בין רצופין בין מפוזרין? תלמוד לומר: \"י ום\", מה יום כולו רצוף\u0004 — \u0003אף שלשים רצופין.\u0004 ונברר: \u0003מני הא\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אלימא רבנן\u0004 \u0005[אם תאמר\u0006 כשיטת \u0005חכמים],\u0006 \u0003ומי אית להו לרבנן\u0004 \u0005[והאם יש להם לחכמים]\u0006 אפשרות של ימי טהרה"],["\u0003מפוזרין,\u0004 שלאחר שבעה ימי טומאה של השני ממשיכה בימי טהרה של הראשון? \u0003הא אמרי רבנן\u0004 \u0005[הרי אומרים חכמים]:\u0006 במקרה של ולדות הרבה, \u0003לולד שני מניא\u0004 \u0005[היא מונה],\u0006 ולא לראשון! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כדעת ר' \u0003יהודה היא, ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003חומרא אית ליה\u0004 \u0005[יש לו]\u0006 להחשיב את הוולד השני כמי שישנו, ולנהוג בו ימי טומאה, אבל \u0003קולא לית ליה\u0004 \u0005[אין לו],\u0006 להשלים במקומם ימי טהרה לראשון.","\u0003ועוד אמר רב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: נאמר ביולדת נקבה \"וששים יום \u0003וששת ימים\u0004 תשב על דמי טהרה\" (ויקרא יב, ה) — \u0003יכול\u0004 תמנה ששה ימים אלה \u0003בין רצופין ובין מפוזרין,\u0004 וכגון שהפילה ביום הששים ושלושה, שתמנה ימי טומאה לשני ותשלים שלושה ימי טהרה לראשון? \u0003תלמוד לומר: ששים\u0004 יום, \u0003מה ששים כולן רצופין\u0004 — \u0003אף ששה כולן רצופין.\u0004 ונברר: \u0003מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 \u0003אלימא רבנן\u0004 \u0005[אם תאמר\u0006 כשיטת \u0005חכמים],\u0006 \u0003מי אית להו לרבנן\u0004 \u0005[האם יש להם לחכמים]\u0006 ענין זה של \u0003מפוזרין? האמרי רבנן\u0004 \u0005[הרי אומרים חכמים]:\u0006 \u0003לולד שני מניא\u0004 \u0005[היא מונה]!\u0006","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת ר' \u0003יהודה היא, ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003חומרא אית ליה\u0004 \u0005[יש לו],\u0006 \u0003קולא לית ליה\u0004 \u0005[אין לו]\u0006 בענין זה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אלו\u0004 הם החמישה ששנינו במשנה לעיל (ט,א) ש\u0003מביאין קרבן עולה ויורד,\u0004 שמשתנה לפי מצבו הכלכלי של החייב: \u0003על שמיעת קול,\u0004 שנשבע לשקר שאינו יודע עדות לחבירו, \u0003ועל בטוי שפתים,\u0004 שנשבע שבועת שקר בענין אחר, \u0003ועל טומאת מקדש וקדשיו,\u0004 שנכנס למקדש או נגע בקדשים בטומאה, \u0003והיולדת, והמצורע.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בסיכום דיני קרבן עולה ויורד: \u0003יש מביא בדלות ועשירות,\u0004 כלומר שיש בו שתי דרגות, גם דלות (קרבן מן העוף) וגם עשירות (מן הבהמה), ויש מביא בדלות ו(יש מביא) \u0003בדלי דלות\u0004 (קרבן מנחה). כיצד?","\u0003יולדת מביאה בדלות ועשירות,\u0004 בעשירות — כבש לעולה ובן יונה או תור לחטאת, ובעניות — שני תורים או שני בני יונה, אחד לעולה ואחד לחטאת (ויקרא יב, א—ח). וכן \u0003מצורע מביא בדלות\u0004 ובעשירות, בעשירות — כבש לאשם, כבש לעולה וכבשה לחטאת, ובדלות — כבש לאשם, ושני תורים או שני בני יונה, אחד לחטאת ואחד לעולה (שם יד, י—כב). ועל \u0003שמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו\u0004 — \u0003מביאין בדלות ודלי דלות\u0004 נוסף לעשירות, בעשירות — כשבה או שעירה לחטאת, בדלות — שני תורים או שני בני יונה, אחד לחטאת ואחד לעולה, בדלי דלות — עשירית האיפה למנחה (שם ה, א—יד).","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003יש מביא אחד תחת אחד, יש מביא שנים תחת שנים, יש מביא שנים תחת אחד, יש מביא אחד תחת שנים, מכאן אתה למד לעשירית האיפה\u0004 שהיא \u0003בפרוטה.\u0004","ומפרטים: \u0003יולדת מביאה אחת תחת אחת\u0004 — \u0003פרידה אחת ו\u0004היא \u0003עוף תחת כבש, מצורע\u0004 מביא \u0003שתי פרידין תחת שני כבשים\u0004 — הרי הם שנים תחת שנים, \u0003שמיעת הקול ובטוי שפתים וטומאת מקדש וקדשיו\u0004 — \u0003מביאין שתי פרידין,\u0004 שני תורים או שני בני יונה, \u0003תחת כבשה אחת\u0004 — הרי שנים תחת אחד, \u0003ומביאין בדלי דלות עשירית האיפה תחת שתי פרידין\u0004 — הרי אחד תחת שנים.","ואומרים, \u0003קתני\u0004 \u0005[שונה]\u0006 התנא: \u0003מכאן אתה למד לעשירית האיפה שהיא בפרוטה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 כיצד נלמד דבר זה? ומבארים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא: \u0003האומר \"הרי עלי\u0004 קרבן \u0003בסלע למזבח\"\u0004 — \u0003מביא כבש, שאין דבר קרב בסלע אלא כבש.\u0004","ומעירים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מהיכן\u0005]\u0006 למדים דבר זה? \u0003מדאמר רחמנא\u0004 \u0005[ממה שאמרה התורה]\u0006 לגבי \u0003איל אשם\u0004 שהוא \u0003ב\"כסף שקלים\"\u0004 (שם טו), כלומר, בשווי שני שקלים (סלעים בלשון חכמים) — \u0003מכלל\u0004 הדברים אתה למד שכבש (איל צעיר) \u0003בן שנה\u0004 (כלומר, בן שנתו הראשונה) שהצריכה התורה לקרבן עשירות הוא \u0003בסלע. ומנין שהצריכה התורה כבש בן שנה? מדכתיב\u0004 \u0005[ממה שנאמר]\u0006 בקרבן היולדת: \u0003\"כבש בן שנתו\"\u0004 (ויקרא יב, ו). \u0003ו\u0004לגבי קרבן דלות, שהוא קן של שני תורים או שני בני יונה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003עמדו קינין בו ביום ברבעתים,\u0004 כל קן ברובע דינר, שהוא אחד מששה עשר בסלע (שבכל סלע ארבעה דינרים).","\u0003ומדחס רחמנא עליה דדלות\u0004 \u0005[ומ\u0006תוך \u0005שחסה התורה על זה שמביא בדלות]\u0006 \u0003למיהוי חד משית עשר\u0004 \u0005[להיות אחד מששה עשר]\u0006 \u0003בעשירות,\u0004 יש לומר כי \u0003חס רחמנא עליה\u0004 \u0005[חסה התורה על מי שמביא]\u0006 ב\u0003דלי דלות\u0004 (עשירית האיפה) \u0003למיהוי חד משית עשר\u0004 \u0005[להיות אחד מששה עשר]\u0006 \u0003בדלות.\u0004","ושואלים: \u0003אם כן,\u0004 כשאתה עושה חשבון זה, \u0003דלות כמה הויא\u0004 \u0005[היא]\u0006 — \u0003ריבעא\u0004 \u0005[רבע\u0006 דינר\u0005], וכמה פריטי בריבעא\u0006 \u0005[פרוטות\u0006 נחושת יש \u0005ברבע]\u0006 — \u0003ארבעים ותמניא פריטי\u0004 \u0005[ארבעים ושמונה פרוטות];\u0006 \u0003חד משית עשר כמה הוי דדלות\u0004 \u0005[אחד מששה עשר של דלות כמה הוא]\u0006 — \u0003תלתא פריטי\u0004 \u0005[שלוש פרוטות].\u0006","ואם כן, מה \u0003דקתני\u0004 \u0005[שהוא שונה]:\u0006 \u0003מכאן אתה למד לעשירית האיפה בפרוטה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003פרוטה? האמרת\u0004 \u0005[הרי אומר אתה]:\u0006 \u0003עשירית האיפה דלי דלות הוא, ואמרת\u0004 \u0005[ואומר אתה]\u0006 כי דלי דלות \u0003חד משית סרי\u0004 \u0005[אחד מששה עשר]\u0006 של \u0003דלות הוא, דחשבינן דתלתא פריטי הויין\u0004 \u0005[שחישבנו ששלוש פרוטות הן]!\u0006","ומשיבים: ה\u0003תנא,\u0004 שלמד עשירית האיפה בפרוטה, \u0003מיולדת יליף\u0004 \u0005[לומד],\u0006 \u0003דמתיא\u0004 \u0005[ש\u0006היא \u0005מביאה]\u0006 \u0003פרידה אחת\u0004 לעולה \u0003תחת כבש\u0004 העולה, כלומר, חצי קן, \u0003דהוי חד מתלתין ותרין\u0004 \u0005[שהוא\u0006 \u0005אחד משלושים ושנים]\u0006 של \u0003כבש\u0004 ששוויו סלע, כלומר שמינית הדינר, ולא רבע. ומקשים: \u0003ועד כאן,\u0004 עדיין צריך אתה לומר כי \u0003דלי דלות כמה הוי\u0004 \u0005[הוא]\u0006 — \u0003חד משית עשר\u0004 \u0005[אחד מששה עשר]\u0006 \u0003בדלות.\u0004 שהרי ביולדת עצמה אין דין דלי דלות, אלא בשמיעת הקול, ושם קרבן הדלות הוא קן שלם, שהוא אחד מששה עשר בעשירות, \u0003דמהיכא יליף\u0004 \u0005[ש\u0006הרי \u0005מהיכן הוא לומד]\u0006 את היחס בין דלות ודלי דלות — \u0003מכבש ואיל\u0004 כפי שהסברנו לעיל. ואם כן \u0003עד כאן,\u0004 לפי דרך זו, קרבן דלי דלות \u0003פרוטה ופלגא הוי\u0004 \u0005[פרוטה וחצי הוא],\u0006 שכך עולה החשבון, כשנחלק שמינית הדינר, שהיא עשרים וארבע פרוטות, לששה עשר. ולא פרוטה בלבד, כלשון הברייתא!","\u0003אמר רבא: כולה מילתא\u0004 \u0005[כל הענין]\u0006 \u0003מיולדת יליף\u0004 \u0005[\u0006התנא \u0005לומד],\u0006 \u0003והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]:\u0006 \u0003מדחס רחמנא עליה\u0004 \u0005[ממה שחסה התורה על זה שמביא]\u0006 ב\u0003דלות למיהוי חד מתלתין ותרין\u0004 \u0005[להיות אחד משלושים ושתים]\u0006 \u0003בעשירות, ומאי\u0004 \u0005[ומה]\u0006 \u0003היא\u0004 — \u0003יולדת, הכי חס רחמנא עליה\u0004 \u0005[כך חסה התורה על זה שמביא]\u0006 בדלי \u0003דלות\u0004 (על שמיעת הקול) \u0003למיהוי חד מן תלתין ותרין\u0004 \u0005[שיהיה אחד משלושים ושתים]\u0006 \u0003בדלות.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 לפי חשבון זה, דלי דלות \u0003נכי ריבעא דפרוטה הוי\u0004 \u0005[פרוטה פחות רבע הוא],\u0006 כלומר, שלושה רבעי פרוטה, עשרים וארבע פרוטות לחלק לשלושים ושנים! ומשיבים: \u0003הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 שבאמת מצד החשבון הוא פחות מפרוטה, \u0003אלא דלאו אורח ארעא לאיתויי\u0004 \u0005[שאין זה דרך ארץ להביא]\u0006 דבר ששוה \u0003פחות מפרוטה\u0004 קרבן \u0003למקום.\u0004","\u0003מה בין שפחה\u0004 חרופה \u0003לבין כל העריות? שלא שוותה להן לא בעונש ולא בקרבן. שכל העריות,\u0004 אם בא עליהן — דינו \u0003בחטאת, ו\u0004הבא על \u0003שפחה\u0004 דינו \u0003באשם. כל העריות\u0004 דינו \u0003ב\u0004קרבן \u0003נקבה,\u0004 שחטאת יחיד היא כשבה או שעירה (ויקרא ד, כז—לב), \u0003ו\u0004הבא על ה\u0003שפחה\u0004 דינו \u0003ב\u0004איל \u0003זכר\u0004 (שם יט, כא).","\u0003כל העריות אחד האיש ואחד האשה שוין\u0004 בעונש, בין \u0003במכות\u0004 אם התרו בהם, \u0003ו\u0004בין \u0003בקרבן\u0004 חטאת בשוגג, \u0003ובשפחה לא השוה לא האיש לאשה במכות,\u0004 שרק היא לוקה, \u0003ולא השוה אשה לאיש בקרבן,\u0004 שהיא אינה מביאה קרבן אשם.","\u0003כל העריות עשה בהן את\u0004 דינו של \u0003המערה\u0004 שאינו בא ביאה גמורה, \u0003כגומר\u0004 את ביאתו לגמרי, שגם על זה וגם על זה חייב, מה שאין כן בשפחה, שאינו חייב עד שיגמור ביאתו. וכן בעריות \u0003חייב על כל ביאה וביאה\u0004 קרבן לחוד, מה שאין כן בשפחה, שמביא קרבן אחד על ביאות הרבה, כפי ששנינו במשנה לעיל (ט,א).","\u0003זו חומר\u0004 (חומרה) \u0003החמיר\u0004 הכתוב \u0003בשפחה\u0004 לעומת העריות,"],["\u0003שעשה בה את המזיד כשוגג,\u0004 שבין כך ובין כך מביא אשם, ובעריות רק השוגג מביא חטאת.","\u0003איזו\u0004 היא \u0003שפחה\u0004 נחרפת לאיש שמדבר בה הכתוב? \u0003כל שחציה שפחה וחציה בת חורין,\u0004 וכגון שפחה כנענית שהיו לה שני אדונים, ואחד מהם שיחרר אותה, \u0003שנאמר: \"והפדה לא נפדתה\"\u0004 (ויקרא יט, כ), כלומר פדויה ואינה פדויה לגמרי, אלו \u0003דברי ר' יהודה. ר' ישמעאל אומר:\u0004 שפחה חרופה \u0003זו היא שפחה ודאית,\u0004 גמורה. \u0003ר' אליעזר בן יעקב אומר: כל עריות\u0004 שבתורה \u0003מפורשות,\u0004 ובכללן אשת איש שחייב עליה הכתוב מיתה, \u0003ושיור אין לנו\u0004 בפרשה זו של שפחה הנחרפת (מאורסת) לאיש \u0003אלא\u0004 מי שהיא \u0003חציה שפחה וחציה בת חורין.\u0004","שנינו במשנה שבשפחה חרופה לא השווה את האיש לאשה במלקות. ומבררים: \u0003מנלן דהיא לקי והוא לא לקי\u0004 \u0005[מנין לנו שהיא לוקה והוא אינו לוקה]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]: \"\u0006\u0003בקרת תהיה\"\u0004 (ויקרא יט, ב) — \u0003מלמד שהיא לוקה; יכול\u0004 יהו \u0003שניהן לוקין? תלמוד לומר: \"תהיה\",\u0004 לומר: \u0003היא לוקה והוא אינו לוקה.\u0004","ושואלים: \u0003ומנין דהדין \"בקרת\"\u0004 \u0005[ש\"ביקורת\" זו]\u0006 \u0003לישנא\u0004 \u0005[לשון]\u0006 של \u0003מלקות הוא? אמר ר' יצחק:\u0004 \"ביקורת\" הוא כעין קיצור של המילים \u0003\"תהא בקראי\"\u0004 \u0005[תהא ב\u0006קריאה \u0005של מקראות],\u0006 \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]\u0006 לענין ביצוע המלקות בבית דין: \u0003גדול הדיינין מקרא\u0004 את הפסוקים שאומרים בענין זה, \u0003שני\u0004 בדיינים \u0003מונה\u0004 את המלקות, \u0003שלישי אומר\u0004 לשמש: \u0003הכהו. רב אשי אומר,\u0004 רמז אחר למלקות יש בכך: \u0003\"בביקור תהיה\",\u0004 כלומר, בבדיקה, שבודקים אותה כמה מלקות היא מסוגלת לקבל, \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אין אומדין אותו\u0004 את הלוקה, כמה מלקות הוא מסוגל לקבל, \u0003אלא מכות הראוין להשתלש,\u0004 להתחלק לשלוש, שהיו מלקים פעמיים על גבו ואחת לפניו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בזמן שהאשה לוקה\u0004 — רק אז \u0003האיש מביא קרבן,\u0004 אבל אם \u0003אין האשה לוקה,\u0004 וכגון שהיתה שוגגת, או אנוסה, או קטנה, שאינה בת עונשין — \u0003אין האיש מביא קרבן.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר רבא, דכתיב\u0004 \u0005[שנאמר]\u0006\u0003: \"ואיש כי ישכב את אשה שכבת זרע והיא שפחה נחרפת לאיש והפדה לא נפדתה או חפשה לא נתן לה\u0004 בקורת תהיה...","והביא את אשמו\" (שם כ—כא), \u0003מכדי עד הכא\u0004 \u0005[הואיל ועד כאן],\u0006 כלומר, מתחילה \u0003באיש קא משתעי קרא\u0004 \u0005[עוסק הכתוב],\u0006 \u0003נכתוב\u0004 \u0005[שיכתוב]\u0006 תחילה: \u0003\"והביא את אשמו לה'\", ולבסוף לכתוב\u0004 \u0005[שיכתוב]\u0006 \u0003\"בקרת תהיה\"\u0004 לגבי האשה, \u0003אמאי כתב רחמנא ברישא\u0004 \u0005[מדוע כתבה התורה בתחילה]:\u0006 \u0003\"בקרת תהיה\" ולבסוף כתב: \"והביא את אשמו לה'\"?\u0004 אלא \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אם בקורת תהיה היא,\u0004 שהיא לוקה — \u0003והביא\u0004 האיש \u0003את אשמו לה', ואם לא תהיה בקורת\u0004 — \u0003לא יביא הוא את אשמו.\u0004","ושואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהוא, האיש, \u0003מעטיה קרא\u0004 \u0005[מיעט אותו המקרא]\u0006 מהבאת קרבן במקרה כזה, \u0003אבל היא תילקי ותיתי\u0004 \u0005[תלקה ו\u0006גם \u0005תביא]\u0006 \u0003קרבן!\u0004 ומשיבים: \u0003\"והביא את אשמו לה'\" כתיב\u0004 \u0005[נאמר],\u0006 ולא \"והביא אשם\", לדייק כי רק הוא מביא את האשם.","\u0003אמר ר' יצחק: לעולם אינו חייב אלא\u0004 שבא \u0003על שפחה בעולה בלבד, שנאמר: \"והיא שפחה נחרפת לאיש\",\u0004 ונחרפת משמעה בעולה. \u0003ומאי משמע\u0004 \u0005[ומהי המשמעות],\u0006 כיצד יודעים \u0003דהאי\u0004 \u0005[ש\u0006מלה \u0005זו]\u0006 \u0003\"נחרפת\" לישנא דשנויי הוא\u0004 \u0005[לשון של שינוי הוא],\u0006 שנשתנתה וכבר אינה בתולה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006\u0003: \"ותשטח עליו הרפות\"\u0004 (שמואל ב יז, יט), ו\"הריפות\" הן שעורים שנכתשו ונשתנו ממה שהיו. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 מהפסוק: \u0003\"אם תכתוש האויל במכתש בתוך הריפות בעלי\u0004 לא תסור מעליו איוולת\" (משלי כז, כב). נאמר בספר עזרא: \"וימצא מבני הכהנים אשר השיבו נשים נכריות...","\u0003ויתנו ידם להוציא נשיהם ואשמים איל צאן על אשמתם\"\u0004 (עזרא י, יח—יט) — \u0003אמר רב חסדא: מלמד, שכולן שפחות חרופות בעלו,\u0004 שהרי לא מצאנו קרבן אשם על ביאה, אלא על שפחה חרופה.","שנינו במשנה מחלוקת \u0003איזוהי שפחה\u0004 חרופה. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"והפדה\"\u0004 (ויקרא יט, כ) — \u0003יכול\u0004 שכולה פדויה? \u0003תלמוד לומר: \"לא נפדתה\";\u0004 אם כן \u0003יכול\u0004 מדובר במי ש\u0003לא נפדתה\u0004 כלל? \u0003תלמוד לומר: \"והפדה\",\u0004","\u0003הא כיצד?\u0004 מדובר במי שהיא \u0003פדויה ואינה פדויה,\u0004 כלומר, \u0003חציה שפחה וחצייה בת חורין, ו\u0004היא \u0003מאורסת לעבד עברי, דברי ר' עקיבא. ר' ישמעאל אומר: בשפחה כנענית הכתוב מדבר,\u0004 שאינה בת חורין כלל, \u0003ו\u0004היא \u0003מאורסת לעבד עברי. אם כן מה תלמוד לומר,\u0004 מדוע השתמשה התורה בביטוי הכפול \u0003\"והפדה לא נפדתה\"\u0004 — \u0003דברה תורה כלשון בני אדם,\u0004 שמשתמשים בלשונות כפולות, ואין ללמוד מכאן הלכה.","ר' אלעזר בן עזריה אומר: כל עריות מפורשות לנו בתורה, \u0003משוייר לנו,\u0004 איפוא, \u0003חציה שפחה וחציה בת חורין ומאורסת לעבד עברי. אחרים אומרים:\u0004 נאמר \"\u0003לא יומתו כי לא חפשה\"\u0004 (ויקרא יט, כ) — \u0003בשפחה כנענית הכתוב מדבר, ומאורסת לעבד כנעני\u0004 ולא לעבד עברי.","ומבררים את השיטות: לשיטת ר' ישמעאל, \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 שהוא מסביר \u0003\"והפדה לא נפדתה\"\u0004 בשפחה גמורה — \u0003כדקתני\u0004 \u0005[כמו שהוא שונה]:\u0006 \u0003דברה תורה כלשון בני אדם, אלא דקתני\u0004 \u0005[\u0006מה \u0005שהוא שונה]\u0006 שהיא \u0003מאורסת לעבד עברי מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]: \"\u0006\u0003כי לא חפשה\"\u0004 (שם), \u0003מכלל\u0004 הדברים אתה למד ש\u0003הוא,\u0004 האיש שלו היא מאורסת — \u0003חופש\u0004 (חופשי), שאינו עבד כנעני הקנוי לבעליו, אלא עבד עברי, שאינו אלא כשכיר.","ועוד שואלים: שיטת \u0003ר' אלעזר בן עזריה היינו\u0004 \u0005[הריהי]\u0006 שיטת ר' \u0003עקיבא,\u0004 שמדובר בשפחה שחציה בת חורין, ולשם מה הובאו דבריו בנפרד? ומשיבים, \u0003לר' ישמעאל,\u0004 הסבור שמדובר בשפחה גמורה, \u0003קאמר\u0004 \u0005[אומר]\u0006 ר' אלעזר בן עזריה: \u0003לדידי, בעלמא כוותיך סבירא ליה\u0004 \u0005[לשיטתי, ב\u0006דרך \u0005כלל כמותך סבור אני]\u0006 ש\u0003דברה תורה כלשון בני אדם, והכא שאני\u0004 \u0005[ו\u0006אולם \u0005כאן שונה]\u0006 הדבר, \u0003מכדי כתיב ליה קרא\u0004 \u0005[הואיל\u0006 וכבר \u0005כתוב לו המקרא]\u0006\u0003: \"כי לא חפשה\", \"והפדה לא נפדתה\" למה לי? שמע מינה להכי אתא\u0004 \u0005[למד מכאן לכך בא], ל\u0006למד שמדובר במי ש\u0003חציה שפחה וחציה בת חורין.\u0004","ושואלים: לשיטת \u0003אחרים,\u0004 האומרים שמדובר בשפחה כנענית המאורסת לעבד כנעני, \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003\"והפדה לא נפדתה\", קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003דברה תורה כלשון בני אדם, אלא הא\u0004 \u0005[זה]\u0006 שהיא מאורסת לעבד \u0003כנעני מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003אמר קרא\u0004 \u0005[המקרא]: \"\u0006\u0003כי לא חפשה\", אם אינו ענין לדידה\u0004 \u0005[עבורה]\u0006 שהרי כבר למדנו דבר זה מ\"הפדה לא נפדתה\" — \u0003תנהו ענין לדידיה\u0004 \u0005[לו עצמו],\u0006 לאיש שלו היא מאורסת, שאינו אדם חופשי, אלא עבד כנעני.","וממשיכים לפרט את ההבדלים שבין העריות לבין שפחה חרופה: \u0003כל עריות,\u0004 אם היה במעשה \u0003אחד גדול ואחד קטן\u0004 — ה\u0003קטן פטור, אחד ער ואחד ישן\u0004 — ה\u0003ישן פטור, אחד שוגג ואחד מזיד\u0004 — \u0003שוגג\u0004 חייב בקרבן \u0003בחטאת ומזיד בהכרת.\u0004","שנינו במשנה כי כל העריות, אם היה אחד גדול ואחד קטן — הקטן פטור. ותמהים: \u0003והכא\u0004 \u0005[וכאן]\u0006 בשפחה חרופה, אתה רוצה לומר ש\u0003חייב\u0004 ה\u0003קטן?\u0004 והלא קטן פטור מן המצוות ומן העונשים! \u0003אמר רב יהודה, הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003כל עריות, אחד\u0004 מהם \u0003גדול ואחד קטן\u0004 — \u0003קטן פטור וגדול חייב, והכא\u0004 \u0005[וכאן,\u0006 בשפחה חרופה\u0005]\u0006 כשאחד מהם קטן — ה\u0003גדול נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006? \u0003דהא מקשיין אהדדי\u0004 \u0005[שהרי הם מוקשים זה לזה]\u0006 בכתוב: \"בקורת תהיה... והביא האיש את אשמו\" (ויקרא יט, כ).","ועוד שנינו: \u0003כל עריות, אחד ניעור ואחד ישן\u0004 — \u0003ישן פטור.\u0004 ותמהים: \u0003וכאן,\u0004 בשפחה חרופה, \u0003ישן נמי\u0004 \u0005[גם כן]\u0006 יהיה \u0003חייב?\u0004 והרי אנוס הוא! \u0003אמר רב יהודה אמר רב, הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003כל עריות, אחד ניעור ואחד ישן\u0004 — \u0003ישן פטור וניעור חייב, וכאן,\u0004 אם היה אחד מהם ישן — \u0003אפילו\u0004 ה\u0003ניעור פטור, מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003דמקשיין אהדדי\u0004 \u0005[\u0006מפני \u0005שמוקשים זה לזה],\u0006 ואם האחד אינו חייב — גם השני פטור.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב ששת: עשו גומר\u0004 ביאתו \u0003כמערה, מתכוין כשאין מתכוין, כדרכה כשלא כדרכה, ניעור כישן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003מאי קאמרת\u0004 \u0005[מה אתה אומר]?\u0006 באיזה מקרה מדובר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשפחה חרופה קתני\u0004 \u0005[הוא שונה]\u0006 הלכות אלה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003עשו גומר כמערה?\u0004 הרי אין הדבר כן, אלא להיפך, \u0003גומר בשפחה חרופה מיחייב\u0004 \u0005[חייב],\u0006 \u0003מערה לא מיחייב\u0004 \u0005[חייב]!\u0006 \u0003ותו\u0004 \u0005[ועוד],\u0006 מה שהוא שונה: עשו \u0003מתכוין כשאינו מתכוין,\u0004 גם כן אינו מתאים לדין שפחה חרופה, שהרי \u0003אי מכוונה\u0004 \u0005[אם היא מתכוונת]\u0006 — \u0003מיחייבא\u0004 \u0005[\u0006היא \u0005מתחייבת]\u0006 מלקות, \u0003אי\u0004 \u0005[אם]\u0006 היא \u0003לא\u0004 מתכוונת — \u0003לא מיחייבא\u0004 \u0005[אינה מתחייבת],\u0006 שהרי עונש מלקות אינו ניתן אלא לעושה במזיד!","\u0003וכדרכה כשלא כדרכה נמי\u0004 \u0005[גם כן],\u0006 אינו מתאים לדין שפחה חרופה, שהרי \u0003כדרכה בשפחה חרופה מיחייב\u0004 \u0005[חייב],\u0006 \u0003ושלא כדרכה לא מיחייב\u0004 \u0005[אינו חייב],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006\u0003? \"שכבת זרע\" כתיב\u0004 \u0005[נאמר],\u0006 שצריך שתהיה זו שכיבה שיש בה כדי להוליד! \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש] שעשו \u0003ניעור כישן?\u0004 הלוא ישן פטור, שהוא אנוס, וניעור — חייב! ואם כן לא ניתן להסביר ברייתא זו בשפחה חרופה.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003בשאר עריות קא תני\u0004 \u0005[הוא שונה]\u0006 ענין זה, מה שהוא שונה ש\u0003עשו גומר כמערה,\u0004"],["\u0003איפכא איבעי ליה למיתני\u0004 \u0005[ההיפך היה צריך לו לשנות],\u0006 שעשו מערה כגומר, שבגומר פשוט לנו הדבר! לאחר כל הקושיות הללו של רב ששת \u0003אמר ליה\u0004 \u0005[לו]\u0006 התנא (חוזר הברייתות): \u0003איסמייה\u0004 \u0005[אמחק אותה]\u0006 את הברייתא הזו, שמשובשת היא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 אל תמחק, אלא יש לתרצה ש\u0003הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003עשו\u0004 דין \u0003גומר שלא כדרכה בשפחה חרופה, דלא מיחייבי\u0004 \u0005[שאינם חייבים],\u0006 \u0003כ\u0004דין \u0003מערה כדרכה\u0004 בשפחה חרופה, שהם פטורים. וטעמו של דבר — שהרי \u0003\"שכבת זרע\" כתיב\u0004 \u0005[נאמר]\u0006 בה (ויקרא יט, כ), וביאה שלא כדרכה אינה ראויה להוליד, גם אם הוא גומר ביאתו.","","וכן עשו דין \u0003מתכוין שלא כדרכה בשפחה,\u0004 שהם \u0003פטורין, כ\u0004דין \u0003אינו מתכוין\u0004 גם אם בא עליה כדרכה, ומאותו טעם: \u0003\"שכבת זרע\" כתיב\u0004 \u0005[נאמר]\u0006 בה, וביאה שלא כדרכה אינה ראויה להוליד. וכן עשו דין \u0003ניעור שלא כדרכה בשפחה,\u0004 שהם \u0003פטורין, כ\u0004דין \u0003ישן\u0004 אפילו כדרכה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003\"שכבת זרע\" כתיב\u0004 \u0005[נאמר].\u0006","ומוסיפים: \u0003נמצא\u0004 שהמתכוין \u0003והמערה בשפחה,\u0004 כלומר, מי שהערה בה והוא מתכוון — דינו \u0003כשאין מתכוין בכל עריות,\u0004 שהוא פטור. וכן דין \u0003ישן\u0004 בשפחה חרופה \u0003כדרכה\u0004 — \u0003כ\u0004דין \u0003ישן\u0004 של \u0003עריות,\u0004 שהוא פטור. וכן נמצא דין \u0003ניעור שלא כדרכה בשפחה\u0004 — \u0003כ\u0004דין \u0003ישן\u0004 של \u0003כל עריות,\u0004 שהוא פטור.","","\u0003אמרו לו\u0004 לאדם: ראינו ש\u0003אכלת חלב\u0004 — הרי זה \u0003מביא חטאת\u0004 על פיהם, אם היה שוגג. \u0003עד\u0004 אחד \u0003אומר: אכל\u0004 חלב, \u0003ועד\u0004 אחר \u0003אומר: לא אכל,\u0004 וכן \u0003אשה אומרת: אכל, ואשה אומרת: לא אכל\u0004 — \u0003מביא אשם תלוי,\u0004 שאדם מביא קרבן זה על ספק חטאת. אם היה \u0003עד אומר: אכל, והוא\u0004 עצמו \u0003אומר: לא אכלתי\u0004 — הרי הוא \u0003פטור.\u0004","אם היו שנים עדים \u0003אומרים: אכל, והוא אומר: לא אכלתי\u0004 — \u0003ר' מאיר מחייב\u0004 חטאת. \u0003אמר ר' מאיר:\u0004 הוכחה לדבר מקל וחומר, \u0003אם הביאוהו שנים לידי מיתה חמורה,\u0004 כגון שהעידו עליו שהרג אדם, גם אם הוא מכחישם — \u0003לא יביאוהו לידי קרבן הקל? אמרו לו:\u0004 בקרבן אינם יכולים לחייב אותו בניגוד לדבריו, שכן \u0003מה אם ירצה לומר \"מזיד הייתי\"\u0004 — הרי הוא \u0003פטור\u0004 מקרבן. \u0003אכל חלב ו\u0004עוד חתיכת \u0003חלב בהעלם\u0004 (בשגגה) \u0003אחת,\u0004 כגון שלא נודע לו בינתיים שחלב אסור, או שחתיכה זו שאכל היתה חלב — \u0003אינו חייב אלא\u0004 חטאת \u0003אחת.\u0004 אבל אם \u0003אכל חלב ודם ופיגול ונותר בהעלם אחת\u0004 — \u0003חייב\u0004 חטאת \u0003על כל אחת ואחת. זה חומר\u0004 (חומרה) \u0003במינין הרבה ממין אחד.\u0004 \u0003ו\u0004יש \u0003חומר במין אחד ממינין הרבה, שאם אכל כחצי זית וחזר ואכל כחצי זית אחר בהעלם אחת,\u0004 אם היו שתי החתיכות \u0003ממין אחד\u0004 — \u0003חייב,\u0004 שהרי אכל כזית שלם של איסור בשגגה אחת. אבל אם היו \u0003משני מינין,\u0004 וכגון כחצי זית חלב וכחצי זית דם — \u0003פטור,\u0004 שלא אכל כדי שיעור אכילה מאחד מהם כדי להתחייב עליו.","","","\u0003קתני\u0004 \u0005[שונה]\u0006 התנא במשנה: \u0003אמרו לו אכלת חלב\u0004 — \u0003מביא חטאת.\u0004 ומדייקים: \u0003\"אמרו\" כמה הויין\u0004 \u0005[הם]?\u0006 \u0003תרין\u0004 \u0005[שנים].\u0006 ויש לשאול: \u0003והוא מה אמר להון\u0004 \u0005[אומר להם]?\u0006 \u0003אלימא דשתיק ולא קמכחיש להו\u0004 \u0005[אם תאמר ששותק ואינו מכחיש אותם],\u0006 \u0003אלא\u0004 לפי זה יש לדייק כי דווקא על \u0003שתיקה דתרין\u0004 \u0005[\u0006מול עדות \u0005של שנים]\u0006 \u0003הוא\u0004 ש\u0003מביא חטאת,\u0004 אבל \u0003על שתיקה דחד\u0004 \u0005[\u0006מול עדות \u0005של אחד]\u0006 — \u0003לא.\u0004","ואולם, \u0003אימא מציעתא\u0004 \u0005[אמור את אמצעיתה\u0006 של המשנה\u0005],\u0006 \u0003עד\u0004 אחד \u0003אומר: אכל, והוא אומר: לא אכלתי\u0004 — פטור. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה \u0003דמכחיש ליה\u0004 \u0005[ש\u0006הוא \u0005מכחיש אותו]\u0006 ואומר: לא אכלתי — פטור, \u0003אבל שתיק\u0004 — \u0003מיחייב\u0004 \u0005[\u0006אם הוא \u0005שותק\u0006 — \u0005הוא חייב],\u0006 \u0003וכל שכן\u0004 אם היו \u0003תרי\u0004 \u0005[שנים]\u0006 מעידים והוא שותק. ואם כן יש כאן סתירה בענין השותק מול עד אחד!","\u0003אלא\u0004 צריך אתה לומר כי מדובר בראש המשנה במקרה \u0003דקמכחיש להו\u0004 \u0005[ש\u0006הוא \u0005אותם],\u0006 את שני העדים, ומשנה זו \u0003מני\u0004 \u0005[שיטת\u0006 \u0005מי היא]?\u0006 שיטת ר' \u0003מאיר היא,\u0004 שאמר בהמשך: \u0003הכחשה דבי תרי\u0004 \u0005[ש\u0006מכחיש עדות \u0005של שנים]\u0006 \u0003לאו הכחשה היא, אבל לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 החולקים עליו, הוא \u0003פטור.\u0004","ושואלים: לדרך זו, שמדובר בתחילת המשנה שהוא מכחיש שני עדים, \u0003ומאי קמשמע לן\u0004 \u0005[ומה משמיע לנו\u0006 התנא\u0005]\u0006 בהלכה זו? הלוא \u0003מסיפא שמעת מינה\u0004 \u0005[מן הסוף שומע אתה]\u0006 אותה במפורש! ומשיבים, \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 בסיפא: \u0003דבר זה\u0004 ששנינו בראש המשנה, שאם אמרו לו שנים שאכל חלב מביא חטאת, הוא \u0003מחלוקת ר' מאיר ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003והוא\u0004 עוסק במקרה \u0003דקמכחיש להו\u0004 \u0005[שמכחיש אותם].\u0006 זהו מהלך אחד של סוגיית הגמרא.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן אחר: \"\u0003אמרו לו\" נמי\u0004 \u0005[גם כן]\u0006 \u0003חד קרי ליה\u0004 \u0005[אחד קוראים לו],\u0006 שלפעמים על עד אחד אומרים \"אמרו לו\", וכפי \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]: האשה שהלך בעלה למדינת הים, ובאו ואמרו לה: מת בעליך, ונישאת,\u0006 \u0003ואחר כך בא בעלה\u0004 — \u0003תצא מזה ומזה,\u0004 מבעלה הראשון ומזה שנישאה לו, \u0003דקיימא לן\u0004 \u0005[שמוחזק בידינו]\u0006 ש\"אמרו לו\" של משנה זו הוא \u0003אפילו בחד\u0004 \u0005[באחד].\u0006","\u0003ממאי\u0004 \u0005[ממה,\u0006 מהיכן\u0005]\u0006 אתה יודע דבר זה? \u0003מדקתני סיפא\u0004 \u0005[ממה שהוא שונה בסוף]:\u0006 \u0003נישאת שלא ברשות\u0004 — \u0003מותרת לחזור לו\u0004 לבעל הראשון. והרי \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003שלא ברשות\u0004 האמור כאן — \u0003שלא ברשות בית דין ועד אחד,\u0004 שלא הוצרכה לרשות מיוחדת של בית דין להינשא, מפני שהיו לה שני עדים שמת בעלה;","\u0003מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[שבתחילה],\u0006 שתצא מזה ומזה, מדובר \u0003ברשות\u0004 שקיבלה מ\u0003בית דין ובעד אחד,\u0004 שעל פיו התירוה בית דין להינשא. \u0003אלמא\u0004 \u0005[מכאן]\u0006 שלגבי \u0003עד אחד קתני\u0004 \u0005[שונה\u0006 התנא\u0005]\u0006 במשנה זו לשון \u0003\"אמרו\", ו\u0004לפי זה, \u0003הכא נמי דקתני\u0004 \u0005[כאן גם כן,\u0006 במשנתנו, \u0005שהוא שונה]\u0006\u0003 \"אמרו לו\", משמע אפילו עד אחד,\u0004 שמחייב אותו חטאת.","ומתקשים: \u0003והוא\u0004 עצמו, \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 \u0003אלימא דקא מכחיש ליה\u0004 \u0005[אם תאמר שהוא מכחיש אותו,\u0006 את העד\u0005], מי מייתי\u0006 \u0005[האם הוא מביא\u0006 קרבן\u0005]? והא קתני מציעתא\u0006 \u0005[והרי הוא שונה ב\u0006הלכה \u0005האמצעית]:\u0006 \u0003עד אחד אומר: אכל, והוא אומר: לא אכלתי\u0004 — \u0003פטור!\u0004","\u0003אלא\u0004 תאמר שמדובר במקרה \u0003דשתיק\u0004 \u0005[שהוא שותק]\u0006 — הלוא \u0003ממציעתא שמע מינה\u0004 \u0005[מ\u0006ההלכה \u0005האמצעית אתה יכול ללמוד את זאת],\u0006 שהרי הוא שונה, \u0003עד אחד אומר:\u0004 אכלת, והוא אומר: לא אכלתי — פטור. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה \u0003דקא מכחיש ליה\u0004 \u0005[שהוא מכחיש אותו]\u0006 — פטור, \u0003אבל שתק מישתק\u0004 \u0005[כשהוא שותק]\u0006 — \u0003חייב,\u0004 ולא הוצרכנו לתחילת המשנה!","ומשיבים: לעולם תפרש שמדובר בתחילת המשנה במקרה \u0003דלא מכחיש ליה\u0004 \u0005[שאינו מכחיש אותו],\u0006 אלא שותק. \u0003והכי קתני\u0004 \u0005[וכך הוא שונה]:\u0006 \u0003אמרו לו\u0004 (אפילו אחד): \u0003אכלת חלב\u0004 — \u0003מביא חטאת,\u0004 וממשיכה המשנה בהלכה האמצעית: \u0003במה דברים אמורים\u0004 — \u0003דשתיק\u0004 \u0005[\u0006במקרה \u0005ששותק]\u0006 מול העד, \u0003אבל\u0004 אם הוא \u0003מכחיש ליה\u0004 \u0005[אותו]\u0006 — \u0003פטור.\u0004","ושואלים: \u0003ומדאורייתא מנלן דלא מכחיש ליה\u0004 \u0005[ומן התורה מניין לנו\u0006 שבמקרה \u0005שאינו מכחיש אותו,\u0006 את העד\u0005]\u0006 הריהו \u0003חייב\u0004 חטאת? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בענין חיוב קרבן חטאת: \u0003\"או הודע אליו חטאתו\"\u0004 (ויקרא ד, כח) — שנודע לו מאליו, מעצמו, \u0003ולא שיודיעוהו אחרים; יכול\u0004 שאינו מתחייב בחטאת על פי אחרים, \u0003אפילו אין\u0004 הוא \u0003מכחישן? תלמוד לומר: \"או הודע אליו\"\u0004 לומר — \u0003מכל מקום,\u0004 אפילו הודיעוהו אחרים הוא מתחייב, כשאינו מכחישם אלא שותק.","ונברר: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 \u0003אלימא בתרין\u0004 \u0005[אם תאמר\u0006 שמדובר בשנים], וכי \u0003תרין\u0004 \u0005[שנים]\u0006 \u0003ואין מכחישן קרא בעי\u0004 \u0005[צריך פסוק]\u0006 לומר שהוא חייב?"],["\u0003אלא לאו בחד\u0004 \u0005[האם לא\u0006 מדובר \u0005באחד],\u0006 \u0003וקתני\u0004 \u0005[והוא שונה]\u0006 \u0003כי אין מכחישן מהימן\u0004 \u0005[\u0006ש\u0005כאשר אינו מכחישם,\u0006 אלא שותק, \u0005הרי הוא נאמן],\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה שאם אמרו לו שניים אכלת חלב, והוא אומר: לא אכלתי — ר' מאיר מחייב. \u0003אמר ר' מאיר: קל וחומר,\u0004 אם הביאו שנים למיתה חמורה לא יביאוהו לקרבן הקל? אמרו לו: מה אם ירצה לומר \"מזיד הייתי\" — ייפטר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה\u0006 עיקר \u0005טעמם של חכמים]\u0006 שפוטרים מקרבן? האם הוא \u0003משום\u0004 שהם סוברים שאדם \u0003נאמן על עצמו\u0004 לענין זה \u0003יותר ממאה איש, או דלמא\u0004 \u0005[שמא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003מיגו דאי בעי אמר\u0004 \u0005[מתוך שאם היה אומר]\u0006\u0003 \"מזיד הייתי\"\u0004 — היה \u0003פטור\u0004 מקרבן, \u0003כי אמר נמי\u0004 \u0005[כאשר הוא אומר גם כן] \"\u0006\u0003לא אכלתי\"\u0004 — \u0003מהימן ופטור?\u0004","ושואלים: \u0003ומאי נפקא מינה\u0004 \u0005[ומה\u0006 ההבדל למעשה \u0005היוצא מזה]?\u0006 שהרי לכאורה מסקנתם אחת היא! ומשיבים: \u0003למיפשט מינה\u0004 \u0005[לפתור ממנה]\u0006 מה יהיה הדין \u0003ל\u0004ענין \u0003טומאה,\u0004 כאשר עדים מעידים עליו שנטמא קודם שנכנס למקדש, והוא אומר: לא נטמאתי, \u0003דאי אמרת טעמייהו דרבנן\u0004 \u0005[שאם אתה אומר\u0006 ש\u0005טעמם של חכמים]\u0006 \u0003משום\u0004 שאדם \u0003נאמן על עצמו יותר ממאה איש\u0004 — \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם הוא מכחיש אותם לגבי \u0003טומאה חדשה,\u0004 שאומרים לו: עכשיו נטמאת, \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 בטומאה \u0003ישנה\u0004 שאומרים לו: אתמול נטמאת, שבכל אופן הוא נאמן על עצמו.","אבל \u0003אי אמרת טעמיהון דרבנן\u0004 \u0005[אם אומר אתה שטעמם של חכמים]\u0006 \u0003משום דאמר \"מיגו\"\u0004 \u0005[שיכול לומר \"מתוך\"]\u0006 \u0003היא\u0004 — \u0003פטרי ליה רבנן\u0004 \u0005[פוטרים אותו חכמים]\u0006 \u0003מטומאה ישנה, אבל מטומאה חדשה מחייב. מאי טעמא\u0004 \u0005[מה טעם\u0006 של דבר\u0005]\u0006\u0003? ט ומאה ישנה, מיגו דאי בעי אמר\u0004 \u0005[מתוך שאם היה רוצה לומר]:\u0006 אמנם נטמאתי אבל \u0003טבלתי\u0004 אחר כך — היה \u0003פטור, כי אמר נמי\u0004 \u0005[כאשר הוא אומר גם כן] \"\u0006\u0003לא נטמאתי\"\u0004 — הרי הוא \u0003פטור, דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]:\u0006 \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"לא נטמאתי\" דקאמר\u0004 \u0005[שהוא אומר]\u0006 — \u0003לא עמדתי בטומאתי אלא טבלתי.\u0004","\u0003אבל\u0004 אם מעידים בו על \u0003טומאה חדשה\u0004 — \u0003מחייב\u0004 \u0005[חייב],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]? דכי אמר נמי\u0006 \u0005[ש\u0006הרי \u0005גם כאשר\u0006 הוא \u0005אומר]\u0006\u0003 \"טבלתי\"\u0004 — \u0003מחייב\u0004 \u0005[חייב],\u0006 \u0003דאמרו ליה\u0004 \u0005[שאומרים לו]\u0006 ה\u0003עדים:\u0004 אמנם טבלת קודם, אבל \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003נטמאת.\u0004","ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 טעמם של חכמים? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003אמר לו עד אחד: נטמאת, והוא אומר: לא נטמאתי\u0004 — הרי הוא \u0003פטור; יכול אפילו שנים\u0004 אומרים לו? \u0003אמר ר' מאיר:\u0004 חייב הוא, מ\u0003קל וחומר, אם הביאוהו שנים\u0004 אפילו \u0003למיתה חמורה, לא יביאוהו לידי קרבן הקל? וחכמים אומרים: אדם נאמן על עצמו יותר ממאה איש. שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003טעמייהו דרבנן\u0004 \u0005[טעמם של חכמים]\u0006 הוא \u0003משום דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003אדם נאמן על עצמו יותר ממאה איש.\u0004","\u0003אמר ר' אמי:\u0004 אין להוכיח מכאן, \u0003לעולם\u0004 אפשר לומר כי \u0003טעמא דרבנן\u0004 \u0005[טעמם של חכמים]\u0006 הוא \u0003משום דאמרינן \"מיגו\"\u0004 \u0005[שאנו אומרים \"מתוך\"],\u0006 \u0003והכי קתני\u0004 \u0005[וכך הוא שונה]\u0006 בברייתא לשיטתם: \u0003מתוך שאם רצה לומר: לא עמדתי בטומאתי,\u0004 אלא טבלתי — היה \u0003פטור, הילכך\u0004 \u0005[על כן]\u0006 \u0003אדם נאמן על עצמו יותר ממאה איש.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 אותו דבר כמו בדין אכילת \u0003חלב,\u0004 ששנינו במשנתנו: מה אם ירצה לומר \"מזיד הייתי\" פטור, ולא הוצרך להשמיענו שוב דין זה!","ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 כשאומר \"לא \u0003אכלתי חלב\"\u0004 יש לו \"מיגו\", שכן \u0003קמתריץ דיבוריה\u0004 \u0005[מתרץ את דיבורו\u0006 הראשון\u0005],\u0006 שמה שאמר \"לא אכלתי\" כוונתו: \u0003לא אכלתי שוגג אלא מזיד, אבל\u0004 כשאומרים לו שנים: \u0003נטמאת, והוא אומר: לא נטמאתי, אימא לא קמתריץ דבוריה\u0004 \u0005[אמור שאינו מתרץ את דיבורו],\u0006 ואינו נאמן, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לתרץ דיבורו ולומר: \u0003לא עמדתי בטומאתי אבל טבלתי.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מה היא דעת חכמים, מברייתא אחרת, ששנינו בענין המטמא מקדש וקדשיו בשגגה: \"והיה כי יאשם לאחת מאלה \u0003והתודה...\u0004 והביא את אשמו\" (ויקרא ה, ה—ו), \u0003מודה בדברים\u0004 — \u0003חייב\u0004 בקרבן, \u0003אין מודה בדברים\u0004 — \u0003פטור.\u0004 ולכן, אם \u0003אמר לו עד אחד: נטמאת, והוא אומר: לא נטמאתי\u0004 — \u0003פטור;\u0004","\u0003יכול אפילו שנים מכחישין\u0004 אותו יהא פטור? \u0003אמר ר' מאיר: אם הביאוהו שנים לידי מיתה חמורה, לא יביאוהו לידי קרבן הקל?\u0004 אלא בוודאי חייב. ר' יהודה אומר: נאמן אדם על עצמו יותר ממאה איש.","\u0003ומודים חכמים\u0004 (והם החכמים שבמשנתנו) \u0003לר' יהודה, ב\u0004אכילת \u0003חלבין ובביאת מקדש\u0004 בטומאה, שאם העידו בו שניים שאכל חלב, או שנכנס למקדש כשהוא טמא, והוא טוען: לא אכלתי, או: לא נכנסתי למקדש — שהוא פטור. \u0003אבל בטומאה,\u0004 אם העידו בו שנטמא קודם שאכל בקדשים, והוא אומר: לא נטמאתי — \u0003לא מודו ליה\u0004 \u0005[אין\u0006 חכמים \u0005מודים לו],\u0006 אלא סבורים הם כר' מאיר, ששני עדים מביאים אותו לידי קרבן. הרי שלשיטתם אין אדם נאמן על עצמו מול עדים במקום שאין לו \"מיגו\".","ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]?\u0006 באיזו טומאה אינו נאמן לדעתם? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006"],["\u0003בטומאה ישנה,\u0004 שאמרו לו: נטמאת אתמול, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 אכילת \u0003חלבין וביאת מקדש דמודו ליה\u0004 \u0005[שמודים לו]\u0006 חכמים לר' יהודה שאין מחייבים אותו קרבן, מפני שיש לו \"מיגו\", ש\u0003אם רצה יאמר: מזיד הייתי,\u0004 וניתן לתרץ את דבריו, שאמר: לא אכלתי בשוגג אלא במזיד, וכן לא באתי למקדש בשוגג אלא במזיד, והרי \u0003טומאה ישנה נמי מתרץ דיבוריה\u0004 \u0005[גם כן\u0006 יכול לתרץ את דיבורו] הראשון, ש\u0003אם רצה יאמר: לא עמדתי בטומאתי אלא טבלתי!\u0004","\u0003אמר רבינא: לעולם\u0004 יכול אתה להסביר כי מדובר \u0003בטומאה ישנה,\u0004 ומכל מקום אין בה \"מיגו\", \u0003וכגון דאמרי ליה\u0004 \u0005[שאומרים לו]\u0006 \u0003עדים: אכלת קדשים בטומאת הגוף, והוא אמר להון\u0004 \u0005[אומר להם]:\u0006 \u0003לא נטמאתי, דהכא לא מתריץ דיבוריה\u0004 \u0005[שכאן לא ניתן לתרץ את דיבורו].\u0006 \u0003דליכא למימר\u0004 \u0005[שאין לומר]\u0006 ש\"לא נטמאתי\" משמעו \u0003לא עמדתי בטומאה אבל טבלתי,\u0004 שהרי כאשר הוא בא לפטור עצמו מקרבן שחייבוהו העדים על אכילת קדשים בטומאה,","\u0003מאי אמר להון\u0004 \u0005[מה הוא אומר להם]?\u0006 \u0003טבלתי ואכלתי,\u0004 והרי \u0003כי אמר להון הכי\u0004 \u0005[כאשר הוא אומר להם כך],\u0006 \u0003איתכחש ליה דבוריה קמא מיהא\u0004 \u0005[הוכחש לו דיבורו הראשון על כל פנים]\u0006 \u0003בטומאת מגעו,\u0004 כלומר, מה שאמר שלא נגע בטומאה.","\u0003אמר רב נחמן: הלכה כר' יהודה,\u0004 שאפילו העידו בו עדים שנטמא והוא אומר: לא נטמאתי — נאמן אדם על עצמו יותר ממאה עדים. \u0003אמר רב יוסף: לא אמרה\u0004 ר' יהודה \u0003אלא בינו לבין עצמו,\u0004 שמותר לו לאכול בקדשים או בטהרות, אבל לא בפני אחרים, \u0003ו\u0004כן \u0003לעצמו\u0004 הוא נאמן, אבל לא לגבי אחרים.","\u0003אמר ריש לקיש:\u0004 אף שאמר ר' מאיר במשנתנו שאם אמרו לו שניים: אכלת חלב — אינו נאמן לומר: לא אכלתי, \u0003מודה ר' מאיר לחכמים, שאם אמרו לו שנים: בעלת שפחה חרופה, והוא אומר: לא בעלתי\u0004 — \u0003מהימן\u0004 \u0005[נאמן],\u0006 לפי \u0003דאי בעי אמר להון\u0004 \u0005[שאם רוצה יכול היה לומר להם]:\u0006 \u0003לא גמרתי ביאתי.\u0004","ובדומה לכך \u0003אמר רב ששת: מודה ר' מאיר לחכמים בנזיר טמא, שאמרו לו שנים: נטמאת\u0004 למת, וחייב אתה קרבן, \u0003והוא אומר: לא נטמאתי\u0004 — \u0003פטור, דאי בעי אמר\u0004 \u0005[שאם רוצה יכול לומר]:\u0006 \u0003נשאלתי\u0004 לחכם \u0003על נזירי\u0004 (נדר נזירותי), והתיר את נדרי, ומותר היה לי להיטמא.","וכיוצא בזה \u0003אמר אביי: מודה ר' מאיר לחכמים, שאם אמרו לו שנים: יודע אתה בעדות\u0004 על \u0003פלוני, והוא אומר: לא ידעתי\u0004 ונשבע על כך — \u0003פטור\u0004 מקרבן על שבועת העדות, \u0003דאי בעי אמר\u0004 \u0005[שאם היה רוצה היה אומר]:\u0006 \u0003לא נתכוונתי לעדות\u0004 בשעה שראיתי את הדבר, ובמקרה זה פטור מן הקרבן.","שנינו במשנה: \u0003אכל חלב ו\u0004שוב אכל \u0003חלב,\u0004 אם היה זה \u0003בהעלם אחת,\u0004 שלא נודע לו בינתיים שהוא חלב — אינו חייב אלא חטאת אחת על שתי האכילות. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006\u0003 ר' זירא: אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו חייב אלא חטאת אחת? והא\u0004 \u0005[והרי]\u0006 \u0003שני זיתי חלב אכל!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 לגבי חיוב חטאת דווקא \u0003העלמות מחולקות\u0004 (מחלקות), שנעלם ממנו האיסור ונודע לו, ושוב נעלם ממנו, שנאמר: \"או הודע אליו חטאתו... והביא את קרבנו\" (ויקרא ד, כח). \u0003ו\u0004אילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003העלם אחד הוא דאיכא\u0004 \u0005[שישנו].\u0006","\u0003איכא דמקשי ליה הכי\u0004 \u0005[יש שמקשים\u0006 דבר \u0005זה כך]\u0006 בשם ר' זירא: מן המשנה יש לדייק כי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 כשאכל חלב ושוב אכל חלב ב\u0003העלם אחת\u0004 חייב חטאת אחת, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003בשתי העלמות חייב שתים,\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 והלוא \u0003שם\u0004 (איסור) \u0003חלב אחד הוא! אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 לענין חטאת \u0003העלמות מחולקין.\u0004","שנינו במשנה: \u0003אכל חלב ודם פיגול ונותר\u0004 בהעלם אחת — \u0003חייב\u0004 על כל אחת ואחת. ועוד שנינו: אכל כחצי זית וחזר ואכל כחצי זית, ממין אחד — חייב.","ותוהים: \u0003ממין אחד חייב, פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שהרי אכל כזית מן האיסור! \u0003אמר ריש לקיש משום בר תוטיני:\u0004 מדובר \u0003כגון שאכלו\u0004 את כזית החלב כשהוא מחולק \u0003בשני תמחויין\u0004 (כלים) שונים, \u0003ואליבא\u0004 \u0005[ולפי שיטתו]\u0006 של ר' \u0003יהושע,\u0004 שאמר: \u0003תמחויין מחולקין\u0004 (מחלקים).","והוצרך לכך, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יהושע\u0004 תמחויין מחלקין — \u0003לא שנא לקולא\u0004 \u0005[אינו שונה להקל],\u0006 כגון במקרה שלנו, שאם אכל כזית שהוא מחולק בשני תמחויים — פטור, \u0003ולא שנא לחומרא\u0004 \u0005[ואינו שונה להחמיר],\u0006 וכגון שאם אכל שני כזיתים בשני תמחויים שונים — חייב שתי חטאות, למרות שאכלם בהעלם אחד, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 כאן שאם אכל כזית כשהוא מחולק לתמחויים \u0003חייב, אלמא\u0004 \u0005[מכאן]\u0006 \u0003אנו למדים שלחומרא\u0004 \u0005[להחמיר]\u0006 \u0003אמר, לקולא\u0004 \u0005[להקל]\u0006 \u0003לא אמר.\u0004","\u0003איכא דאמר\u0004 \u0005[יש שאומר]\u0006 שדבר זה נאמר \u0003על סיפא\u0004 \u0005[סופה]\u0006 של המשנה: אכל כחצי זית וחזר ואכל כחצי זית... \u0003משני מינין\u0004 — \u0003פטור.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהוא פטור, שהרי לא אכל כזית שלם של איסור אחד! \u0003אמר ריש לקיש משום בר תוטיני:\u0004 אין מדובר בשני מינים, אלא בכזית ממין אחד, ו\u0003כגון שאכלו בשני תמחויין, ואליבא\u0004 \u0005[ולפי שיטתו]\u0006 של ר' \u0003יהושע,\u0004 שאמר: \u0003תמחויין מחולקין.\u0004","\u0003דמהו דתימא\u0004 \u0005[שמהו שתאמר]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יהושע\u0004 שתמחויים מחלקים — \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003אמר,\u0004 שאם אכל שני כזיתים בשני תמחויים שונים חייב שתי חטאות. אבל \u0003לקולא\u0004 \u0005[להקל]\u0006 \u0003לא אמר,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאם אכל כזית \u0003משני מינין פטור,\u0004 וכפי שהסברנו:","\u0003מאי\u0004 \u0005[מהו]\u0006 \u0003משני מינין\u0004 — \u0003ממין אחד הוא, ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003שני מינים\u0004 — \u0003משום\u0004 שאכלו \u0003בשני תמחויין,\u0004 כחצי זית בכל תמחוי, \u0003וקתני\u0004 \u0005[והוא שונה]:\u0006 \u0003פטור, אלמא\u0004 \u0005[מכאן]\u0006 שלא \u0003שנא לקולא ולא שנא לחומרא\u0004 \u0005[לא שונה להקל ולא שונה להחמיר]\u0006 \u0003קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יהושע\u0004 שתמחויים מחלקים, ואפילו היו שני חצאי הזית ממין אחד, ואכלם בהעלם אחד — פטור.","ומתקשים: \u0003מדסיפא\u0004 \u0005[מתוך שבסוף],\u0006 מה ששנינו \"משני מינים\" כוונתו \u0003מין אחד ושני תמחויין,\u0004 נמצא כי \u0003רישא\u0004 \u0005[ההתחלה]\u0006 של דין זה, ששנינו בה \"ממין אחד\" כוונתה שני חצי כזית מ\u0003מין אחד ותמחוי אחד,\u0004 שחייב חטאת על אכילתם. והלוא דבר זה \u0003פשיטא\u0004 \u0005[פשוט],\u0006 ולא הוצרך לאומרו!","\u0003אמר רבינא:\u0004 מדובר \u0003כגון שהיתה לו ידיעה בינתיים,\u0004 שאכל כחצי זית ונודע לו שאכל חלב, ושוב נעלם ממנו האיסור, וחזר ואכל כחצי זית, \u0003ואליבא\u0004 \u0005[ו\u0006הוא \u0005לפי שיטתו]\u0006 של \u0003רבן גמליאל,\u0004 שאמר: \u0003אין ידיעה לחצי שיעור,\u0004 שאם לאחר שחטא בשגגה בחצי שיעור נודע לו שחטא, ושוב נעלם ממנו האיסור וחטא — אין הידיעה שבאמצע מחלקת אותו לשתי שגגות שונות, אלא כאילו חטא בהעלם אחד.","\u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003הכותב\u0004 בשבת \u0003שתי אותיות בשתי העלמות\u0004 שונות, \u0003אחת שחרית ואחת ערבית\u0004 — \u0003רבן גמליאל מחייב\u0004 משום מלאכת כתיבה, ששיעורה שתי אותיות, \u0003וחכמים פוטרין;\u0004 וטעם מחלוקתם,","\u0003רבן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003אין ידיעה לחצי שיעור,\u0004 ולכן גם אם נודע לו האיסור לאחר כתיבת אות אחת — אין ידיעה זו נחשבת לחלק בינה לבין הכתיבה של האות השניה, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003יש ידיעה\u0004 גם \u0003לחצי שיעור.\u0004","\u0003כמה ישהא באוכלין\u0004 ויתחייב משום אכילת כזית איסור? \u0003כאילו אוכל קליות\u0004 (גרעינים קלויים) שאוכל אותן אחת אחת, \u0003דברי ר' מאיר. וחכמים אומרים: עד שישהא מתחלה ועד סוף כדי אכילת פרס\u0004 (חצי ככר לחם) — \u0003חייב.\u0004","ושיעור זה נוגע למי ש\u0003אכל אוכלין טמאין ושתה משקין טמאין,\u0004 שאם אכל כחצי פרס (רבע ככר) אוכלים טמאים, או שתה רביעית משקים טמאים בתוך זמן של אכילת פרס — נפסל מאכילת תרומה עד שייטהר. ועוד, \u0003שתה רביעית יין ונכנס למקדש ושהה כדי אכילת פרס\u0004 — \u0003חייב, ר' אליעזר אומר: אם פסק בה,\u0004 עשה הפסקות בשתיית רביעית היין, \u0003או אם נתן בו מים כל שהוא\u0004 — \u0003פטור.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006\u0003: ר' מאיר\u0004 שאמר שמשערים את אכילת האיסורים כאילו אוכל קליות, \u0003לחומרא קאמר או לקולא קאמר\u0004 \u0005[להחמיר הוא אומר או להקל הוא אומר]?\u0006 ומפרטים: \u0003לחומרא קאמר\u0004 \u0005[להחמיר הוא אומר],\u0006 \u0003והכי קתני\u0004 \u0005[וכך הוא שונה]:\u0006 רואים אותו \u0003כאילו אוכל קליות\u0004 מעט מעט, \u0003אפילו\u0004 נמשכת אכילת כזית מן האיסור \u0003כוליה יומא\u0004 \u0005[כל היום].\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שמתחלה \u0003ועד סוף\u0004 של אכילת כזית איסור יש \u0003יותר מכדי אכילת פרס, כיון דמשכיה אכילתיה\u0004 \u0005[שנמשכה אכילתו]\u0006 ולא הפסיק בה — הרי הוא \u0003מחייב\u0004 \u0005[חייב].\u0006 \u0003ואמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 \u0003עד שישהא\u0004 באכילת כזית \u0003בכדי אכילת פרס הוא\u0004 ש\u0003יייב,\u0004 אבל אם שהה \u0003יותר מכדי אכילת פרס\u0004 באכילת כזית — הרי הוא \u0003פטור.\u0004","\u0003או דלמא לקולא קאמר\u0004 \u0005[שמא להקל הוא אומר],\u0006 \u0003דהכי קתני\u0004 \u0005[שכך הוא שונה]:\u0006 מתי הוא מתחייב על אכילת כזית האיסור — \u0003כאילו אוכל קליות,\u0004 וכוונתו: \u0003והוא\u0004 שלא \u0003איפסיק ביני וביני\u0004 \u0005[הפסיק\u0006 אכילתו \u0005בין לבין],\u0006 אלא אכל ברצף, \u0003אבל\u0004 אם \u0003איפסיק ביני וביני\u0004 \u0005[הפסיק בין לבין],\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שמתחלה \u0003ועד סוף\u0004 היה \u0003בכדי אכילת פרס\u0004 — \u0003פטור. ואמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 \u0003כיון\u0004 ש\u0003מתחלה ועד סוף בכדי אכילת פרס הוא\u0004 — \u0003חייב,\u0004 למרות שהפסיק באכילתו?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003וחכמים אומרים: עד שישהא בכדי אכילת פרס מתחלה ועד סוף.\u0004"],["\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שר' \u0003מאיר לחומרא\u0004 \u0005[\u0006בא להחמיר], ומחייב אפילו נמשכה אכילתו כל היום — \u0003היינו דקתני\u0004 \u0005[זהו שהוא שונה]\u0006 בדברי חכמים: \u0003\"עד שישהא\",\u0004 כלומר, אינו חייב \u0003עד דשהי דיליה\u0004 \u0005[שהשהייה שלו]\u0006 מתחילה ועד סוף היא \u0003כדי אכילת פרס,\u0004 ולא יותר מכך.","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כי \u0003ר' מאיר לקולא\u0004 \u0005[\u0006בא \u0005להקל]\u0006 ולומר שכל שהפסיק באכילה פטור, ואם כן, \u0003\"וחכמים אומרים: אם שהה\u0004 כדי אכילת פרס — פטור\" \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 אבל שהה פחות מכך — חייב אפילו אם הפסיק! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שר' \u0003מאיר לחומרא\u0004 \u0005[\u0006בא \u0005להחמיר]?\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רבנאי אמר שמואל: ב\u0004אכילת \u0003חלבים וב\u0004אכילת \u0003נבילה\u0004 — חייב על אכילת כזית ואפילו בהפסקות, \u0003עד שישהא מתחלה ועד סוף בכדי אכילת פרס,\u0004 ולא יותר, וכדברי חכמים במשנתנו. אם אכל \u0003אוכלים טמאים\u0004 בשיעור חצי פרס (רבע ככר), או \u0003שקצים ורמשים,\u0004 או שתה \u0003משקין\u0004 טמאים בשיעור רביעית — נטמא גופו, ואסור באכילת טהרות, \u0003אפילו\u0004 נמשכה אכילתם \u0003כל היום כולו בכדי אכילת פרס.\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 מה משמעות הדברים הללו? \u0003אמר רב פפא, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אפילו\u0004 נמשכה אכילתם \u0003כל היום כולו\u0004 נטמא גופו, \u0003והוא שאכל\u0004 כל \u0003כזית\u0004 מהם \u0003בכדי אכילת פרס.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003כל האוכלין\u0004 הטמאים \u0003מצטרפין\u0004 זה עם זה \u0003לפסול הגוייה\u0004 (את גופו) מלאכול תרומה, אם היה בהם יחד \u0003בכחצי פרס; מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003דאכליה\u0004 \u0005[שאכלו]\u0006 את \u0003חצי פרס בכדי\u0004 בזמן של שיעור \u0003אכילת פרס?\u0004 ודוחים: \u0003לא,\u0004 שאכל כל \u0003כזית\u0004 ו\u0003כזית\u0004 מאותו חצי פרס \u0003בכדי אכילת פרס.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003כל האוכלין מצטרפין לפסול את הגוייה בכחצי פרס בכדי אכילת פרס, כיצד? אכל וחזר ואכל, אם יש מתחלת אכילה ראשונה ועד סוף אכילה אחרונה כדי\u0004 שיעור \u0003אכילת פרס\u0004 — הרי אלו \u0003מצטרפין, יותר מכאן\u0004 — \u0003אין מצטרפין.\u0004","וממשיכה הברייתא בענין טומאת אוכלים: \u0003לא התירו לאכול\u0004 (לאוכל) אוכלים טמאים \u0003פחות מכשיעור\u0004 (כחצי פרס) \u0003לירד ולטבול,\u0004 אם \u0003ירד וטבל ועלה והשלימו\u0004 לשיעור כחצי פרס — הרי זה \u0003מצטרף\u0004 לפסול את הגויה, אף על פי שטבל בין שתי האכילות. \u0003התירו לה לעוברה\u0004 (אשה מעוברת) \u0003לאכול פחות מכשיעור, מפני הסכנה,\u0004 שמא תפיל.","\u0003כל המשקין\u0004 הטמאים \u0003מצטרפין לפסול את הגוייה\u0004 מלאכול תרומה, \u0003ברביעית\u0004 הלוג, אם שותה אותה \u0003בכדי אכילת פרס, כיצד? שתה וחזר ושתה,\u0004 ויש בכל השתיות יחד רביעית, \u0003אם יש מתחלת שתיה ראשונה ועד סוף שתיה אחרונה\u0004 שיעור זמן \u0003כדי אכילת פרס\u0004 — \u0003מצטרפין, יותר מכאן\u0004 — \u0003אין מצטרפין.\u0004","\u0003הותרו\u0004 (התירו) \u0003לה ל\u0004אישה שהיא \u0003מגע טמא מת,\u0004 כלומר, שנגעה במי שנגע במת, שהוא אב הטומאה, ונעשתה ראשון לטומאה, \u0003להניק בנה, ובנה\u0004 נשאר \u0003טהור\u0004 ואינו פוסל תרומה, למרות שלכאורה ינק חלב שכבר נטמא כשיצא מגופה של אמו. עד כאן לשון הברייתא.","\u0003קתני מיהת\u0004 \u0005[הריהו שונה על כל פנים]\u0006 לענין אוכלים טמאים: \u0003אם יש מתחלת אכילה ראשונה ועד סוף אכילה\u0004 אחרונה \u0003בכדי אכילת פרס\u0004 — \u0003מצטרף\u0004 לפסול את גופו. הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבנאי,\u0004 שאמר שדי שיאכל כל כזית וכזית בכדי אכילת פרס! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו דבריו.","וממשיכים לדון בפרטי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003לא התירו לו לאכול\u0004 (למי שאוכל) אוכלים טמאים \u0003פחות מכשיעור לירד ולטבול.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 מדוע לא התירו לו?","\u0003אמר רב יהודה, הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אכל פחות מכשיעור\u0004 — \u0003לא התירו לו לירד ולטבול,\u0004 לפי \u0003שאם ירד וטבל ועלה והשלימו\u0004 בכדי אכילת פרס — \u0003מצטרף\u0004 הכל לפוסלו מאכילת תרומה. \u0003ו\u0004אם לא נאסור עליו לטבול בתחילה \u0003אתי למימר\u0004 \u0005[ויבוא לומר]:\u0006 \u0003אהני לי טבילה קמייתא\u0004 \u0005[הועילה לי הטבילה הראשונה]\u0006 על חצי השיעור, ועל חצי השיעור הנוסף איני צריך טבילה, \u0003ואין\u0004 הוא \u0003יודע שאין טבילה\u0004 מועילה לו להיטהר \u0003אלא באחרונה.\u0004","ועוד \u0003קתני\u0004 \u0005[שונה]\u0006 התנא בברייתא: \u0003התירו לה לעוברה לאכול\u0004 איסור \u0003פחות מכשיעור מפני הסכנה.\u0004 ומבינים כי הכוונה היא שכל שהותר לה לאכול הוא פחות מכשיעור. ותוהים: אם \u0003מפני הסכנה, אפילו טובא נמי תיכול\u0004 \u0005[הרבה גם כן שתאכל]!\u0006 \u0003אמר רב פפא, הכי קתני\u0004 \u0005[כך שנה]:\u0006 \u0003הותרו לה לעוברה\u0004 לאכול \u0003פחות מכשיעור\u0004 כלומר, בפחות מכזית בכדי אכילת פרס, \u0003אפילו\u0004 אוכלת \u0003טובא\u0004 \u0005[הרבה],\u0006 \u0003מפני הסכנה.\u0004","ועוד \u0003קתני\u0004 \u0005[שונה]\u0006 התנא בברייתא: \u0003התירו ל\u0004אשה שנטמאה ב\u0003מגע טמא מת להניק את בנה, ובנה טהור,\u0004 ורשאים להאכילו תרומה. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהיה \u0003טהור? כיון\u0004 ש\u0003יינק חלב איטמי ליה\u0004 \u0005[נטמא לו]\u0006 מן ה\u0003חלב!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שחלב זה, שהוא מאכל התינוק, \u0003לא איתכשר\u0004 \u0005[הוכשר\u0006 לקבל טומאה\u0005],\u0006 ואין אוכל מקבל טומאה אלא אם הוכשר במשקה — הלוא \u0003נתכשר בטיפה מלוכלכת\u0004 שנשארת \u0003על פי הדד,\u0004 שאינה מיועדת למאכל התינוק, אלא דין משקה יש לה, והיא מכשירה את החלב שיוצא לאחר מכן לקבל טומאה! \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 מדובר שינק \u0003בתקיפה\u0004 (במשיכה) \u0003אחת,\u0004 ולא \u0003הניח טיפה מלוכלכת על פי הדד,\u0004 שתכשיר את החלב היוצא לאחר מכן.","\u0003אמר רבא, שתי תשובות בדבר\u0004 לדחות הסבר זה: \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003דקחזינא לפומיה דינוקא\u0004 \u0005[שרואים אנו את פי התינוק]\u0006 שהוא \u0003מלא חלב,\u0004 ולכן לא יכול להיות שינק בלא שתיוותר טיפה על הדד! \u0003ועוד,\u0004 גם אם לא נשארה טיפה על פי הדד, אין החלב צריך הכשר כאוכל כדי ליטמא ולטמא, שהרי \u0003מקום\u0004 ה\u0003חלב\u0004 באשה \u0003מעיין הוא,\u0004 והחלב נחשב כחלק מגוף האשה, וטמא כמוה, ואין לו דין רגיל של אוכל או משקה.","\u0003דקתני\u0004 \u0005[ש\u0006כך \u0005הוא שונה]\u0006 במשנה: \u0003חלב אשה מטמא\u0004 (מכשיר אוכל לקבלת טומאה) \u0003בין\u0004 שיצא \u0003לרצון\u0004 האשה או התינוק, \u0003ובין\u0004 שיצא \u0003שלא לרצון,\u0004 ואילו חלב \u0003בהמה אינה מטמא אלא לרצון;\u0004","\u0003מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 \u0003\"שלא לרצון\"\u0004 — אפילו \u0003דלא ניחא ליה\u0004 \u0005[שלא נוח לו],\u0006 שאינו רוצה בחלב? \u0003וקתני\u0004 \u0005[והוא שונה]\u0006 שהוא \u0003מטמא,\u0004 והרי אוכל אינו מוכשר לקבל טומאה אלא במשקה שיצא לרצון! אלא מכאן שאין דין החלב כדין אוכל ומשקה רגיל, ואינו צריך הכשר כדי ליטמא ולטמא, ואם כן חוזרת השאלה: מדוע התינוק טהור? והרי אכל דבר טמא!","\u0003אלא אמר רבא: היינו טעמא\u0004 \u0005[זה הטעם]\u0006 שבנה \u0003טהור\u0004 — מפני ש\u0003ספק ינק כשיעור\u0004 הראוי לפוסלו לאכילת תרומה, \u0003וספק לא ינק\u0004 כשיעור, \u0003ואם תמצא לומר\u0004 שוודאי \u0003ינק,\u0004 מכל מקום \u0003ספק ינקו\u0004 את החלב \u0003ב\u0004תוך כדי \u0003אכילת פרס, ספק ינקו ביותר מכדי אכילת פרס,\u0004 ואז אינו פוסל.","ושואלים: \u0003ולרבא,\u0004 האם \u0003מקום חלב מעיין הוא ולא צריך הכשר?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006\u0003: האשה\u0004 שהיא נדה \u0003שנטף חלב מדדיה ונפל\u0004 החלב \u0003לאויר תנור\u0004 — ה\u0003תנור טמא. וקשיא לן\u0004 \u0005[והיה קשה לנו]:\u0006 \u0003במאי איתכשר\u0004 \u0005[במה הוכשר]\u0006 חלב זה כדי שייטמא ויטמא? \u0003ואמר רבי יוחנן: בטיפה מלוכלכת על פי הדד.\u0004 הרי שר' יוחנן סבור שהחלב צריך הכשר!","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003רבא לא סבר לה\u0004 \u0005[אינו סבור] כ\u0006דעת ר' \u0003יוחנן,\u0004 ואמורא רשאי לחלוק על אמורא אחר, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003נמצאת אתה אומר, תשעה משקין בזוב\u0004 כלומר, לגבי הזב: \u0003הזיעה, וליחה סרוחה, וריעי\u0004 (צואה נוזלית) — הרי הם \u0003טהורין מכולם,\u0004 שאינם מטמאים, ואינם מכשירים לקבל טומאה. \u0003דמעת עינו\u0004 של הזב, \u0003ו\u0004כן \u0003דם מגפתו\u0004 (היוצא מפצעו),"],["\u0003וחלב אשה\u0004 זבה — \u0003מטמאין טומאת משקין ברביעית. רוקו\u0004 של הזב, \u0003זובו, ומימי רגליו\u0004 — \u0003מטמאין טומאה חמורה\u0004 כזב עצמו, \u0003בכל שהוא.\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כדברי רבא, ש\u0003מקום חלב מעיין\u0004 הוא, \u0003חלב\u0004 של זבה \u0003נמי נטמא\u0004 \u0005[גם כן יטמא]\u0006 \u0003טומאה חמורה בכל שהוא, כזובו ורוקו! אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מקום חלב אשה לאו מעיין הוא,\u0004 והחלב צריך הכשר כדי ליטמא ולטמא.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003קשיא הא מתניתא\u0004 \u0005[קשה משנה זו]\u0006 \u0003ואמר\u0004 והוכיח ממנה \u0003רבא\u0004 כשיטתו, ששנינו בה שחלב אשה \u0003מטמא בין לרצון ובין שלא לרצון,\u0004 והרי אוכל אינו מוכשר ליטמא אלא לרצון!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003\"שלא לרצון\" דאמר\u0004 \u0005[שאומר\u0006 התנא\u0005]\u0006 כוונתו — \u0003דלא ניחא ליה\u0004 \u0005[שלא נוח לו],\u0006 שאינו רוצה בחלב? \u0003לא, מאי\u0004 \u0005[מהו]\u0006 \u0003\"שלא לרצון\"\u0004 ש\u0003אמר\u0004 \u0005[\u0006ש\u0005הוא אומר]\u0006 — בסתם, \u0003דדעתיה דתינוק קריבא\u0004 \u0005[שדעתו של התינוק קרובה]\u0006 \u0003לגבי חלב,\u0004 ולכן אין צורך ברצון מפורש כדי לקבל טומאה, \u0003אבל\u0004 אם הוא \u0003אמר\u0004 \u0005[אומר]\u0006 במפורש ש\u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 — הרי החלב \u0003טהור.\u0004","שנינו במשנה: \u0003אכל אוכלין טמאין\u0004 ושתה משקין טמאין, שתה רביעית יין ונכנס למקדש, ושהה כדי אכילת פרס — חייב. ושואלים: \u0003למה לי שהייה\u0004 במקדש כדי להתחייב על כך, \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 \u0003ושהה? אמר רב יהודה, הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003אכל אוכלין טמאין ושתה משקין טמאין ושתה רביעית יין, ושהה באכילתן ובשתייתן כדי אכילת פרס, ו\u0004אחר כך \u0003נכנס למקדש\u0004 — \u0003חייב.\u0004","שנינו במשנה, \u0003ר' אליעזר אומר:\u0004 אם פסק בשתיית רביעית יין, או שנתן לתוכו מים כל שהוא, ונכנס למקדש — פטור. בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר לאהרן הכהן \u0003\"יין ושכר אל תשת\u0004 אתה ובניך בבואכם אל אהל מועד ולא תמותו\" וכו' (ויקרא י, יט), אילו נאמר רק \"יין\" — \u0003יכול אפילו\u0004 שתה יין \u0003כל שהוא,\u0004 יכול \u0003אפילו\u0004 שתה יין \u0003מגתו,\u0004 שעדיין לא תסס, יהא חייב?","\u0003תלמוד לומר: \"ושכר\",\u0004 לומר שאין \u0003אסור אלא\u0004 יין שיש בו \u0003כדי לשכר, וכמה כדי לשכר?\u0004 לפחות \u0003רביעית יין,\u0004 וכן שיהיה זה יין \u0003בן ארבעים יום,\u0004 שכבר תסס.","\u0003אם כן,\u0004 די היה לכתוב \"שכר\", \u0003מה תלמוד לומר \"יין\"? לומר לך, ש\u0004אף שחיוב מיתה אין בו \u0003מוזהרין עליו\u0004 מלשתות אפילו \u0003כל שהוא,\u0004 גם אם אין בו רביעית, \u0003ו\u0004כן \u0003מוזהרין עליו\u0004 אפילו כשהוא \u0003מגתו,\u0004 ולכן יש בכך עונש מלקות, כדין כל \"לא תעשה\" שבתורה.","ר' יהודה אומר: \"\u0003יין\"\u0004 — \u0003אין לי אלא יין\u0004 בלבד, \u0003שאר\u0004 משקים \u0003משכרין מנין? תלמוד לומר: \"ושכר\"; אם כן מה תלמוד לומר \"יין\"? על היין,\u0004 אם נכנס למקדש — בחיוב \u0003מיתה, ועל שאר משקין\u0004 משכרים \u0003באזהרה\u0004 בלבד.","ר' \u0003אליעזר אומר,\u0004 יש להבין את הכתוב \"יין ושכר אל תשת\" כאילו נאמר: \u0003\"יין אל תשת ושכר\",\u0004 וכוונתו: יין \u0003אל תשתהו כדרך שכרותו, הא\u0004 \u0005[אבל]\u0006 \u0003אם הפסיק בו\u0004 בשתייתו, \u0003או נתן לתוכו מים כל שהוא\u0004 ושתהו — \u0003פטור.\u0004","ומסבירים: \u0003במאי פליגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003גמרינן\u0004 \u0005[למדים אנו]\u0006 גזירה שווה \"\u0003שכר\" \"שכר\" מנזיר,\u0004 שנאמר בו: \"מיין ושכר יזיר\" (במדבר ו, ג) ולא נאסר עליו אלא יין, ש\"שכר\" האמור כאן גם הוא יין (מ\u0003שכר).\u0004","\u0003ור' יהודה לא יליף\u0004 \u0005[אינו לומד]\u0006 מגזירה שווה זו של \"\u0003שכר\" \"שכר\" מנזיר,\u0004 ולכן הוא מפרש \"שכר\" במובן של משקה משכר שאינו יין. \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירושו של \"יין ו\u0003שכר\"?\u0004 לא שני דברים שונים, אלא: יין \u0003מידי\u0004 \u0005[כמו,\u0006 כדרך\u0005]\u0006 ש\u0003הוא משכר.\u0004","ואומרים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת אותה\u0006 ברייתא \u0005ששנויה]:\u0006 \u0003אכל דבילה קעילית,\u0004 שגורמת למעין שיכרון, \u0003ו\u0004כן \u0003שתה דבש או חלב,\u0004 ונשתכר, \u0003ונכנס למקדש ושימש\u0004 — \u0003לוקה, כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006\u0003? כ\u0004דעת ר' \u0003יהודה,\u0004 שסבור שעל כל דבר משכר יש אזהרה. \u0003אמר רב יהודה בר אחותאי: הלכה כר' אליעזר,\u0004 ומעירים: \u0003וקרי\u0004 \u0005[וקורא]\u0006 היה \u0003רב עליה\u0004 \u0005[עליו]\u0006 על ר' \u0003אלעזר \"ט ובינא דחכימי\"\u0004 \u0005[המאושר שבחכמים],\u0006 שהלכה כמותו.","מסופר, \u0003רב אחא דהוצל\u0004 (מן העיר הוצל) \u0003הוה נידרא עלה דביתהו\u0004 \u0005[היה נדר על אשתו],\u0006 שנדר שלא ליהנות ממנה, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב אשי\u0004 כדי שיתיר לו את נדרו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל האידנא ותא\u0004 \u0005[לך עכשיו ובוא]\u0006 \u0003למחר,\u0004 כי עכשיו שתיתי יין, ונאסר עלי להורות, שהרי \u0003רב לא\u0004 היה \u0003מוקי אמורא עליה\u0004 \u0005[מעמיד מתורגמן עליו],\u0006 כלומר, לא היה דורש ברבים \u0003מיומא טבא לחבריה\u0004 \u0005[מיום טוב\u0006 אחד, לאחר שאכל ושתה יין, עד \u0005לחבירו,\u0006 למחרת\u0005]\u0006\u0003 משום שכרות,\u0004 מפני שהשותה יין אסור לו להורות, כמבואר להלן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחא, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: הלכה כר' אלעזר,\u0004 שאם נתן מים לתוך היין פטור, \u0003ומר הוא דקא רמי ביה מיא\u0004 \u0005[ואדוני הוא שהטיל בו מים]\u0006 ביין שלו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי, \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שפטור אם נתן בו מים כל שהוא — \u0003ברביעית\u0004 יין בדיוק, \u0003הא\u0004 \u0005[זה]\u0006 \u0003ביותר מכדי רביעית\u0004 יין, שגם אם נתן בתוכו מעט מים עדיין הוא משכר.","בהמשך לאיסור על הכהנים להיכנס למקדש שתויי יין, נאמר: \"ולהבדיל בין הקודש ובין החול ובין הטמא ובין הטהור, ולהורות את בני ישראל את כל החוקים אשר דיבר ה' אליהם ביד משה\" (ויקרא י, י—א), ועל כך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"ולהבדיל בין הקדש ובין החל\"\u0004 — \u0003אלו\u0004 דיני \u0003דמין וערכין,\u0004 ו\u0003חרמין והקדשות,\u0004 שאסור לדון בענייני הקדש כשהוא שתוי יין,","\u0003\"בין הטמא ובין הטהור\"\u0004 — \u0003אלו\u0004 דיני \u0003טמאות וטהרות, \"ולהורת\"\u0004 — \u0003זו הוראה\u0004 באיסור והיתר, \u0003\"את כל החקים\"\u0004 — \u0003אלו מדרשות,\u0004 דרשות הכתובים בענייני הלכה, שאסור ללמדן כשהוא שתוי יין, \u0003\"אשר דבר ה'\"\u0004— \u0003זו הלכה\u0004 למשה מסיני (שניתנה בדיבור ולא בכתב), \u0003\"ביד משה\"\u0004 — \u0003זה תלמוד,\u0004 המשא ומתן של התורה שבעל פה, שיש ממנו מסקנות להלכה,","\u0003יכול אף המשנה\u0004 אסור ללמד? \u0003תלמוד לומר: \"ולהורת\",\u0004 כלומר מדובר פה רק בדבר שיש ממנו הוראת הלכה למעשה, ואין מורים הלכה מן המשנה. \u0003ר' יוסי בר' יהודה אומר: יכול אף תלמוד\u0004 אסור לעסוק בו? \u0003תלמוד לומר: \"ולהורת\",\u0004 דווקא הוראת הלכה למעשה נאסרה, ולא דבר שרק ניתן להסיק ממנו הוראה.","ושואלים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת זו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003יצא\u0004 דין \u0003שרץ,\u0004 להורות שהוא \u0003טמא, וצפרדע,\u0004 להורות שהוא \u0003טהור, ש\u0004אפילו \u0003שתויי יין מורין בהן הוראה, נימא\u0004 \u0005[האם לומר]\u0006 שדעת ר' \u0003יוסי בר' יהודה היא,\u0004 המיקל בענין זה, \u0003ולא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 מותר הדבר. \u0003ושאני הכא\u0004 \u0005[ושונה כאן],\u0006 \u0003דזיל קרי בי רב הוא\u0004 \u0005[ש\"לך קרא בבית הרב\" הוא],\u0006 שאפילו תינוקות של בית רבן יודעים אותו, ואין בו הוראה.","\u0003אמר רב: הלכה כר' יוסי בר' יהודה,\u0004 שכל שאין בו הוראת הלכה למעשה מותר ללמד, למרות שניתן להסיק משם הלכה. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב לא מוקים אמורא מיומא טבא לחבריה\u0004 \u0005[לא\u0006 היה \u0005מעמיד מתורגמן\u0006 לדרשה \u0005מיום טוב אחד לחבירו]\u0006 \u0003משום שכרות!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב, דאורי מורי\u0004 \u0005[שהיה מורה הוראה\u0006 בתוך הדרשה\u0005].\u0006 ואומרים: \u0003וניקם דלא לורי\u0004 \u0005[ושיעמיד\u0006 מתורגמן וידרוש \u0005ולא יורה הוראה]!\u0006 ומשיבים: \u0003כל היכא דיתיב\u0004 \u0005[מקום שיושב]\u0006 \u0003רב\u0004 ודורש \u0003לא סגי ליה\u0004 \u0005[לא יתכן שיהיה]\u0006 \u0003בלא הוראה.\u0004","\u0003יש אוכל אכילה אחת וחייבין עליה ארבעה חטאות ואשם אחד,\u0004 כיצד? \u0003טמא שאכל חלב, והיה\u0004 החלב \u0003נותר, מן המוקדשין,\u0004 ואכלו \u0003ביום הכפורים\u0004 — חייב באכילתו משום חלב, משום נותר, משום טמא שאכל את הקודש, ומשום אכילה ביום הכיפורים, ואשם על המעילה בקודש.","ר' מאיר \u0003אומר: אם היה שבת והוציאו\u0004 בתוך כדי אכילתו מרשות היחיד לרשות הרבים — \u0003חייב. אמרו לו:\u0004 זה \u0003אינו מן השם\u0004 (מן הענין), אין חיוב זה משום אכילה, ולכן אין למנותו."]]};
